INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-001', 'academic performance', '学业表现', 'noun phrase', '6.0', 95, '{"education"}', '{"writing","speaking"}', '{"improve academic performance","outstanding academic performance","decline in academic performance"}', '{"提高学业表现","出色的学业表现","学业表现下滑"}', 'Extracurricular activities can positively influence students'' academic performance.', '课外活动可以对学生的学业表现产生积极影响。', '{"educational achievement","scholastic attainment"}', '{"教育成就","学业成就"}', '{"不能说 study performance，固定搭配是 academic performance"}', 'Writing Task 2: education / parenting topics', '/ˌæk.əˈdem.ɪk pərˈfɔːr.məns/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-002', 'higher education', '高等教育', 'noun phrase', '6.0', 98, '{"education"}', '{"writing","speaking"}', '{"pursue higher education","access to higher education","higher education institution","cost of higher education"}', '{"接受高等教育","获得高等教育的机会","高等教育机构","高等教育成本"}', 'Higher education plays a crucial role in preparing individuals for the competitive job market.', '高等教育在培养个人应对竞争激烈的就业市场方面发挥着关键作用。', '{"tertiary education","university education","post-secondary education"}', '{"第三级教育","大学教育","中学后教育"}', '{"higher education 泛指时前面不加 the"}', 'Writing Task 2: education / government spending; Speaking Part 3: education', '/ˈhaɪ.ər ˌedʒ.ʊˈkeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-003', 'critical thinking', '批判性思维', 'noun phrase', '6.5', 97, '{"education"}', '{"writing","speaking"}', '{"develop critical thinking","foster critical thinking","critical thinking skills","lack of critical thinking"}', '{"培养批判性思维","促进批判性思维","批判性思维能力","缺乏批判性思维"}', 'Schools should focus on developing students'' critical thinking rather than encouraging rote memorization.', '学校应该注重培养学生的批判性思维，而不是鼓励死记硬背。', '{"analytical thinking","logical reasoning","higher-order thinking"}', '{"分析性思维","逻辑推理","独立思考"}', '{"不说 criticize thinking，critical thinking 是固定搭配"}', 'Writing Task 2: education methods / curriculum reform', '/ˈkrɪt.ɪ.kəl ˈθɪŋ.kɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-004', 'lifelong learning', '终身学习', 'noun phrase', '6.0', 95, '{"education"}', '{"writing","speaking"}', '{"promote lifelong learning","embrace lifelong learning","lifelong learning habits","culture of lifelong learning"}', '{"学校课程","课程设计","核心课程","课外活动"}', 'In today''s rapidly changing job market, lifelong learning has become essential for career advancement.', '新课程强调实践技能而非理论知识。', '{"continuous learning","ongoing education","lifelong education"}', '{"教学大纲","课程安排","学习计划"}', '{"lifelong 是一个词，不要分开写成 life long"}', 'Writing Task 2: education / employment; Speaking Part 3: career development', '/kəˈrɪk.jʊ.ləm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-005', 'tuition fees', '学费', 'noun phrase', '5.5', 94, '{"education"}', '{"writing","speaking"}', '{"rising tuition fees","afford tuition fees","tuition fees waiver","cover tuition fees"}', '{"上涨的学费","负担学费","学费减免","支付学费"}', 'Rising tuition fees have made higher education increasingly unaffordable for students from low-income families.', '不断上涨的学费使许多学生难以负担高等教育。', '{"tuition costs","school fees","educational expenses"}', '{"学费成本","学杂费","教育支出"}', '{"tuition 本身就有学费的意思，不要说 tuition fee costs"}', 'Writing Task 2: education funding / government policy; Speaking Part 3', '/ˈped.ə.ɡɒdʒ.i/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-006', 'vocational training', '职业培训', 'noun phrase', '6.0', 93, '{"education"}', '{"writing","speaking"}', '{"provide vocational training","vocational training program","vocational training center","undergo vocational training"}', '{"识字率","数字素养","读写能力","金融素养"}', 'Vocational training equips young people with practical skills that are directly applicable in the workplace.', '读写能力是教育发展和经济赋权的基础。', '{"career training","technical education","professional training"}', '{"读写能力","识字","文化水平"}', '{"vocational 发音 /vəʊˈkeɪʃənl/，重音在第二个音节"}', 'Writing Task 2: employment / education policy; Speaking Part 3', '/ˈlɪt.ər.ə.si/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-007', 'compulsory education', '义务教育', 'noun phrase', '6.0', 92, '{"education"}', '{"writing","speaking"}', '{"compulsory education law","nine-year compulsory education","complete compulsory education","beyond compulsory education"}', '{"义务教育法","九年义务教育","完成义务教育","超出义务教育"}', 'In most countries, children are legally required to complete at least nine years of compulsory education.', '义务教育确保每个儿童都能接受基础教育。', '{"mandatory education","obligatory schooling","statutory schooling"}', '{"强制教育","义务学校教育","法定教育"}', '{"compulsory 是法律强制的，mandatory 更口语化但可互换"}', 'Writing Task 2: government policy / education', '/kəmˈpʌl.sər.i ˌedʒ.ʊˈkeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-008', 'study abroad', '留学', 'verb phrase', '5.5', 98, '{"education"}', '{"speaking","writing"}', '{"choose to study abroad","study abroad experience","study abroad program","opportunity to study abroad"}', '{"选择出国留学","留学经历","留学项目","出国留学机会"}', 'Studying abroad exposes students to different cultures and broadens their horizons.', '出国留学为学生提供了体验不同文化和教育体系的机会。', '{"pursue overseas education","attend foreign universities","international study"}', '{"海外求学","就读国外大学","国际学习"}', '{"study abroad 中间没有 in/at，不要说 study in abroad"}', 'Speaking Part 1/2: personal experience; Writing Task 2: education / culture', '/stʌd əˈbrɔːd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-009', 'extracurricular activities', '课外活动', 'noun phrase', '6.0', 91, '{"education"}', '{"speaking","writing"}', '{"participate in extracurricular activities","extracurricular activities program","engage in extracurricular activities","variety of extracurricular activities"}', '{"参加课外活动","课外活动项目","参与课外活动","丰富多样的课外活动"}', 'Participating in extracurricular activities helps students develop teamwork and leadership skills.', '学生通过参与课外活动来培养课堂之外的技能。', '{"after-school activities","co-curricular activities","enrichment activities"}', '{"课后活动","辅助课程活动","拓展活动"}', '{"extracurricular 拼写注意：extra + curricular，两个 r"}', 'Writing Task 2: holistic education; Speaking Part 1: school life', '/ˌek.strə.kəˈrɪk.jʊ.lər ækˈtɪv.ə.tiz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-010', 'educational system', '教育体系', 'noun phrase', '6.0', 96, '{"education"}', '{"writing","speaking"}', '{"reform the educational system","educational system faces challenges","flaws in the educational system","outdated educational system"}', '{"改革教育体系","教育体系面临挑战","教育体系的缺陷","过时的教育体系"}', 'The educational system should be reformed to meet the demands of the 21st-century economy.', '改革教育体系需要政策制定者、教师和家长的共同努力。', '{"education system","school system","schooling system"}', '{"教育系统","学校体系","教育制度"}', '{"educational system 和 education system 可互换，后者更常用"}', 'Writing Task 2: education policy; Speaking Part 3: education', '/ˌedʒ.ʊˈkeɪ.ʃən.əl ˈsɪs.təm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-011', 'formal education', '正规教育', 'noun phrase', '6.0', 99, '{"education"}', '{"writing","speaking"}', '{"complete formal education","access to formal education","formal education system","beyond formal education"}', '{"完成正规教育","获得正规教育的机会","正规教育体系","超出正规教育"}', 'Many successful entrepreneurs achieved remarkable success without completing formal education.', '正规教育为个人提供了系统化的知识获取途径。', '{"mainstream education","structured education","institutional education"}', '{"主流教育","结构化教育","体制教育"}', '{"formal education 前面通常不加 the"}', 'Writing Task 2: education / career success; Speaking Part 3', '/ˈfɔːr.məl ˌedʒ.ʊˈkeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-012', 'teaching methodology', '教学方法', 'noun phrase', '6.5', 92, '{"education"}', '{"writing","reading"}', '{"innovative teaching methodology","traditional teaching methodology","adopt new teaching methodology","effective teaching methodology"}', '{"创新教学方法","传统教学方法","采用新教学方法","有效的教学方法"}', 'Modern teaching methodology emphasizes student-centered learning over teacher-centered instruction.', '教师需要根据学生需求不断更新和改进自己的教学方法。', '{"teaching approach","pedagogical method","instructional strategy"}', '{"教学方式","教育方法","教学策略"}', '{"methodology 强调整套体系，method 指具体方法，不可混用"}', 'Writing Task 2: education reform; Reading: pedagogy articles', '/ˈtiː.tʃɪŋ ˌmeθ.əˈdɒl.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-013', 'student engagement', '学生参与度', 'noun phrase', '6.5', 90, '{"education"}', '{"writing","reading"}', '{"increase student engagement","level of student engagement","promote student engagement","measure student engagement"}', '{"提高学生参与度","学生参与度水平","促进学生参与度","衡量学生参与度"}', 'Interactive teaching methods have been shown to significantly improve student engagement in the classroom.', '学生参与度是预测学习成果的重要指标之一。', '{"student participation","student involvement","learner engagement"}', '{"学生参与","学生投入","学习者参与"}', '{"engagement 是参与/投入，不要说 student engagement rate"}', 'Reading: educational research; Writing Task 2: teaching methods', '/ˈstjuː.dənt ɪnˈɡeɪdʒ.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-014', 'learning outcome', '学习成果', 'noun phrase', '6.5', 93, '{"education"}', '{"writing","reading"}', '{"improve learning outcomes","measure learning outcomes","desired learning outcomes","assess learning outcomes"}', '{"改善学习成果","衡量学习成果","期望的学习成果","评估学习成果"}', 'Technology in the classroom can enhance learning outcomes when integrated effectively.', '有效的教学策略可以显著改善学生的学习成果。', '{"educational outcome","learning result","academic outcome"}', '{"教育成果","学习结果","学业成果"}', '{"outcome 常用复数 outcomes 更自然"}', 'Writing Task 2: education technology; Reading: academic journals', '/ˈlɜː.nɪŋ ˈaʊt.kʌmz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-015', 'academic qualification', '学历', 'noun phrase', '6.0', 90, '{"education"}', '{"writing","reading"}', '{"obtain academic qualifications","recognized academic qualification","minimum academic qualification","academic qualification requirement"}', '{"获得学历资格","认可的学历资格","最低学历要求","学历资格要求"}', 'While academic qualifications are important, employers increasingly value practical experience and soft skills.', '学术资格证书是许多职业的基本入职门槛。', '{"educational credentials","academic degree","formal qualification"}', '{"学历证书","学术学位","正式资格"}', '{"qualification 表示学历时可数，常用复数 qualifications"}', 'Writing Task 2: job market; Reading: employment / education articles', '/ˌæk.əˈdem.ɪk ˌkwɒl.ɪ.fɪˈkeɪ.ʃənz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-016', 'education reform', '教育改革', 'noun phrase', '6.0', 91, '{"education"}', '{"writing","speaking"}', '{"implement education reform","comprehensive education reform","education reform policy","call for education reform"}', '{"检测抄袭","学术抄袭","抄袭检查工具","避免抄袭"}', 'Education reform is urgently needed to equip students with 21st-century skills such as digital literacy.', '许多大学使用专门的软件来检测学生作业中的抄袭行为。', '{"educational reform","school reform","curriculum reform"}', '{"剽窃","学术抄袭","学术不端"}', '{"reform 作不可数名词指改革过程；reforms (复数) 指具体改革措施"}', 'Writing Task 2: government policy / education', '/ˈpleɪ.dʒər.ɪ.zəm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-017', 'peer pressure', '同侪压力', 'noun phrase', '6.0', 90, '{"education"}', '{"speaking","writing"}', '{"succumb to peer pressure","negative peer pressure","cope with peer pressure","influence of peer pressure"}', '{"获得奖学金","奖学金申请","学术奖学金","全额奖学金"}', 'Teenagers often engage in risky behaviors due to intense peer pressure from their social circles.', '她凭借出色的学业成绩获得了一所顶尖大学的奖学金。', '{"peer influence","social pressure","group pressure"}', '{"奖学金","助学金","学术资助"}', '{"peer 指同龄人，不要说 peer''s pressure"}', 'Speaking Part 2/3: teenage issues; Writing Task 2: education / parenting', '/ˈskɒl.ə.ʃɪp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-018', 'learning environment', '学习环境', 'noun phrase', '6.0', 91, '{"education"}', '{"writing","reading"}', '{"conducive learning environment","supportive learning environment","create a positive learning environment","inclusive learning environment"}', '{"支付学费","高额学费","学费上涨","学费减免"}', 'A supportive learning environment is essential for students to reach their full potential.', '学费上涨使得许多学生难以负担高等教育。', '{"educational environment","study environment","academic setting"}', '{"学杂费","教育费用","学费支出"}', '{"conducive to learning 固定搭配，介词用 to 不用 for"}', 'Writing Task 2: school infrastructure; Reading: educational psychology', '/tjuːˈɪʃ.ən fiːz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-019', 'academic achievement', '学业成就', 'noun phrase', '6.0', 94, '{"education"}', '{"writing","reading"}', '{"measure academic achievement","improve academic achievement","academic achievement gap","outstanding academic achievement"}', '{"衡量学业成绩","提高学业成绩","学业成绩差距","出色的学业成绩"}', 'Parental involvement plays a crucial role in shaping children''s academic achievement.', '衡量学业成绩不仅仅依赖于考试成绩。', '{"educational attainment","scholastic achievement","academic success"}', '{"教育成就","学术成就","学业成功"}', '{"achievement 作成就时可数也可不可数，看语境"}', 'Writing Task 2: education / parenting; Reading: education studies', '/əˈtʃiːv.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-020', 'educational opportunity', '教育机会', 'noun phrase', '6.0', 94, '{"education"}', '{"writing","speaking"}', '{"equal educational opportunity","expand educational opportunities","access to educational opportunities","limited educational opportunity"}', '{"入学人数","招生过程","注册入学","入学率"}', 'Online learning platforms have expanded educational opportunities for students in remote regions.', '过去十年间，大学入学人数显著增加。', '{"learning opportunity","access to education","educational access"}', '{"注册","入学","招生"}', '{"opportunity 后接 for + noun 或 to + verb，不要混淆"}', 'Writing Task 2: education equality; Speaking Part 3', '/ɪnˈrəʊl.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-021', 'cognitive development', '认知发展', 'noun phrase', '6.5', 85, '{"education"}', '{"reading","writing"}', '{"promote cognitive development","cognitive development theory","early cognitive development","stage of cognitive development"}', '{"促进认知发展","认知发展理论","早期认知发展","认知发展阶段"}', 'Reading to children from an early age significantly promotes their cognitive development and language skills.', '早期儿童教育对认知发展有显著影响。', '{"intellectual development","mental development","cognitive growth"}', '{"智力发展","心理发展","认知成长"}', '{"cognitive 发音 /ˈkɒɡnɪtɪv/，g 不发音"}', 'Reading: child development articles; Writing Task 2: early education', '/ˈkɒɡ.nə.tɪv dɪˈvel.əp.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-022', 'rote memorization', '死记硬背', 'noun phrase', '6.0', 82, '{"education"}', '{"writing","speaking"}', '{"rely on rote memorization","discourage rote memorization","rote memorization approach","beyond rote memorization"}', '{"出勤率","强制出勤","记录出勤","缺勤"}', 'Traditional exam-oriented education often places too much emphasis on rote memorization rather than understanding.', '定期出勤与学业成绩的提高密切相关。', '{"rote learning","mechanical memorization","learning by heart"}', '{"出勤","到课","参与度"}', '{"rote 拼写注意不是 wrote；rote 指机械重复"}', 'Writing Task 2: exam-oriented education; Speaking Part 3: learning styles', '/əˈten.dəns/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-023', 'scholarship program', '奖学金项目', 'noun phrase', '5.5', 80, '{"education"}', '{"reading","listening"}', '{"apply for a scholarship program","award a scholarship program","merit-based scholarship program","fully-funded scholarship program"}', '{"申请奖学金项目","授予奖学金","基于成绩的奖学金","全额资助奖学金"}', 'The university offers a range of scholarship programs to attract talented international students.', '她通过优异的成绩获得了全额资助的奖学金项目。', '{"financial aid program","bursary scheme","grant program","fellowship"}', '{"助学金项目","助学金计划","资助项目","奖学金"}', '{"scholarship 指奖学金，bursary 更多指助学金，不要混淆"}', 'Listening Section 3: campus conversation; Reading: university brochures', '/ˈskɒl.ə.ʃɪp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-024', 'literacy rate', '识字率', 'noun phrase', '6.0', 83, '{"education"}', '{"writing","reading"}', '{"improve literacy rate","adult literacy rate","high literacy rate","national literacy rate"}', '{"参加研讨会","研讨会讨论","举办研讨会","研讨会系列"}', 'Developing countries have made significant progress in improving literacy rates over the past few decades.', '小型研讨会鼓励学生积极参与课堂讨论。', '{"reading proficiency","literate population rate","educational attainment indicator"}', '{"研讨课","专题讨论","研讨班"}', '{"literacy 是不可数名词；表示识字率用 literacy rate"}', 'Writing Task 1/2: development indicators; Reading: social science', '/ˈsem.ɪ.nɑːr/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-025', 'academic integrity', '学术诚信', 'noun phrase', '6.5', 78, '{"education"}', '{"reading","writing"}', '{"uphold academic integrity","violation of academic integrity","academic integrity policy","maintain academic integrity"}', '{"辅导课程","一对一辅导","辅导材料","在线教程"}', 'Universities must enforce strict policies to uphold academic integrity and prevent plagiarism.', '辅导课程为学生提供了在小组环境中提问的机会。', '{"intellectual honesty","scholarly integrity","academic honesty"}', '{"辅导课","指导课","个别指导"}', '{"integrity 是不可数名词，不用复数形式"}', 'Reading: university policies; Writing Task 2: education standards', '/tjuːˈtɔː.ri.əl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-026', 'dropout rate', '辍学率', 'noun phrase', '5.5', 81, '{"education"}', '{"writing","speaking"}', '{"high dropout rate","reduce dropout rate","school dropout rate","college dropout rate"}', '{"撰写论文","博士论文","论文答辩","提交论文"}', 'The high dropout rate in rural areas is primarily caused by poverty and lack of educational resources.', '她花了两年时间进行实地研究才完成博士论文。', '{"attrition rate","non-completion rate","withdrawal rate"}', '{"学位论文","博士论文","学术论文"}', '{"dropout 可以连写也可以写 drop-out，但 drop out 是动词"}', 'Writing Task 1/2: education data; Speaking Part 3: social issues', '/ˌdɪs.əˈteɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-027', 'educational resources', '教育资源', 'noun phrase', '6.0', 84, '{"education"}', '{"writing","speaking"}', '{"allocate educational resources","lack of educational resources","equal distribution of educational resources","digital educational resources"}', '{"硕士论文","论文陈述","论文研究","论文指导"}', 'The unequal distribution of educational resources between urban and rural areas remains a pressing issue.', '他的硕士论文探讨了社交媒体对青少年心理健康的影响。', '{"learning resources","teaching resources","academic resources"}', '{"毕业论文","学位论文","研究论文"}', '{"resources 表示资源时通常用复数"}', 'Writing Task 2: education equality; Speaking Part 3', '/ˈθiː.sɪs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-028', 'classroom interaction', '课堂互动', 'noun phrase', '5.5', 77, '{"education"}', '{"listening","speaking"}', '{"encourage classroom interaction","facilitate classroom interaction","meaningful classroom interaction","classroom interaction patterns"}', '{"本科生","本科课程","本科教育","本科学位"}', 'Teachers should encourage more classroom interaction to help students develop communication skills.', '本科阶段为学生提供了广泛的通识教育基础。', '{"classroom participation","student-teacher interaction","class engagement"}', '{"大学本科生","学士生","本科学生"}', '{"interaction 后可跟 between 或 with，根据语境选择"}', 'Listening Section 3: academic discussion; Speaking Part 2: school experience', '/ˌʌn.dəˈɡrædʒ.u.ət/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-029', 'hands-on experience', '实践经验', 'noun phrase', '6.0', 79, '{"education"}', '{"speaking","writing"}', '{"gain hands-on experience","valuable hands-on experience","provide hands-on experience","practical hands-on experience"}', '{"研究生","研究生课程","研究生学习","研究生学位"}', 'Internships provide students with valuable hands-on experience that cannot be gained in the classroom.', '研究生学习通常需要更深入的独立研究和专业方向。', '{"practical experience","real-world experience","experiential learning"}', '{"研究生","硕士生","博士生"}', '{"hands-on 是形容词，注意连字符；没有连字符的 hands on 是动词短语"}', 'Speaking Part 2: work/study experience; Writing Task 2: education', '/ˌpəʊstˈɡrædʒ.u.ət/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-030', 'standardized testing', '标准化考试', 'noun phrase', '6.0', 80, '{"education"}', '{"writing","reading"}', '{"rely on standardized testing","criticism of standardized testing","standardized testing system","performance on standardized tests"}', '{"攻读博士学位","获得博士学位","博士学位课程","荣誉博士"}', 'Critics argue that standardized testing fails to measure creativity and critical thinking abilities.', '获得博士学位需要在特定领域做出原创性的研究贡献。', '{"standardized assessment","uniform testing","norm-referenced testing"}', '{"博士","博士头衔","最高学位"}', '{"standardized 是美式拼写，英式为 standardised"}', 'Writing Task 2: education assessment; Reading: education policy', '/ˈdɒk.tər.ət/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-031', 'academic research', '学术研究', 'noun phrase', '6.0', 82, '{"education"}', '{"reading","writing"}', '{"conduct academic research","peer-reviewed academic research","academic research paper","academic research findings"}', '{"校友网络","校友会","校友捐赠","校友聚会"}', 'Government funding for academic research is essential for scientific and technological progress.', '强大的校友网络可以为毕业生提供宝贵的职业发展机会。', '{"scholarly research","scientific investigation","academic inquiry"}', '{"校友","毕业生","旧生"}', '{"research 是不可数名词，不说 a research，可说 a piece of research"}', 'Reading: academic journals; Writing Task 2: science / education', '/əˈlʌm.naɪ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-032', 'educational background', '教育背景', 'noun phrase', '5.5', 76, '{"education"}', '{"speaking","listening"}', '{"academic and educational background","diverse educational background","educational background information","regardless of educational background"}', '{"教职工","学院","教师团队","系"}', 'Applicants from diverse educational backgrounds bring unique perspectives to the program.', '该大学拥有一支经验丰富的国际化学术教师队伍。', '{"academic background","educational history","academic upbringing"}', '{"院系","教学人员","教职员"}', '{"background 在此语境下为可数名词，可以说 different backgrounds"}', 'Speaking Part 2: self-introduction; Listening Section 1: application forms', '/ˈfæk.əl.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-033', 'tertiary education', '高等教育', 'noun phrase', '6.5', 84, '{"education"}', '{"writing","reading"}', '{"enroll in tertiary education","access to tertiary education","tertiary education sector","tertiary education institution"}', '{"课程大纲","考试大纲","教学大纲","更新教学大纲"}', 'Investing in tertiary education is crucial for a nation''s long-term economic competitiveness.', '课程大纲概述了学生将在整个学期学习的所有主题。', '{"higher education","post-secondary education","college education"}', '{"教学大纲","课程纲要","教学计划"}', '{"tertiary 是正式用词，IELTS Writing 中比 higher education 更正式"}', 'Writing Task 2: education policy; Reading: academic reports', '/ˈsɪl.ə.bəs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-034', 'academic excellence', '学术卓越', 'noun phrase', '6.5', 75, '{"education"}', '{"reading","writing"}', '{"strive for academic excellence","pursue academic excellence","academic excellence award","standard of academic excellence"}', '{"课程表","考试时间表","安排时间表","修订时间表"}', 'The school has built a reputation for academic excellence over the past three decades.', '学校在学期开始前公布课程时间表。', '{"scholastic excellence","educational excellence","academic distinction"}', '{"课表","日程表","时间安排"}', '{"excellence 是不可数名词，不说 an excellence"}', 'Reading: school profiles; Writing Task 2: education quality', '/ˈtaɪmˌteɪ.bəl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-035', 'student enrollment', '入学人数', 'noun phrase', '5.5', 78, '{"education"}', '{"listening","reading"}', '{"increase in student enrollment","declining student enrollment","student enrollment figures","total student enrollment"}', '{"成绩单","官方成绩单","申请成绩单","学术成绩单"}', 'The university has seen a steady increase in student enrollment since introducing its online programs.', '申请研究生院时通常需要提交正式的本科成绩单。', '{"student admission","registration numbers","pupil intake"}', '{"成绩报告","学业记录","成绩证明"}', '{"enrollment 美式拼写；英式是 enrolment"}', 'Listening Section 3: campus statistics; Reading: university reports', '/ˈtræn.skrɪpt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-036', 'intellectual development', '智力发展', 'noun phrase', '6.5', 73, '{"education"}', '{"reading","listening"}', '{"support intellectual development","intellectual development of children","stimulate intellectual development","intellectual development theories"}', '{"平均绩点","高绩点","计算绩点","绩点要求"}', 'Play-based learning has been proven to support the intellectual development of young children.', '许多雇主在筛选应届毕业生简历时会将平均绩点作为参考指标。', '{"cognitive development","mental growth","intellectual growth"}', '{"GPA","平均分","成绩均值"}', '{"intellectual 作形容词时重音在第三音节 /ˌɪntɪˈlektʃuəl/"}', 'Reading: child psychology; Listening Section 4: education lecture', '/ɡreɪd pɔɪnt ˈæv.ər.ɪdʒ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-037', 'academic discipline', '学科', 'noun phrase', '6.0', 74, '{"education"}', '{"reading","writing"}', '{"core academic discipline","across academic disciplines","various academic disciplines","traditional academic discipline"}', '{"学年","学年开始","整个学年","学年结束"}', 'Interdisciplinary research that bridges multiple academic disciplines is becoming increasingly common.', '大多数学术机构从九月到次年六月为一个学年。', '{"field of study","subject area","scholarly discipline"}', '{"学年度","教学年","校历年度"}', '{"discipline 表示学科；也表示纪律，根据语境区分"}', 'Reading: curriculum documents; Writing Task 2: higher education', '/ˌæk.əˈdem.ɪk jɪər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-038', 'educational attainment', '教育程度', 'noun phrase', '6.5', 71, '{"education"}', '{"writing","reading"}', '{"level of educational attainment","high educational attainment","educational attainment gap","measure educational attainment"}', '{"秋季学期","春季学期","学期末","学期制"}', 'There is a strong correlation between educational attainment and lifetime earnings.', '每个学期通常持续约15周，包括考试周。', '{"educational achievement","academic attainment","education level"}', '{"学期","半学年","学季"}', '{"attainment 常作不可数名词，偶尔可数"}', 'Writing Task 1/2: social data; Reading: sociology articles', '/sɪˈmes.tər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-039', 'learning curve', '学习曲线', 'noun phrase', '6.0', 68, '{"education"}', '{"speaking","listening"}', '{"steep learning curve","manageable learning curve","learning curve theory","overcome the learning curve"}', '{"学期","期中考试","学期论文","学期结束"}', 'Learning a new language has a steep learning curve at first, but it becomes easier with consistent practice.', '学生在每个学期结束时参加期末考试。', '{"learning trajectory","skill acquisition rate","adaptation period"}', '{"学期","学段","教学期"}', '{"steep learning curve 表示初始很难学，不是曲线本身陡峭"}', 'Speaking Part 2: learning experience; Listening Section 3: student discussion', '/tɜːm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-040', 'formative assessment', '形成性评价', 'noun phrase', '6.5', 65, '{"education"}', '{"reading","writing"}', '{"conduct formative assessment","formative assessment strategies","formative vs summative assessment","ongoing formative assessment"}', '{"校园生活","大学校园","校园设施","住在校园"}', 'Formative assessment provides continuous feedback that helps students improve throughout the learning process.', '现代化的校园设施为学生的学习和生活提供了全面的支持。', '{"continuous assessment","ongoing evaluation","diagnostic assessment"}', '{"校园","校区","大学园区"}', '{"formative 与 summative 相对，前者关注过程，后者关注结果"}', 'Reading: education methodology; Writing Task 2: assessment methods', '/ˈkæm.pəs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-041', 'educational equity', '教育公平', 'noun phrase', '6.5', 66, '{"education"}', '{"writing","speaking"}', '{"promote educational equity","ensure educational equity","educational equity policy","issue of educational equity"}', '{"学生宿舍","住在宿舍","宿舍生活","宿舍楼"}', 'Ensuring educational equity remains one of the biggest challenges facing developing nations.', '住在学校宿舍有助于新生更快地适应大学生活。', '{"education equality","equal access to education","fairness in education"}', '{"学生公寓","集体宿舍","住宿楼"}', '{"equity（公平/公正）与 equality（平等）不同；equity 关注结果公平"}', 'Writing Task 2: social justice / education; Speaking Part 3', '/ˈdɔːr.mɪ.tər.i/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-042', 'boarding school', '寄宿学校', 'noun phrase', '5.5', 64, '{"education"}', '{"listening","speaking"}', '{"attend a boarding school","boarding school education","traditional boarding school","boarding school experience"}', '{"科学实验室","实验室设备","实验室研究","语言实验室"}', 'Some parents believe that boarding school education fosters independence and self-discipline in children.', '新建的科学实验室配备了最先进的研究设备。', '{"residential school","dormitory school","live-in school"}', '{"实验室","研究室","实验中心"}', '{"boarding school 是寄宿制学校；boarding pass 是登机牌，不要混淆"}', 'Listening Section 3: student discussion; Speaking Part 1: school life', '/ləˈbɒr.ə.tər.i/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-043', 'self-directed learning', '自主学习', 'noun phrase', '6.0', 69, '{"education"}', '{"reading","speaking"}', '{"encourage self-directed learning","self-directed learning skills","independent and self-directed learning","promote self-directed learning"}', '{"大学图书馆","图书馆资源","数字图书馆","图书馆服务"}', 'Online courses require strong self-directed learning skills as there is minimal teacher supervision.', '大学图书馆提供丰富的学术资源和安静的学习空间。', '{"autonomous learning","self-paced study","independent learning"}', '{"图书馆","图书室","资料中心"}', '{"self-directed 有连字符，不要写成 self directed"}', 'Reading: education technology; Speaking Part 2: study habits', '/ˈlaɪ.brər.i/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-044', 'intellectual curiosity', '求知欲', 'noun phrase', '6.5', 62, '{"education"}', '{"reading","speaking"}', '{"spark intellectual curiosity","nurture intellectual curiosity","intellectual curiosity and creativity","natural intellectual curiosity"}', '{"购买教材","教科书内容","数字教科书","参考书"}', 'Great teachers know how to spark intellectual curiosity in their students through engaging lessons.', '教科书仍然是大多数课程的核心学习材料。', '{"inquisitiveness","thirst for knowledge","curiosity to learn"}', '{"教材","教科书","课本"}', '{"curiosity 是不可数名词，不说 a curiosity（除非表示奇物）"}', 'Reading: education philosophy; Speaking Part 2: teachers', '/ˈtekst.bʊk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-045', 'mixed-ability class', '混合能力班', 'noun phrase', '6.0', 58, '{"education"}', '{"reading","listening"}', '{"teach a mixed-ability class","mixed-ability class challenges","in a mixed-ability class","manage mixed-ability classes"}', '{"撰写简历","提交简历","简历格式","更新简历"}', 'Teaching a mixed-ability class requires differentiated instruction to meet every student''s needs.', '一份精心撰写的简历对于求职和学术申请都至关重要。', '{"heterogeneous class","multi-level class","mixed-level group"}', '{"个人简历","履历表","CV"}', '{"mixed-ability 有连字符；ability 不要拼成 abilty"}', 'Reading: teaching methodology; Listening Section 3: teacher discussion', '/kəˌrɪk.jʊ.ləm ˈviː.taɪ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-046', 'academic pressure', '学业压力', 'noun phrase', '5.5', 67, '{"education"}', '{"speaking","writing"}', '{"intense academic pressure","cope with academic pressure","under academic pressure","mounting academic pressure"}', '{"学术资格","专业资格","获得资格","资格认证"}', 'Many students suffer from anxiety and depression due to intense academic pressure from parents and schools.', '雇主越来越重视实践经验和学历资格的结合。', '{"study pressure","educational stress","examination pressure"}', '{"学历","资质","资历认证"}', '{"pressure 是不可数名词，不说 a pressure"}', 'Speaking Part 2/3: student life; Writing Task 2: education / mental health', '/ˌkwɒl.ɪ.fɪˈkeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-047', 'learning disability', '学习障碍', 'noun phrase', '6.0', 55, '{"education"}', '{"reading","listening"}', '{"diagnosed with a learning disability","students with learning disabilities","specific learning disability","overcome learning disabilities"}', '{"获得证书","毕业证书","证书课程","资格证书"}', 'Students with learning disabilities require tailored support to succeed in mainstream education.', '完成该课程后，学生将获得行业内认可的证书。', '{"learning difficulty","learning disorder","special educational needs"}', '{"证书","证明","结业证"}', '{"disability 可数；learning disability 比 learning difficulty 更正式/医学"}', 'Reading: special education; Listening Section 4: psychology lecture', '/sərˈtɪf.ɪ.kət/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-048', 'educational philosophy', '教育理念', 'noun phrase', '6.5', 60, '{"education"}', '{"reading","writing"}', '{"educational philosophy emphasizes","progressive educational philosophy","adopt an educational philosophy","traditional educational philosophy"}', '{"获得文凭","高等教育文凭","文凭课程","研究生文凭"}', 'Montessori''s educational philosophy emphasizes hands-on learning and self-directed activity.', '该文凭课程为学生提供了进入职场所需的实用技能。', '{"teaching philosophy","pedagogical approach","educational ideology"}', '{"毕业文凭","学位证书","结业证书"}', '{"philosophy 在此语境中是可数的，可以说 a philosophy of education"}', 'Reading: education theory; Writing Task 2: education approaches', '/dɪˈpləʊ.mə/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-049', 'academic advisor', '学业导师', 'noun phrase', '5.5', 63, '{"education"}', '{"listening","speaking"}', '{"meet with an academic advisor","seek advice from an academic advisor","assigned academic advisor","academic advisor appointment"}', '{"与学术导师会面","向学术导师寻求建议","指派的学术导师","学术导师约见"}', 'Students should regularly meet with their academic advisor to discuss their course selection and career plans.', '学术导师帮助学生规划课程选择并为职业道路提供建议。', '{"faculty advisor","tutor","academic counselor","academic mentor"}', '{"院系导师","辅导教师","学术顾问","学业指导"}', '{"advisor 美式拼写；英式为 adviser，IELTS 两种都接受"}', 'Listening Section 3: campus services; Speaking Part 1: university life', '/ˌæk.əˈdem.ɪk ədˈvaɪ.zər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('edu-050', 'educational subsidy', '教育补贴', 'noun phrase', '6.0', 57, '{"education"}', '{"writing","reading"}', '{"government educational subsidy","receive an educational subsidy","educational subsidy program","provide educational subsidies"}', '{"硕士学位","攻读硕士","硕士课程","硕士论文"}', 'Government educational subsidies can help bridge the gap between rich and poor students.', '攻读硕士学位可以帮助学生在特定领域深化专业知识和研究能力。', '{"education grant","tuition subsidy","financial aid"}', '{"研究生学位","硕士学历","研究生"}', '{"subsidy 可数，复数 subsidies；注意拼写不是 subside"}', 'Writing Task 2: government spending; Reading: policy reports', '/ˈmɑː.stər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-001', 'environmental protection', '环境保护', 'noun phrase', '6.0', 96, '{"environment"}', '{"writing","speaking"}', '{"environmental protection measures","environmental protection agency","prioritize environmental protection"}', '{"环境保护措施","环境保护机构","优先考虑环境保护"}', 'Governments should invest more in environmental protection to combat climate change.', '环境保护措施对于实现可持续发展目标至关重要。', '{"conservation","eco-protection","environmental conservation"}', '{"自然保护","生态保护","环境保育"}', '{"不能说 protect environment，要加 the → protect the environment"}', 'Writing Task 2: government / environment topics', '/ɪnˌvaɪ.rənˈmen.təl prəˈtek.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-002', 'climate change', '气候变化', 'noun phrase', '6.0', 99, '{"environment"}', '{"writing","speaking"}', '{"combat climate change","tackle climate change","impact of climate change","climate change adaptation"}', '{"控制全球变暖","导致全球变暖","全球变暖效应","减缓全球变暖"}', 'Climate change poses an unprecedented threat to ecosystems and human societies around the world.', '全球变暖正导致极地冰盖以前所未有的速度融化。', '{"global warming","climatic change","climate crisis"}', '{"地球变暖","气温上升","全球变热"}', '{"climate change 是更综合的说法，global warming 是其中一个方面"}', 'Writing Task 2: environment; Speaking Part 3: global issues', '/ˌɡləʊ.bəl ˈwɔːr.mɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-003', 'carbon footprint', '碳足迹', 'noun phrase', '6.5', 96, '{"environment"}', '{"writing","speaking"}', '{"reduce carbon footprint","measure carbon footprint","carbon footprint reduction","individual carbon footprint"}', '{"减少碳足迹","测量碳足迹","个人碳足迹","碳足迹计算器"}', 'Switching to renewable energy sources is one of the most effective ways to reduce our carbon footprint.', '减少碳足迹是每个人都可以为环境保护做出的贡献。', '{"carbon emissions","greenhouse gas emissions","environmental footprint"}', '{"碳排放量","碳排量","温室气体排放"}', '{"footprint 此处是比喻义，不说 carbon footmark"}', 'Writing Task 2: environment / lifestyle; Speaking Part 3', '/ˈkɑːr.bən ˈfʊt.prɪnt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-004', 'renewable energy', '可再生能源', 'noun phrase', '6.0', 97, '{"environment"}', '{"writing","speaking"}', '{"invest in renewable energy","renewable energy sources","shift to renewable energy","renewable energy technology"}', '{"温室效应","加剧温室效应","温室气体","温室效应导致"}', 'Governments should provide incentives for businesses to invest in renewable energy sources such as solar and wind power.', '温室效应虽然是一种自然现象，但人类活动使其大大加剧。', '{"clean energy","green energy","sustainable energy","alternative energy"}', '{"温室现象","大气保温效应","增温效应","「alternative energy」的中文释义"}', '{"renewable 发音 /rɪˈnjuːəbəl/，注意重音在第二个音节"}', 'Writing Task 2: energy / environment; Speaking Part 3', '/ˈɡriːn.haʊs ɪˈfekt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-005', 'sustainable development', '可持续发展', 'noun phrase', '6.5', 98, '{"environment"}', '{"writing","speaking"}', '{"achieve sustainable development","promote sustainable development","sustainable development goals","path to sustainable development"}', '{"开发可再生能源","转向可再生能源","可再生能源技术","推广可再生能源"}', 'Balancing economic growth with environmental protection is at the heart of sustainable development.', '投资可再生能源是摆脱对化石燃料依赖的关键一步。', '{"sustainability","balanced development","green growth"}', '{"清洁能源","可持续能源","绿色能源"}', '{"sustainable 形容词形式，sustainability 是名词形式，用法不同"}', 'Writing Task 2: economy vs environment; Speaking Part 3', '/rɪˈnjuː.ə.bəl ˈen.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-006', 'fossil fuels', '化石燃料', 'noun phrase', '6.0', 95, '{"environment"}', '{"writing","speaking"}', '{"dependence on fossil fuels","burning fossil fuels","phase out fossil fuels","reliance on fossil fuels"}', '{"燃烧化石燃料","依赖化石燃料","化石燃料消耗","替代化石燃料"}', 'Our heavy dependence on fossil fuels is the primary driver of global carbon emissions.', '过度依赖化石燃料是造成空气污染和气候问题的主要原因。', '{"non-renewable fuels","conventional fuels","hydrocarbon fuels"}', '{"矿物燃料","石化燃料","传统能源"}', '{"fossil 拼写注意两个 s；fuels 通常用复数"}', 'Writing Task 2: energy policy; Speaking Part 3: environment', '/ˈfɒs.əl fjuːəlz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-007', 'greenhouse gas', '温室气体', 'noun phrase', '6.0', 94, '{"environment"}', '{"writing","reading"}', '{"emit greenhouse gases","reduce greenhouse gas emissions","greenhouse gas effect","major greenhouse gas"}', '{"实现可持续发展","可持续发展目标","促进可持续发展","可持续发展战略"}', 'Carbon dioxide is the most significant greenhouse gas contributing to global warming.', '可持续发展旨在满足当代需求，同时不损害后代的能力。', '{"heat-trapping gas","atmospheric pollutant","CO2 equivalent"}', '{"永续发展","可持续增长","绿色发展"}', '{"greenhouse 是一个词，不要分开写 green house"}', 'Writing Task 2: climate change; Reading: science articles', '/səˈsteɪ.nə.bəl dɪˈvel.əp.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-008', 'natural resources', '自然资源', 'noun phrase', '6.0', 93, '{"environment"}', '{"writing","speaking"}', '{"deplete natural resources","conserve natural resources","abundant natural resources","exploit natural resources"}', '{"森林砍伐","防止森林砍伐","大规模森林砍伐","森林砍伐率"}', 'Rapid industrialization has led to the depletion of natural resources at an alarming rate.', '亚马逊雨林的森林砍伐对全球生物多样性构成严重威胁。', '{"raw materials","natural capital","environmental resources"}', '{"森林破坏","毁林","砍伐森林"}', '{"resources 在此语境中总是用复数"}', 'Writing Task 2: development / environment; Speaking Part 3', '/diːˌfɒr.ɪˈsteɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-009', 'environmental degradation', '环境退化', 'noun phrase', '6.5', 91, '{"environment"}', '{"writing","reading"}', '{"cause environmental degradation","prevent environmental degradation","severe environmental degradation","combat environmental degradation"}', '{"保护生物多样性","生物多样性丧失","丰富生物多样性","生物多样性热点"}', 'Uncontrolled industrial expansion has resulted in severe environmental degradation in many regions.', '保护生物多样性对于维持生态系统的健康和稳定至关重要。', '{"environmental damage","ecological deterioration","environmental deterioration"}', '{"物种多样性","生物多样化","生态多样性"}', '{"degradation 是不可数名词；恶劣程度用 severe/serious 修饰"}', 'Writing Task 2: industry / environment; Reading: environmental reports', '/ˌbaɪ.əʊ.daɪˈvɜː.sə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-010', 'global warming', '全球变暖', 'noun phrase', '6.0', 97, '{"environment"}', '{"writing","speaking"}', '{"contribute to global warming","address global warming","impact of global warming","combat global warming"}', '{"生态系统保护","海洋生态系统","生态系统服务","破坏生态系统"}', 'The scientific consensus is clear: human activities are the primary cause of global warming.', '健康的生态系统为人类提供清洁的水源、空气和食物。', '{"climate heating","planetary warming","temperature rise"}', '{"生态体系","生态环境","自然系统"}', '{"global warming 多用于口语/一般写作；climate change 更学术"}', 'Writing Task 2: environment; Speaking Part 3: climate topics', '/ˈiː.kəʊˌsɪs.təm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-011', 'conservation efforts', '保护工作', 'noun phrase', '6.0', 90, '{"environment"}', '{"writing","speaking"}', '{"support conservation efforts","wildlife conservation efforts","conservation efforts aim to","strengthen conservation efforts"}', '{"环境保护","野生动物保护","保护工作","保护措施"}', 'International cooperation is essential for effective wildlife conservation efforts across national borders.', '有效的环境保护需要政府、企业和公众的共同努力。', '{"preservation initiatives","protection measures","conservation programs"}', '{"保护","保育","保存"}', '{"conservation 主要指保护自然资源；preservation 侧重维持原始状态"}', 'Writing Task 2: wildlife / environment; Speaking Part 3', '/ˌkɒn.səˈveɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-012', 'ecological balance', '生态平衡', 'noun phrase', '6.5', 92, '{"environment"}', '{"writing","reading"}', '{"maintain ecological balance","disrupt ecological balance","restore ecological balance","delicate ecological balance"}', '{"保护濒危物种","濒危物种名单","濒危物种栖息地","濒危物种保护法"}', 'The introduction of invasive species can severely disrupt the ecological balance of an entire ecosystem.', '由于栖息地丧失和非法捕猎，许多濒危物种面临灭绝的威胁。', '{"environmental equilibrium","ecosystem balance","natural balance"}', '{"受威胁物种","珍稀物种","濒临灭绝的物种"}', '{"ecological 是形容词，注意拼写 eco + logical"}', 'Writing Task 2: biodiversity; Reading: ecology articles', '/ɪnˈdeɪn.dʒəd ˈspiː.ʃiːz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-013', 'deforestation rate', '森林砍伐率', 'noun phrase', '6.0', 90, '{"environment"}', '{"writing","reading"}', '{"alarming deforestation rate","reduce deforestation rate","rapid deforestation rate","slow the deforestation rate"}', '{"空气污染","水污染","减少污染","工业污染"}', 'The alarming deforestation rate in the Amazon rainforest has raised serious concerns worldwide.', '城市地区的空气污染已导致严重的公共健康问题。', '{"forest clearing rate","rate of forest loss","tree cover loss"}', '{"污染","环境污染","污染物"}', '{"deforestation 是不可数名词；deforest 是动词形式"}', 'Writing Task 1/2: environmental data; Reading: environmental news', '/pəˈluː.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-014', 'environmental awareness', '环保意识', 'noun phrase', '6.0', 92, '{"environment"}', '{"writing","speaking"}', '{"raise environmental awareness","growing environmental awareness","promote environmental awareness","lack of environmental awareness"}', '{"空气质量指数","改善空气质量","空气质量监测","空气质量标准"}', 'Schools play a vital role in raising environmental awareness among the younger generation.', '糟糕的空气质量与呼吸系统疾病发病率上升有直接关联。', '{"eco-consciousness","environmental consciousness","green awareness"}', '{"大气质量","空气状况","大气环境"}', '{"awareness 是不可数名词，不用复数形式"}', 'Writing Task 2: education / environment; Speaking Part 3', '/eər ˈkwɒl.ə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-015', 'air pollution', '空气污染', 'noun phrase', '5.5', 94, '{"environment"}', '{"speaking","listening"}', '{"combat air pollution","reduce air pollution","severe air pollution","indoor air pollution"}', '{"废物管理","固体废物管理","废物管理系统","可持续废物管理"}', 'Air pollution in major cities has reached hazardous levels, posing serious health risks to residents.', '有效的废物管理是构建可持续城市的关键组成部分。', '{"atmospheric pollution","smog","air contamination"}', '{"垃圾处理","废物处理","废料管理"}', '{"pollution 是不可数名词；specific types 用 air/water/noise pollution"}', 'Speaking Part 3: city life; Listening Section 2: public health announcements', '/weɪst ˈmæn.ɪdʒ.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-016', 'energy consumption', '能源消耗', 'noun phrase', '6.0', 94, '{"environment"}', '{"writing","reading"}', '{"reduce energy consumption","excessive energy consumption","household energy consumption","energy consumption patterns"}', '{"回收计划","提高回收率","回收设施","分类回收"}', 'Installing smart meters can help households monitor and reduce their energy consumption.', '提高回收率可以显著减少垃圾填埋场的压力。', '{"energy use","power consumption","energy expenditure"}', '{"循环利用","资源回收","再生利用"}', '{"consumption 是不可数名词；consumer 是消费者，不要混淆"}', 'Writing Task 1/2: energy data; Reading: energy reports', '/ˌriːˈsaɪ.klɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-017', 'waste disposal', '废物处理', 'noun phrase', '5.5', 93, '{"environment"}', '{"listening","speaking"}', '{"improper waste disposal","waste disposal system","household waste disposal","safe waste disposal"}', '{"保护自然资源","消耗自然资源","可再生自然资源","自然资源管理"}', 'Improper waste disposal has led to widespread contamination of soil and groundwater in the area.', '不可持续的自然资源消耗威胁着后代的发展机会。', '{"garbage disposal","refuse management","waste management"}', '{"天然资源","自然资源禀赋","自源"}', '{"disposal 是不可数名词；dispose of 是动词短语"}', 'Listening Section 2: community services; Speaking Part 3', '/ˈnætʃ.ər.əl rɪˈzɔːr.sɪz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-018', 'biodiversity loss', '生物多样性丧失', 'noun phrase', '6.5', 95, '{"environment"}', '{"writing","reading"}', '{"halt biodiversity loss","rapid biodiversity loss","cause biodiversity loss","consequences of biodiversity loss"}', '{"臭氧层破坏","保护臭氧层","臭氧层空洞","臭氧层恢复"}', 'Habitat destruction is the leading cause of biodiversity loss in tropical regions worldwide.', '禁止使用氟利昂的国际协议帮助减缓了臭氧层的破坏。', '{"species extinction","loss of biodiversity","ecological decline"}', '{"臭氧保护层","大气臭氧","平流层臭氧"}', '{"biodiversity 是 bio+ diversity 合成词，不可数"}', 'Writing Task 2: environment / wildlife; Reading: biology articles', '/ˈəʊ.zəʊn ˈleɪ.ər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-019', 'eco-friendly', '环保的', 'adjective', '5.5', 93, '{"environment"}', '{"speaking","listening"}', '{"eco-friendly product","eco-friendly alternative","eco-friendly lifestyle","eco-friendly packaging"}', '{"太阳能板","利用太阳能","太阳能发电","太阳能技术"}', 'Consumers are increasingly choosing eco-friendly products to minimize their environmental impact.', '太阳能是最具发展潜力的可再生能源之一。', '{"environmentally friendly","green","sustainable","earth-friendly"}', '{"太阳能源","光伏能源","日光能","「earth-friendly」的中文释义"}', '{"eco-friendly 有连字符；不要写成 eco friendly"}', 'Speaking Part 3: consumer habits; Listening Section 2: product descriptions', '/ˈsəʊ.lər ˈen.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-020', 'environmental impact', '环境影响', 'noun phrase', '6.0', 92, '{"environment"}', '{"writing","reading"}', '{"assess environmental impact","minimize environmental impact","environmental impact assessment","negative environmental impact"}', '{"风力发电","风电场","风力涡轮机","开发风能"}', 'Companies are now required to conduct environmental impact assessments before starting major projects.', '风力发电已成为许多国家清洁能源战略的重要组成部分。', '{"ecological impact","environmental consequence","environmental effect"}', '{"风能","风力能源","风电"}', '{"impact 后接 on；environmental impact on local communities"}', 'Writing Task 2: business / environment; Reading: environmental reports', '/wɪnd ˈpaʊ.ər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-021', 'carbon emissions', '碳排放', 'noun phrase', '6.0', 85, '{"environment"}', '{"writing","reading"}', '{"cut carbon emissions","reduce carbon emissions","carbon emissions trading","net-zero carbon emissions"}', '{"核电站","发展核能","核能安全","核能政策"}', 'Many countries have pledged to achieve net-zero carbon emissions by 2050.', '核能是一种低碳能源，但安全问题和核废料处置仍存在争议。', '{"CO2 emissions","greenhouse gas output","carbon output"}', '{"原子能","核动力","核电力"}', '{"emissions 表示排放物时总是用复数；emission 单数指排放过程"}', 'Writing Task 1/2: climate data; Reading: climate science', '/ˈnjuː.kli.ər ˈen.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-022', 'water scarcity', '水资源短缺', 'noun phrase', '6.0', 82, '{"environment"}', '{"writing","reading"}', '{"face water scarcity","severe water scarcity","water scarcity issue","address water scarcity"}', '{"减少碳排放","碳排放交易","零碳排放","碳排放量"}', 'Water scarcity affects over two billion people worldwide and is expected to worsen with climate change.', '许多国家承诺在2050年前实现净零碳排放。', '{"water shortage","water stress","water deficit"}', '{"二氧化碳排放","温室气体排放","碳排放物"}', '{"scarcity 是不可数名词；scarce 是形容词形式"}', 'Writing Task 2: resource management; Reading: global issues', '/ˈkɑːr.bən ɪˈmɪʃ.ənz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-023', 'endangered species', '濒危物种', 'noun phrase', '6.0', 84, '{"environment"}', '{"writing","speaking"}', '{"protect endangered species","critically endangered species","endangered species list","habitat of endangered species"}', '{"环保产品","环保技术","环保做法","环保政策"}', 'Poaching and habitat loss continue to threaten endangered species such as the giant panda and the snow leopard.', '消费者越来越倾向于购买环保产品，推动企业走向可持续发展。', '{"threatened species","vulnerable species","at-risk species"}', '{"环保的","生态友好的","对环境无害的"}', '{"endangered 不用于 very 修饰；说 critically endangered"}', 'Writing Task 2: wildlife conservation; Speaking Part 3: animals', '/ɪnˌvaɪ.rənˈmen.təl.i ˈfrend.li/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-024', 'marine ecosystem', '海洋生态系统', 'noun phrase', '6.5', 76, '{"environment"}', '{"reading","listening"}', '{"protect marine ecosystems","threat to marine ecosystems","marine ecosystem health","fragile marine ecosystem"}', '{"维持生态平衡","破坏生态平衡","恢复生态平衡","生态平衡的重要性"}', 'Plastic pollution poses a growing threat to marine ecosystems and the countless species that depend on them.', '每个物种在维持生态平衡中都扮演着不可替代的角色。', '{"ocean ecosystem","aquatic ecosystem","marine environment"}', '{"生态均衡","自然平衡","环境平衡"}', '{"marine 发音 /məˈriːn/，注意重音在第二个音节"}', 'Reading: environmental science; Listening Section 4: marine biology', '/ˌiː.kəˈlɒdʒ.ɪ.kəl ˈbæl.əns/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-025', 'ozone layer', '臭氧层', 'noun phrase', '6.0', 80, '{"environment"}', '{"reading","listening"}', '{"deplete the ozone layer","protect the ozone layer","ozone layer depletion","hole in the ozone layer"}', '{"推广绿色能源","绿色能源技术","转向绿色能源","绿色能源产业"}', 'The successful recovery of the ozone layer demonstrates that international cooperation can solve environmental problems.', '绿色能源产业的快速发展正在重塑全球能源格局。', '{"ozone shield","stratospheric ozone","atmospheric ozone layer"}', '{"清洁能源","可再生能源","环保能源"}', '{"ozone layer 前通常加 the；deplete 表示消耗/枯竭"}', 'Reading: environmental science; Listening Section 4: science lecture', '/ɡriːn ˈen.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-026', 'solar energy', '太阳能', 'noun phrase', '5.5', 86, '{"environment"}', '{"speaking","writing"}', '{"harness solar energy","solar energy system","install solar energy panels","solar energy potential"}', '{"水资源短缺","应对水资源短缺","严重的水资源短缺","水资源短缺问题"}', 'Solar energy is becoming increasingly affordable and accessible for households in sun-rich regions.', '水资源短缺正成为许多发展中国家面临的严峻挑战。', '{"solar power","sunlight energy","photovoltaic energy"}', '{"缺水","水资源匮乏","用水紧张"}', '{"solar 表示太阳的；lunar 表示月亮的，不要混淆"}', 'Speaking Part 3: energy / technology; Writing Task 2: renewable energy', '/ˈwɔː.tər ˈskeə.sə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-027', 'environmental policy', '环保政策', 'noun phrase', '6.5', 78, '{"environment"}', '{"writing","reading"}', '{"implement environmental policy","stringent environmental policy","government environmental policy","formulate environmental policy"}', '{"环境保护","环保署","环境保护措施","环境保护法"}', 'Stringent environmental policies have proven effective in reducing industrial pollution in developed nations.', '环境保护不应被视为经济发展的障碍，而应是其重要组成部分。', '{"green policy","environmental regulation","eco-policy"}', '{"生态保护","环境保护","环境保育"}', '{"policy 可数，复数 policies；表示政策的集合时也可用单数"}', 'Writing Task 2: government; Reading: policy documents', '/ˌen.vaɪ.rənˈmen.təl prəˈtek.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-028', 'urban sprawl', '城市扩张', 'noun phrase', '6.5', 74, '{"environment"}', '{"writing","reading"}', '{"uncontrolled urban sprawl","limit urban sprawl","urban sprawl contributes to","consequences of urban sprawl"}', '{"有毒废物","处理有毒废物","有毒废物排放","有毒废物管理"}', 'Uncontrolled urban sprawl has led to the loss of valuable farmland and green spaces around many cities.', '工业有毒废物的不当处置对附近社区的健康构成严重威胁。', '{"suburban expansion","urban expansion","city sprawl"}', '{"危险废物","有害废物","毒性废料"}', '{"sprawl 是不可数名词；注意拼写不是 sprawl"}', 'Writing Task 2: urbanization; Reading: urban planning articles', '/ˈtɒk.sɪk weɪst/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-029', 'ecological footprint', '生态足迹', 'noun phrase', '6.5', 72, '{"environment"}', '{"writing","reading"}', '{"reduce ecological footprint","measure ecological footprint","humanity''s ecological footprint","exceed the ecological footprint"}', '{"土地荒漠化","防止荒漠化","荒漠化进程","荒漠化控制"}', 'If everyone lived like the average American, we would need five Earths to sustain our ecological footprint.', '过度放牧和森林砍伐加速了许多干旱地区的荒漠化进程。', '{"environmental footprint","biocapacity demand","earth footprint"}', '{"沙漠化","土地退化","干旱化"}', '{"ecological footprint 是科学术语，和 carbon footprint 不同"}', 'Writing Task 2: sustainability; Reading: environmental economics', '/ˌdes.tɪˈfɪ.keɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-030', 'industrial pollution', '工业污染', 'noun phrase', '5.5', 81, '{"environment"}', '{"writing","listening"}', '{"reduce industrial pollution","control industrial pollution","sources of industrial pollution","tackle industrial pollution"}', '{"红树林保护","红树林生态系统","恢复红树林","红树林森林"}', 'Strict regulations have been introduced to control industrial pollution and protect local communities.', '红树林在保护海岸线和为海洋生物提供栖息地方面发挥着重要作用。', '{"factory emissions","industrial contamination","manufacturing pollution"}', '{"红树林","海岸防护林","潮汐林"}', '{"industrial 是形容词 (工业的)；industrious 是勤劳的，完全不同"}', 'Writing Task 2: industry regulation; Listening Section 2: community issues', '/ˈmæn.ɡrəʊv/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-031', 'recycling program', '回收计划', 'noun phrase', '5.5', 79, '{"environment"}', '{"listening","speaking"}', '{"implement a recycling program","participate in recycling programs","community recycling program","effective recycling program"}', '{"海平面上升","应对海平面上升","海平面上升威胁","海平面上升速度"}', 'The city council launched a comprehensive recycling program to reduce the amount of waste sent to landfills.', '海平面上升对低洼沿海城市和岛屿国家的生存构成了直接威胁。', '{"waste recovery scheme","reuse initiative","circular economy program"}', '{"海面上升","海水上涨","洋面升高"}', '{"recycling 拼写注意，中间有 c 不是 k"}', 'Listening Section 2: community announcements; Speaking Part 1: daily habits', '/siː ˈlev.əl raɪz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-032', 'natural habitat', '自然栖息地', 'noun phrase', '6.0', 83, '{"environment"}', '{"reading","writing"}', '{"destroy natural habitats","preserve natural habitats","loss of natural habitat","threatened natural habitat"}', '{"环境可持续性","可持续性发展","可持续性实践","确保可持续性"}', 'Urban expansion continues to encroach upon the natural habitats of many wildlife species.', '企业在追求利润的同时，也需要关注其运营对环境可持续性的影响。', '{"native habitat","wildlife habitat","ecological habitat","natural environment"}', '{"可持续性","永续性","可维持性","「natural environment」的中文释义"}', '{"habitat 可数，复数 habitats；注意重音在第一个音节"}', 'Reading: wildlife articles; Writing Task 2: conservation', '/səˌsteɪ.nəˈbɪl.ə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-033', 'wind power', '风力发电', 'noun phrase', '5.5', 75, '{"environment"}', '{"listening","reading"}', '{"generate wind power","offshore wind power","harness wind power","wind power capacity"}', '{"湿地保护","湿地生态系统","人工湿地","湿地恢复"}', 'Offshore wind power has emerged as one of the most promising sources of clean energy in Europe.', '湿地是地球上最具生物多样性的生态系统之一，具有重要的生态功能。', '{"wind energy","aeolian energy","wind-generated electricity"}', '{"沼泽地","湿地生态系统","水泽地"}', '{"wind 发音 /wɪnd/，不是 /waɪnd/ (那个是动词缠绕)"}', 'Listening Section 4: renewable energy; Reading: energy technology', '/ˈwɛt.lənd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-034', 'greenhouse effect', '温室效应', 'noun phrase', '5.5', 84, '{"environment"}', '{"reading","listening"}', '{"the greenhouse effect causes","enhanced greenhouse effect","natural greenhouse effect","trap heat in the greenhouse effect"}', '{"原始森林","保护原始森林","原始森林砍伐","原始森林生态系统"}', 'The greenhouse effect is a natural phenomenon, but human activities have intensified it to dangerous levels.', '原始森林拥有最丰富的生物多样性，一旦破坏几乎无法恢复。', '{"heat-trapping phenomenon","atmospheric warming process"}', '{"原生森林","古老森林"}', '{"greenhouse 一个词，重音在前面"}', 'Reading: basic science; Listening Section 4: environmental lecture', '/ˈmeɪ.dən ˈfɔː.rɪst/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-035', 'natural disaster', '自然灾害', 'noun phrase', '5.5', 77, '{"environment"}', '{"speaking","listening"}', '{"devastating natural disaster","prone to natural disasters","cope with natural disasters","frequency of natural disasters"}', '{"开发可再生资源","利用可再生资源","可再生资源管理","可再生资源技术"}', 'Climate change has been linked to the increasing frequency and intensity of natural disasters worldwide.', '投资可再生资源有助于减少对有限化石燃料的依赖。', '{"catastrophic event","environmental disaster","act of nature"}', '{"可持续资源","再生资源","可更新资源"}', '{"disaster 可数；natural disaster 前可加 a/an"}', 'Speaking Part 2/3: natural disasters; Listening Section 2: news reports', '/rɪˈnjuː.ə.bəl rɪˈzɔːr.sɪz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-036', 'pollutant emission', '污染物排放', 'noun phrase', '6.5', 70, '{"environment"}', '{"reading","writing"}', '{"reduce pollutant emissions","vehicle pollutant emissions","industrial pollutant emissions","regulate pollutant emissions"}', '{"酸雨形成","酸雨影响","减少酸雨","酸雨问题"}', 'The government has introduced stricter standards to regulate pollutant emissions from factories and vehicles.', '酸雨对森林、湖泊和建筑物造成长期的腐蚀性损害。', '{"toxic discharge","contaminant release","harmful emission"}', '{"酸性降水","酸沉降","酸性降雨"}', '{"emission 可用单数表示排放过程，复数表示排放物"}', 'Reading: environmental regulations; Writing Task 2: pollution control', '/ˈæs.ɪd reɪn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-037', 'environmental sustainability', '环境可持续性', 'noun phrase', '6.5', 73, '{"environment"}', '{"writing","reading"}', '{"achieve environmental sustainability","promote environmental sustainability","ensure environmental sustainability","commitment to environmental sustainability"}', '{"森林覆盖率","增加森林覆盖率","森林覆盖面积","森林覆盖减少"}', 'Achieving environmental sustainability requires a fundamental shift in how we produce and consume goods.', '提高森林覆盖率是应对气候变化最有效的自然解决方案之一。', '{"ecological sustainability","green sustainability","planetary sustainability"}', '{"森林覆盖","林地面积","林木覆盖"}', '{"sustainability 不可数；sustainable 是形容词，用法不同"}', 'Writing Task 2: sustainability / development; Reading: policy documents', '/ˈfɔː.rɪst ˈkʌv.ər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-038', 'habitat destruction', '栖息地破坏', 'noun phrase', '6.0', 71, '{"environment"}', '{"writing","reading"}', '{"cause habitat destruction","widespread habitat destruction","prevent habitat destruction","rate of habitat destruction"}', '{"海洋污染","减少海洋污染","海洋塑料污染","控制海洋污染"}', 'Habitat destruction due to agriculture and urbanization is the single greatest threat to biodiversity.', '每年有数百万吨塑料流入海洋，造成严重的海洋污染。', '{"habitat loss","ecosystem destruction","habitat degradation"}', '{"海水污染","海洋环境污染","海上污染"}', '{"destruction 不可数；动词是 destroy"}', 'Writing Task 2: conservation; Reading: ecology articles', '/ˈmær.ɪn pəˈluː.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-039', 'carbon neutral', '碳中和', 'adjective', '6.5', 68, '{"environment"}', '{"writing","reading"}', '{"become carbon neutral","carbon neutral by 2050","achieve carbon neutral status","pledge to be carbon neutral"}', '{"排放标准","提高排放标准","车辆排放标准","工业排放标准"}', 'Several major corporations have pledged to become carbon neutral by 2030 to combat climate change.', '更严格的排放标准对于减少城市空气污染至关重要。', '{"net-zero emissions","climate neutral","carbon zero"}', '{"排污标准","排放规范","废气标准"}', '{"carbon neutral 是复合形容词，不需要连字符；carbon-neutral 也接受"}', 'Writing Task 2: climate policy; Reading: business news', '/ɪˈmɪʃ.ən stæn.dədz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-040', 'plastic waste', '塑料垃圾', 'noun phrase', '5.5', 69, '{"environment"}', '{"speaking","listening"}', '{"reduce plastic waste","plastic waste pollution","dispose of plastic waste","plastic waste problem"}', '{"重新造林","植树造林项目","推进重新造林","重新造林计划"}', 'Single-use plastic waste has become one of the most visible and pressing environmental issues today.', '重新造林是恢复退化土地和应对气候变化的重要手段。', '{"plastic pollution","plastic debris","synthetic waste"}', '{"森林重建","复林","再造林"}', '{"waste 是不可数名词；plastic waste 无复数形式"}', 'Speaking Part 3: environment; Listening Section 2: public campaigns', '/ˌriː.fɔːr.ɪˈsteɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-041', 'emission standards', '排放标准', 'noun phrase', '6.5', 64, '{"environment"}', '{"reading","writing"}', '{"meet emission standards","strict emission standards","vehicle emission standards","tighten emission standards"}', '{"野生动物栖息地","保护野生动物栖息地","破坏野生动物栖息地","恢复野生动物栖息地"}', 'The government plans to tighten emission standards for all newly registered vehicles from next year.', '城市扩张不断侵占野生动物栖息地，导致人与动物的冲突加剧。', '{"pollution limits","discharge regulations","emission limits"}', '{"野生动物生境","动物栖息环境","野生动物家园"}', '{"standards 通常用复数，因为涉及多项标准"}', 'Reading: regulatory documents; Writing Task 2: government policy', '/ˈwaɪld.laɪf ˈhæb.ɪ.tæt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-042', 'organic farming', '有机农业', 'noun phrase', '6.0', 67, '{"environment"}', '{"speaking","reading"}', '{"practice organic farming","organic farming methods","promote organic farming","shift to organic farming"}', '{"养蜂业","可持续养蜂","城市养蜂","养蜂实践"}', 'Organic farming avoids the use of synthetic pesticides and fertilizers, making it more environmentally friendly.', '养蜂不仅提供蜂蜜，更重要的是通过授粉维持农业生产。', '{"sustainable agriculture","chemical-free farming","natural farming"}', '{"养蜂","蜂业","蜜蜂养殖"}', '{"organic 在不同语境有不同含义，这里指有机/无化学合成"}', 'Speaking Part 3: food / agriculture; Reading: food industry', '/ˈeɪ.pɪ.kʌl.tʃər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-043', 'soil erosion', '土壤侵蚀', 'noun phrase', '6.0', 61, '{"environment"}', '{"reading","listening"}', '{"prevent soil erosion","cause soil erosion","severe soil erosion","soil erosion control"}', '{"噪音污染","减少噪音污染","城市噪音污染","噪音污染影响"}', 'Deforestation on steep slopes has accelerated soil erosion, reducing the land''s agricultural productivity.', '长期暴露于噪音污染中会对心理健康和睡眠质量产生负面影响。', '{"land erosion","topsoil loss","soil degradation"}', '{"声音污染","噪声干扰","噪音危害"}', '{"erosion 不可数；动词是 erode"}', 'Reading: agriculture / geography; Listening Section 4: environmental lecture', '/əˈkʌs.tɪk pəˈluː.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-044', 'overpopulation', '人口过剩', 'noun phrase', '6.0', 66, '{"environment"}', '{"writing","speaking"}', '{"problem of overpopulation","overpopulation leads to","address overpopulation","burden of overpopulation"}', '{"生态学","生态系统","生态平衡","生态保护"}', 'Overpopulation puts tremendous strain on natural resources, infrastructure, and the environment.', '了解生态学原理有助于我们更好地保护自然环境。', '{"population explosion","overcrowding","excessive population growth"}', '{"生态","生态学","环境科学"}', '{"overpopulation 不可数；通常不加 the"}', 'Writing Task 2: global issues; Speaking Part 3: social problems', '/ɪˌkɒl.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-045', 'energy efficiency', '能源效率', 'noun phrase', '6.0', 65, '{"environment"}', '{"writing","reading"}', '{"improve energy efficiency","promote energy efficiency","energy efficiency standards","invest in energy efficiency"}', '{"有机农业","推广有机农业","有机农业实践","有机农业产品"}', 'Improving energy efficiency in buildings is one of the most cost-effective ways to reduce carbon emissions.', '有机农业避免使用合成农药和化肥，有利于土壤健康和生物多样性。', '{"energy conservation","fuel efficiency","power efficiency"}', '{"有机耕作","生态农业","绿色农业"}', '{"efficiency 不可数；efficient 是形容词"}', 'Writing Task 2: energy policy; Reading: technology reports', '/ˈɒr.ɡæn.ɪk ˈfɑːr.mɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-046', 'acid rain', '酸雨', 'noun phrase', '5.5', 62, '{"environment"}', '{"reading","listening"}', '{"caused by acid rain","damage from acid rain","acid rain pollution","effects of acid rain"}', '{"温室气体排放","减少温室气体","温室气体浓度","温室气体效应"}', 'Acid rain, primarily caused by industrial emissions, has severely damaged forests and lakes across the region.', '二氧化碳是最主要的温室气体之一，主要来自化石燃料的燃烧。', '{"acid precipitation","acid deposition","atmospheric acid"}', '{"温室效应气体","大气保温气体","热捕获气体"}', '{"acid rain 不可数，前面不用加 an"}', 'Reading: environmental science; Listening Section 4: environmental issues', '/ˈɡriːn.haʊs ɡæs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-047', 'wildlife corridor', '野生动物走廊', 'noun phrase', '6.5', 54, '{"environment"}', '{"reading","listening"}', '{"establish wildlife corridors","create wildlife corridors","wildlife corridor network","protect wildlife corridors"}', '{"碳中和","保持中立","碳中性","中立立场"}', 'Wildlife corridors allow animals to move safely between fragmented habitats, helping maintain genetic diversity.', '许多科技公司承诺在2030年前实现碳中和目标。', '{"ecological corridor","habitat corridor","conservation corridor","green corridor"}', '{"中和","中立","平衡","「green corridor」的中文释义"}', '{"corridor 表示走廊/通道；wildlife corridor 是生态学术语"}', 'Reading: conservation biology; Listening Section 4: ecology lecture', '/ˈnjʊə.trəl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-048', 'afforestation', '植树造林', 'noun phrase', '6.5', 56, '{"environment"}', '{"reading","writing"}', '{"promote afforestation","afforestation project","afforestation efforts","large-scale afforestation"}', '{"资源枯竭","臭氧层消耗","能源枯竭","地下水枯竭"}', 'Large-scale afforestation projects have been launched to combat desertification in arid regions.', '自然资源的持续枯竭对经济的长期可持续发展构成了威胁。', '{"tree planting","reforestation","forest restoration"}', '{"耗尽","枯竭","消耗殆尽"}', '{"afforestation 是在无林地上造林；reforestation 是在毁林地上再造林"}', 'Reading: environmental science; Writing Task 2: land management', '/dɪˈpliː.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-049', 'tidal energy', '潮汐能', 'noun phrase', '6.5', 52, '{"environment"}', '{"reading","listening"}', '{"harness tidal energy","tidal energy project","tidal energy potential","generate tidal energy"}', '{"饥荒","遭受饥荒","预防饥荒","大饥荒"}', 'Tidal energy offers a predictable and reliable source of renewable power compared to wind and solar.', '气候变化和冲突是导致部分地区饥荒频发的主要原因。', '{"tidal power","wave energy","ocean energy"}', '{"饥荒","粮荒","饥饿危机"}', '{"tidal 来自 tide (潮汐)，注意拼写 tidal 不是 tidle"}', 'Reading: renewable energy; Listening Section 4: technology lecture', '/ˈfæm.ɪn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('env-050', 'environmental ethics', '环境伦理', 'noun phrase', '6.5', 58, '{"environment"}', '{"reading","writing"}', '{"principles of environmental ethics","environmental ethics argues","apply environmental ethics","field of environmental ethics"}', '{"大气层","地球大气","大气压力","大气条件"}', 'Environmental ethics challenges the anthropocentric view that nature exists solely for human exploitation.', '地球大气层保护我们免受有害的太阳辐射。', '{"ecological ethics","conservation philosophy","green ethics"}', '{"大气","大气层","空气层"}', '{"ethics 以 -s 结尾但是单数概念，视为单数"}', 'Reading: philosophy / environment; Writing Task 2: environmental values', '/ˈæt.mə.sfɪər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-001', 'technological advancement', '科技进步', 'noun phrase', '6.5', 87, '{"technology"}', '{"writing","speaking"}', '{"rapid technological advancement","driven by technological advancement","keep pace with technological advancements"}', '{"发展人工智能","人工智能技术","人工智能应用"}', 'Technological advancement has transformed the way people communicate and access information.', '人工智能正在彻底改变从医疗保健到交通运输的各个行业。', '{"technological progress","technological development"}', '{"AI","机器智能"}', '{"technology advancement 不如 technological advancement 正式"}', 'Writing Task 2: technology / society topics', '/ˌɑːr.tɪˈfɪʃ.əl ɪnˈtel.ɪ.dʒəns/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-002', 'artificial intelligence', '人工智能', 'noun phrase', '6.5', 99, '{"technology"}', '{"writing","reading"}', '{"develop artificial intelligence","application of artificial intelligence","powered by artificial intelligence","artificial intelligence algorithm"}', '{"机器学习算法","应用机器学习","机器学习模型","机器学习技术"}', 'Artificial intelligence is transforming industries ranging from healthcare to transportation.', '机器学习算法可以从大量数据中识别模式并做出预测。', '{"AI","machine intelligence","cognitive computing"}', '{"机器学习","算法学习","自动学习"}', '{"artificial 拼写注意，两个 i (art + i + ficial)"}', 'Writing Task 2: technology / employment; Reading: technology articles', '/məˈʃiːn ˈlɜː.nɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-003', 'social media', '社交媒体', 'noun phrase', '5.5', 98, '{"technology"}', '{"speaking","writing"}', '{"addicted to social media","social media platform","social media influencer","impact of social media"}', '{"大数据分析","利用大数据","大数据技术","大数据时代"}', 'Social media has fundamentally changed the way people interact and share information.', '大数据分析帮助企业更好地理解客户行为和市场趋势。', '{"social networking sites","online platforms","digital networks"}', '{"海量数据","大规模数据","巨量数据"}', '{"media 是复数形式 (单数 medium)，但 social media 后常跟单数动词"}', 'Speaking Part 1/3: technology use; Writing Task 2: society', '/bɪɡ ˈdeɪ.tə/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-004', 'digital technology', '数字技术', 'noun phrase', '6.0', 95, '{"technology"}', '{"writing","speaking"}', '{"embrace digital technology","advancement of digital technology","digital technology adoption","impact of digital technology"}', '{"自动化系统","工业自动化","流程自动化","自动化技术"}', 'Digital technology has revolutionized the way businesses operate and deliver services to customers.', '自动化正在取代许多重复性工作，同时创造新的技术岗位。', '{"information technology","digital tools","electronic technology"}', '{"自动化","自动控制","机械化操作"}', '{"digital 是形容词，digit 是名词 (数字/手指)，不要混淆"}', 'Writing Task 2: technology / business; Speaking Part 3: technology', '/ˌɔː.təˈmeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-005', 'online learning', '在线学习', 'noun phrase', '5.5', 94, '{"technology"}', '{"speaking","writing"}', '{"online learning platform","shift to online learning","online learning environment","benefits of online learning"}', '{"数字化转型","推动数字化转型","数字化转型战略","数字化转型进程"}', 'Online learning has democratized access to education, enabling anyone with internet access to study.', '数字化转型已成为企业在数字经济时代生存的关键。', '{"e-learning","distance education","virtual learning","web-based learning"}', '{"数字化变革","数字革命","信息化转型","「web-based learning」的中文释义"}', '{"online learning 和 e-learning 可互换，前者更日常，后者更技术化"}', 'Speaking Part 3: education technology; Writing Task 2: education', '/ˈdɪdʒ.ɪ.təl ˌtræns.fərˈmeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-006', 'information technology', '信息技术', 'noun phrase', '6.0', 93, '{"technology"}', '{"writing","reading"}', '{"information technology sector","develop information technology","information technology infrastructure","information technology specialist"}', '{"网络安全","网络安全威胁","加强网络安全","网络安全措施"}', 'The information technology sector has been the driving force behind economic growth in many countries.', '随着网络攻击日益频繁，网络安全已成为企业和个人的首要关注。', '{"IT","computing technology","information systems","digital technology"}', '{"网络安全","信息安全","计算机安全","「digital technology」的中文释义"}', '{"information technology 在正式写作中第一次提用全称，之后可用 IT"}', 'Writing Task 2: economy / technology; Reading: business articles', '/ˌsaɪ.bə.sɪˈkjʊə.rə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-007', 'screen time', '屏幕时间', 'noun phrase', '5.5', 90, '{"technology"}', '{"speaking","writing"}', '{"limit screen time","excessive screen time","reduce screen time","manage screen time"}', '{"云计算服务","采用云计算","云计算平台","云计算技术"}', 'Parents are increasingly concerned about the effects of excessive screen time on children''s development.', '云计算使企业能够灵活扩展IT资源而不需要大量的前期投入。', '{"device usage time","digital exposure","electronic device use"}', '{"云端计算","云服务","网络计算"}', '{"screen time 是名词短语，不分开使用；通常作不可数名词"}', 'Speaking Part 3: parenting / technology; Writing Task 2: children', '/klaʊd kəmˈpjuː.tɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-008', 'data privacy', '数据隐私', 'noun phrase', '6.5', 92, '{"technology"}', '{"writing","reading"}', '{"protect data privacy","data privacy concern","data privacy regulation","violation of data privacy"}', '{"物联网设备","物联网技术","物联网应用","物联网平台"}', 'Stricter data privacy regulations are needed to protect individuals in the digital age.', '物联网正在实现家电、汽车和工业设备之间的无缝连接。', '{"information privacy","digital privacy","personal data protection"}', '{"IoT","万物互联","智能互联"}', '{"privacy 不可数；private 是形容词，不要写成 data private"}', 'Writing Task 2: technology / law; Reading: technology news', '/ˈɪn.tə.net əv θɪŋz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-009', 'cutting-edge technology', '尖端技术', 'noun phrase', '6.5', 90, '{"technology"}', '{"writing","reading"}', '{"adopt cutting-edge technology","cutting-edge technology company","access to cutting-edge technology","invest in cutting-edge technology"}', '{"区块链技术","区块链应用","区块链平台","基于区块链"}', 'The hospital invested in cutting-edge technology to improve patient diagnosis and treatment outcomes.', '区块链技术为数字交易提供了前所未有的透明度和安全性。', '{"state-of-the-art technology","advanced technology","frontier technology","leading-edge technology"}', '{"分布式账本","去中心化账本","加密链","「leading-edge technology」的中文释义"}', '{"cutting-edge 带连字符，是复合形容词"}', 'Writing Task 2: innovation / business; Reading: technology reviews', '/ˈblɒk.tʃeɪn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-010', 'digital literacy', '数字素养', 'noun phrase', '6.5', 91, '{"technology"}', '{"writing","reading"}', '{"improve digital literacy","digital literacy skills","promote digital literacy","lack of digital literacy"}', '{"虚拟现实体验","虚拟现实技术","虚拟现实头盔","虚拟现实游戏"}', 'Digital literacy is now considered as essential as traditional literacy in the modern workforce.', '虚拟现实技术正在改变教育、培训和娱乐的方式。', '{"technological literacy","computer literacy","IT skills","tech proficiency"}', '{"VR","虚拟环境","模拟现实","「tech proficiency」的中文释义"}', '{"literacy 是不可数名词；表示读写能力或素养"}', 'Writing Task 2: education / technology; Reading: education policy', '/ˌvɜː.tʃu.əl riˈæl.ə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-011', 'technological innovation', '技术创新', 'noun phrase', '6.5', 91, '{"technology"}', '{"writing","reading"}', '{"drive technological innovation","pace of technological innovation","foster technological innovation","technological innovation leads to"}', '{"增强现实技术","增强现实应用","增强现实眼镜","增强现实体验"}', 'Technological innovation has accelerated at an unprecedented pace over the past two decades.', '增强现实将数字信息叠加到现实世界中，创造出丰富的混合体验。', '{"tech innovation","scientific advancement","technological breakthrough"}', '{"AR","扩增实境","混合现实"}', '{"innovation 可以是可数 (一项创新 innovation) 或不可数 (创新概念)"}', 'Writing Task 2: technology / progress; Reading: technology news', '/ɔːɡˈmen.tɪd riˈæl.ə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-012', 'automation technology', '自动化技术', 'noun phrase', '6.0', 93, '{"technology"}', '{"writing","reading"}', '{"introduce automation technology","displaced by automation technology","industrial automation technology","invest in automation technology"}', '{"社交媒体平台","使用社交媒体","社交媒体营销","社交媒体影响"}', 'Automation technology is reshaping the manufacturing sector, boosting efficiency while reducing labor costs.', '社交媒体彻底改变了人们沟通和获取信息的方式。', '{"robotic technology","mechanized systems","automated technology"}', '{"社交网络","社群媒体","社交平台"}', '{"automation 不可数；automate 是动词，automatic 是形容词"}', 'Writing Task 2: employment / industry; Reading: industry reports', '/ˈsəʊ.ʃəl ˈmiː.di.ə/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-013', 'internet access', '互联网接入', 'noun phrase', '5.5', 90, '{"technology"}', '{"speaking","writing"}', '{"provide internet access","broadband internet access","universal internet access","lack of internet access"}', '{"电子商务平台","电子商务网站","发展电子商务","电子商务交易"}', 'Bridging the digital divide requires providing affordable internet access to underserved communities.', '电子商务的快速发展正在重塑传统零售业的格局。', '{"web access","online access","network connectivity"}', '{"电商","网络商务","线上交易"}', '{"access 是不可数名词，access to the internet 介词用 to"}', 'Speaking Part 3: technology; Writing Task 2: digital divide', '/ˈiːˌkɒm.ɜːs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-014', 'cybersecurity threat', '网络安全威胁', 'noun phrase', '6.5', 95, '{"technology"}', '{"reading","writing"}', '{"protect against cybersecurity threats","growing cybersecurity threat","cybersecurity threat landscape","address cybersecurity threats"}', '{"智能手机","智能手机应用","智能手机用户","智能手机普及"}', 'The growing number of cybersecurity threats has forced organizations to invest heavily in digital defenses.', '智能手机的普及使人们可以随时随地获取信息和娱乐。', '{"cyber threat","digital security risk","online security threat"}', '{"智慧型手机","智能电话","移动电话"}', '{"cybersecurity 可以连写也可以 cyber security；两种拼写都接受"}', 'Reading: technology security; Writing Task 2: technology risks', '/ˈsmɑːrt.fəʊn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-015', 'tech giant', '科技巨头', 'noun phrase', '5.5', 94, '{"technology"}', '{"reading","speaking"}', '{"global tech giant","tech giant faces scrutiny","dominated by tech giants","regulate tech giants"}', '{"技术创新","推动创新","创新驱动","创新精神"}', 'Tech giants such as Google and Apple have accumulated unprecedented market power and influence.', '技术创新是推动经济增长和提高生活质量的核心动力。', '{"technology conglomerate","big tech company","tech behemoth"}', '{"革新","创新","创造"}', '{"giant 此处是名词；也可作形容词 (giant corporation)"}', 'Reading: business news; Speaking Part 3: companies', '/ˌɪn.əˈveɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-016', 'digital revolution', '数字革命', 'noun phrase', '6.5', 92, '{"technology"}', '{"writing","reading"}', '{"sparked a digital revolution","digital revolution has transformed","era of digital revolution","impact of the digital revolution"}', '{"重大突破","技术突破","取得突破","突破性进展"}', 'The digital revolution has fundamentally changed how we work, communicate, and access information.', '量子计算领域的最新突破可能彻底改变信息处理的方式。', '{"information revolution","tech revolution","digital transformation"}', '{"重大进展","关键突破","飞跃"}', '{"revolution 前可加冠词 a/the，根据语境选择"}', 'Writing Task 2: technology / society; Reading: technology history', '/ˈbreɪk.θruː/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-017', 'big data analytics', '大数据分析', 'noun phrase', '6.5', 96, '{"technology"}', '{"reading","writing"}', '{"leverage big data analytics","big data analytics tools","apply big data analytics","big data analytics platform"}', '{"尖端技术","处于前沿","尖端研究","最前沿"}', 'Big data analytics enables companies to understand customer behavior and make data-driven decisions.', '这家公司以其在人工智能领域的尖端技术而闻名。', '{"large-scale data analysis","data mining","predictive analytics"}', '{"前沿","最先进","前沿技术"}', '{"data 严格来说是复数 (datum 的复数)，但现代英语常用作不可数单数"}', 'Reading: business technology; Writing Task 2: data / business', '/ˌkʌt.ɪŋ ˈedʒ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-018', 'the internet of things', '物联网', 'noun phrase', '6.5', 80, '{"technology"}', '{"reading","listening"}', '{"the internet of things enables","internet of things devices","internet of things technology","rise of the internet of things"}', '{"算法设计","复杂算法","算法优化","机器学习算法"}', 'The Internet of Things connects everyday devices to the internet, enabling smarter homes and cities.', '高效的算法是处理大规模数据集的基础。', '{"IoT","connected devices","smart network","ambient computing"}', '{"计算程序","运算规则","演算法","「ambient computing」的中文释义"}', '{"此短语前面通常有 the；正式写作首次提用全称后可用 IoT"}', 'Reading: technology trends; Listening Section 4: technology lectures', '/ˈæl.ɡə.rɪð.əm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-019', 'remote working', '远程办公', 'noun phrase', '6.0', 94, '{"technology"}', '{"speaking","writing"}', '{"embrace remote working","remote working arrangement","shift to remote working","remote working technology"}', '{"数据库管理","数据库系统","数据库查询","数据库技术"}', 'Remote working has become a permanent fixture in many industries following the global pandemic.', '一个设计良好的数据库对于高效存储和检索信息至关重要。', '{"telecommuting","working from home","distributed work","flexible working"}', '{"数据仓库","数据库","信息库","「flexible working」的中文释义"}', '{"remote working 和 working remotely 都正确，前者是名词短语"}', 'Speaking Part 3: work / technology; Writing Task 2: employment', '/ˈdeɪ.tə.beɪs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-020', 'wearable device', '可穿戴设备', 'noun phrase', '5.5', 78, '{"technology"}', '{"reading","listening"}', '{"wearable device market","smart wearable device","health-related wearable device","adopt wearable devices"}', '{"网络连接","社交网络","网络系统","网络基础设施"}', 'Wearable devices such as smartwatches can monitor health indicators like heart rate and sleep patterns.', '强大的网络基础设施是现代数字经济的基础。', '{"wearable technology","smart accessory","body-borne device"}', '{"网络","互联系统","通讯网"}', '{"wearable 是形容词，也可作名词 (复数 wearables)"}', 'Reading: technology reviews; Listening Section 2: product descriptions', '/ˈnet.wɜːk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-021', 'digital divide', '数字鸿沟', 'noun phrase', '6.5', 79, '{"technology"}', '{"writing","speaking"}', '{"bridge the digital divide","widen the digital divide","digital divide between","narrow the digital divide"}', '{"软件开发","软件系统","软件工程","应用软件"}', 'Governments must take steps to bridge the digital divide between urban and rural communities.', '软件开发已成为现代经济中最具活力的行业之一。', '{"technological gap","information gap","digital inequality","connectivity divide"}', '{"电脑程序","应用程序","软件系统","「connectivity divide」的中文释义"}', '{"divide 在此是名词 (鸿沟)，不是动词"}', 'Writing Task 2: technology / inequality; Speaking Part 3: society', '/ˈsɒft.weər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-022', 'electronic commerce', '电子商务', 'noun phrase', '6.0', 77, '{"technology"}', '{"reading","writing"}', '{"electronic commerce platform","growth of electronic commerce","electronic commerce sector","cross-border electronic commerce"}', '{"计算机硬件","硬件设备","硬件升级","硬件制造"}', 'Electronic commerce has reshaped the retail industry by allowing businesses to reach global markets.', '硬件和软件的协同发展推动了个人计算的飞速进步。', '{"e-commerce","online retail","digital commerce","internet shopping"}', '{"硬体","设备","实体设备","「internet shopping」的中文释义"}', '{"electronic commerce 在正式写作中用全称，日常写作可用 e-commerce"}', 'Reading: business articles; Writing Task 2: economy / technology', '/ˈhɑːrd.weər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-023', 'genetic engineering', '基因工程', 'noun phrase', '6.5', 76, '{"technology"}', '{"reading","writing"}', '{"advancements in genetic engineering","genetic engineering technology","concerns about genetic engineering","field of genetic engineering"}', '{"用户界面设计","图形用户界面","友好的用户界面","用户界面改进"}', 'Genetic engineering has opened up new possibilities in medicine, but it also raises ethical concerns.', '直观的用户界面是决定应用程序成功与否的关键因素。', '{"gene modification","genetic modification","biotechnology intervention"}', '{"UI","使用者界面","操作界面"}', '{"genetic 是形容词 (基因的)；generic 是通用的/一般的，完全不同"}', 'Reading: science articles; Writing Task 2: science ethics', '/ˈjuː.zər ˈɪn.tə.feɪs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-024', 'smartphone addiction', '手机沉迷', 'noun phrase', '5.5', 91, '{"technology"}', '{"speaking","writing"}', '{"suffer from smartphone addiction","combat smartphone addiction","overcome smartphone addiction","signs of smartphone addiction"}', '{"远程办公","推行远程办公","远程办公模式","远程办公政策"}', 'Smartphone addiction among teenagers has become a growing concern for parents and educators worldwide.', '远程办公让员工可以在家工作，减少通勤时间和办公成本。', '{"phone dependency","mobile device addiction","digital dependency"}', '{"远程工作","居家办公","电子通勤"}', '{"addiction 后接 to；addiction to smartphones"}', 'Speaking Part 3: technology / health; Writing Task 2: technology / society', '/ˌtel.ɪ.kəˈmjuː.tɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-025', 'algorithm recommendation', '算法推荐', 'noun phrase', '6.5', 74, '{"technology"}', '{"reading","writing"}', '{"powered by algorithm recommendation","algorithm recommendation system","personalized algorithm recommendation","algorithm recommendation engine"}', '{"远程工作","远程工作模式","适应远程工作","远程工作工具"}', 'Algorithm recommendation systems have raised concerns about echo chambers and information bias.', '疫情后，许多公司决定永久保留远程工作的选项。', '{"algorithmic suggestions","automated recommendation","machine-learning recommendations"}', '{"远程办公","在线工作","居家工作"}', '{"algorithm 发音 /ˈælɡərɪðəm/，注意和 logarithm (对数) 区分"}', 'Reading: technology analysis; Writing Task 2: AI / social media', '/rɪˈməʊt wɜːk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-026', 'cloud computing', '云计算', 'noun phrase', '6.0', 91, '{"technology"}', '{"reading","writing"}', '{"adopt cloud computing","cloud computing services","cloud computing platform","shift to cloud computing"}', '{"深度学习","深度学习算法","深度学习模型","深度学习技术"}', 'Cloud computing allows businesses to access powerful computing resources without investing in expensive hardware.', '深度学习在图像识别和自然语言处理方面取得了显著成果。', '{"cloud services","distributed computing","remote server technology"}', '{"深度神经网络","深层学习","深度机器学习"}', '{"cloud 在这里是比喻义，不是气象学意义上的云"}', 'Reading: technology news; Writing Task 2: business technology', '/ˈdiːp ˈlɜː.nɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-027', 'video conferencing', '视频会议', 'noun phrase', '5.5', 92, '{"technology"}', '{"speaking","listening"}', '{"participate in video conferencing","video conferencing tool","video conferencing software","via video conferencing"}', '{"机器人技术","工业机器人","机器人研究","机器人应用"}', 'Video conferencing has become an indispensable tool for remote collaboration in the modern workplace.', '机器人技术正在从制造业向服务业和医疗保健领域扩展。', '{"video call","virtual meeting","online conferencing","teleconferencing"}', '{"机器人学","自动化机械","智能机械","「teleconferencing」的中文释义"}', '{"conferencing 不可数；注意重音在第一个音节"}', 'Speaking Part 3: work; Listening Section 1/2: business context', '/rəʊˈbɒt.ɪks/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-028', 'quantum computing', '量子计算', 'noun phrase', '6.5', 70, '{"technology"}', '{"reading","listening"}', '{"develop quantum computing","quantum computing technology","potential of quantum computing","quantum computing breakthroughs"}', '{"量子计算","量子计算机","量子计算研究","量子计算技术"}', 'Quantum computing has the potential to solve complex problems that are beyond the reach of conventional computers.', '量子计算有潜力解决传统计算机无法处理的复杂问题。', '{"quantum computation","quantum information processing","quantum technology"}', '{"量子运算","量子计算技术","量子信息处理"}', '{"quantum 发音 /ˈkwɒntəm/，复数 quanta，但在 computing 前不变"}', 'Reading: advanced technology; Listening Section 4: science lecture', '/ˈkwɒn.təm kəmˈpjuː.tɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-029', 'gig economy', '零工经济', 'noun phrase', '6.0', 75, '{"technology"}', '{"speaking","writing"}', '{"participate in the gig economy","rise of the gig economy","gig economy worker","platform-based gig economy"}', '{"生物技术","生物技术产业","生物技术研究","生物技术应用"}', 'The gig economy offers flexibility but often lacks the job security and benefits of traditional employment.', '生物技术正在推动医学、农业和环境保护领域的革新。', '{"freelance economy","on-demand economy","sharing economy","platform economy"}', '{"生物科技","生技","生物工程","「platform economy」的中文释义"}', '{"gig 原意是演出，现引申为零工；the gig economy 前通常加 the"}', 'Speaking Part 3: work trends; Writing Task 2: employment', '/ˌbaɪ.əʊ.tekˈnɒl.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-030', 'patent protection', '专利保护', 'noun phrase', '6.5', 68, '{"technology"}', '{"reading","writing"}', '{"seek patent protection","intellectual property and patent protection","patent protection laws","adequate patent protection"}', '{"全球定位系统","GPS导航","GPS跟踪","GPS技术"}', 'Strong patent protection is essential for encouraging innovation and rewarding research and development.', 'GPS技术使我们能够精确导航并追踪物体的实时位置。', '{"intellectual property right","patent safeguard","invention protection"}', '{"卫星定位","全球定位","卫星导航"}', '{"patent 发音 /ˈpeɪtənt/ 或 /ˈpætənt/，两种英式发音均接受"}', 'Reading: business law; Writing Task 2: innovation policy', '/ˈdʒiː ˈpiː ˈes/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-031', 'data breach', '数据泄露', 'noun phrase', '6.0', 72, '{"technology"}', '{"reading","listening"}', '{"suffer a data breach","major data breach","prevent data breaches","data breach incident"}', '{"防火墙保护","网络安全防火墙","安装防火墙","防火墙设置"}', 'The company faced severe criticism and legal action following the massive data breach affecting millions of users.', '防火墙是保护计算机网络免受未授权访问的第一道防线。', '{"data leak","security breach","information leak","privacy violation"}', '{"网络防护墙","安全屏障","防护系统","「privacy violation」的中文释义"}', '{"breach 不是 beach (海滩)；breach 表示违反/突破/泄露"}', 'Reading: cybersecurity news; Listening Section 3: business discussion', '/ˈfaɪə.wɔːl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-032', 'social networking', '社交网络', 'noun phrase', '5.5', 78, '{"technology"}', '{"speaking","writing"}', '{"social networking site","online social networking","social networking platform","impact of social networking"}', '{"数据加密","加密技术","端到端加密","加密标准"}', 'Social networking has fundamentally altered patterns of human interaction and community formation.', '数据加密确保敏感信息在传输过程中不会被窃取。', '{"social media networking","online networking","digital socializing"}', '{"加密","密码保护","编码技术"}', '{"networking 是动名词形式；network 是名词/动词形式"}', 'Speaking Part 3: social media; Writing Task 2: technology / relationships', '/ɪnˈkrɪp.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-033', 'telemedicine service', '远程医疗服务', 'noun phrase', '6.5', 70, '{"technology"}', '{"reading","listening"}', '{"access telemedicine services","telemedicine service platform","provide telemedicine services","telemedicine service delivery"}', '{"网络带宽","增加带宽","带宽限制","高带宽"}', 'Telemedicine services have greatly improved healthcare access for patients in rural and remote areas.', '更高的网络带宽支持更快的数据传输和更流畅的视频流。', '{"remote healthcare","virtual consultation","e-health service","digital healthcare"}', '{"频宽","传输容量","数据速率","「digital healthcare」的中文释义"}', '{"telemedicine 前缀 tele- 表示远距离，和 television/telescope 一样"}', 'Reading: healthcare technology; Listening Section 3: healthcare discussion', '/ˈbænd.wɪdθ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-034', 'virtual reality', '虚拟现实', 'noun phrase', '6.0', 73, '{"technology"}', '{"reading","listening"}', '{"virtual reality technology","immersive virtual reality","virtual reality application","virtual reality headset"}', '{"纳米技术","纳米技术应用","纳米技术研究","纳米技术产业"}', 'Virtual reality is being used increasingly in education to create immersive learning experiences.', '纳米技术在材料科学和医学领域具有广阔的应用前景。', '{"VR","immersive technology","simulated environment","artificial reality"}', '{"毫微技术","分子制造","纳米工程","「artificial reality」的中文释义"}', '{"virtual 表示虚拟的/模拟的，和 actual 相对，不是美德的意思"}', 'Reading: technology reviews; Listening Section 4: technology trends', '/ˌnae.noʊ.tekˈnɒl.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-035', 'digital payment', '数字支付', 'noun phrase', '5.5', 76, '{"technology"}', '{"speaking","listening"}', '{"digital payment system","adopt digital payments","digital payment platform","convenience of digital payments"}', '{"自动驾驶汽车","自主驾驶车辆","自动驾驶技术","无人驾驶车辆"}', 'Digital payment systems have made financial transactions faster, safer, and more convenient than cash.', '自动驾驶汽车有望大幅减少交通事故并缓解城市拥堵。', '{"electronic payment","mobile payment","cashless payment","online transaction"}', '{"无人驾驶汽车","自动驾驶车辆","智能汽车","「online transaction」的中文释义"}', '{"payment 是可数名词 (一笔支付) 也能作不可数 (支付概念)"}', 'Speaking Part 1/2: daily life; Listening Section 1: transactions', '/ˈɔː.tə.nə.məs ˈviː.ɪ.kəl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-036', 'innovation hub', '创新中心', 'noun phrase', '6.0', 67, '{"technology"}', '{"reading","listening"}', '{"global innovation hub","establish an innovation hub","technology and innovation hub","serve as an innovation hub"}', '{"可穿戴技术","可穿戴设备","智能穿戴","可穿戴科技产品"}', 'Silicon Valley remains the world''s most prominent innovation hub for technology startups.', '可穿戴技术如智能手表可以实时监测用户的健康数据。', '{"tech hub","innovation center","technology cluster","startup ecosystem"}', '{"穿戴设备","智能穿戴","随身科技","「startup ecosystem」的中文释义"}', '{"hub 原意是轮毂，引申为中心/枢纽"}', 'Reading: business articles; Listening Section 3: business discussion', '/ˈweə.rə.bəl tekˈnɒl.ə.dʒi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-037', 'technology sector', '科技行业', 'noun phrase', '6.0', 71, '{"technology"}', '{"writing","reading"}', '{"booming technology sector","work in the technology sector","technology sector growth","dominate the technology sector"}', '{"开源软件","开源项目","开源社区","开源代码"}', 'The technology sector continues to attract the largest share of venture capital investment globally.', '开源软件促进了全球开发者之间的协作和创新。', '{"tech industry","IT sector","high-tech sector","technology industry"}', '{"开放源代码","公开源码","自由软件","「technology industry」的中文释义"}', '{"sector 可数；注意和 section (部分/章节) 区分"}', 'Writing Task 2: employment / economy; Reading: business news', '/ˈəʊ.pən sɔːs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-038', 'scientific breakthrough', '科学突破', 'noun phrase', '6.0', 74, '{"technology"}', '{"writing","reading"}', '{"major scientific breakthrough","achieve a scientific breakthrough","transformative scientific breakthrough","announce a scientific breakthrough"}', '{"数据可视化","可视化工具","信息可视化","可视化技术"}', 'The discovery of the CRISPR gene-editing tool is considered one of the most significant scientific breakthroughs of this century.', '数据可视化将复杂的数据转化为易于理解的图形和图表。', '{"research breakthrough","technological breakthrough","major advance","scientific discovery"}', '{"可视化","图示化","视觉呈现","「scientific discovery」的中文释义"}', '{"breakthrough 可数；through 不是 though"}', 'Writing Task 2: science / progress; Reading: science journals', '/ˈvɪdʒ.u.əl.ʌɪˈzeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-039', 'cryptocurrency', '加密货币', 'noun phrase', '6.5', 72, '{"technology"}', '{"reading","listening"}', '{"invest in cryptocurrency","cryptocurrency market","cryptocurrency exchange","rise of cryptocurrency"}', '{"软件部署","部署策略","快速部署","云部署"}', 'Cryptocurrency has sparked debate about the future of money and the role of central banks.', '自动化部署流程可以大幅减少软件发布所需的时间和风险。', '{"digital currency","virtual currency","decentralized currency","crypto"}', '{"发布","上线","配置部署","「crypto」的中文释义"}', '{"cryptocurrency 可数/不可数均可；crypto- 前缀表示隐藏/加密"}', 'Reading: finance technology; Listening Section 3: finance discussion', '/dɪˈplɔɪ.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-040', 'intellectual property', '知识产权', 'noun phrase', '6.5', 66, '{"technology"}', '{"writing","reading"}', '{"protect intellectual property","intellectual property rights","intellectual property law","violate intellectual property"}', '{"覆盖方法","安全覆盖","优先级覆盖","系统覆盖"}', 'Protecting intellectual property is essential for encouraging creativity and innovation in the digital age.', '在面向对象编程中，子类可以重写父类的方法。', '{"IP","creative rights","proprietary knowledge","copyright and patent"}', '{"重写","替换","取代","「copyright and patent」的中文释义"}', '{"property 不可数；intellectual property 也不可数"}', 'Writing Task 2: law / innovation; Reading: legal documents', '/ˌəʊ.vəˈɹaɪd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-041', 'tech startup', '科技创业公司', 'noun phrase', '5.5', 64, '{"technology"}', '{"reading","speaking"}', '{"found a tech startup","tech startup ecosystem","promising tech startup","invest in tech startups"}', '{"应用程序接口","API调用","API开发","REST API"}', 'The city has become a thriving hub for tech startups thanks to its supportive regulatory environment.', 'API允许不同的软件系统之间进行无缝的数据交换。', '{"technology startup","tech venture","emerging tech company"}', '{"应用程序接口","接口","编程接口"}', '{"startup 可连写也可 start-up，tech startup 更常用连写形式"}', 'Reading: business news; Speaking Part 2: career', '/ˈæp.ɪ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-042', 'algorithmic bias', '算法偏见', 'noun phrase', '6.5', 58, '{"technology"}', '{"reading","writing"}', '{"address algorithmic bias","algorithmic bias in AI","detect algorithmic bias","concerns about algorithmic bias"}', '{"计算机蠕虫","蠕虫病毒","网络蠕虫","蠕虫传播"}', 'Algorithmic bias in hiring tools can perpetuate discrimination against certain demographic groups.', '网络蠕虫可以自动复制并传播到其他计算机，造成大规模感染。', '{"AI bias","machine bias","data-driven discrimination","computational bias"}', '{"蠕虫病毒","计算机蠕虫","恶意蠕虫","「computational bias」的中文释义"}', '{"bias 可数/不可数均可；algorithmic 是 algorithm 的形容词形式"}', 'Reading: AI ethics; Writing Task 2: technology / ethics', '/wɜːm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-043', 'digital infrastructure', '数字基础设施', 'noun phrase', '6.5', 62, '{"technology"}', '{"writing","reading"}', '{"build digital infrastructure","lack of digital infrastructure","invest in digital infrastructure","robust digital infrastructure"}', '{"缓存机制","数据缓存","浏览器缓存","缓存策略"}', 'Developing countries need to invest in digital infrastructure to participate fully in the global economy.', '有效的缓存策略可以显著提高网站加载速度和用户体验。', '{"technological infrastructure","IT infrastructure","network infrastructure","cyber infrastructure"}', '{"高速缓存","缓冲存储","暂存","「cyber infrastructure」的中文释义"}', '{"infrastructure 不可数；通常用单数形式"}', 'Writing Task 2: development / technology; Reading: policy documents', '/ˈkæʃ.ɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-044', 'space exploration', '太空探索', 'noun phrase', '6.0', 60, '{"technology"}', '{"reading","listening"}', '{"advance space exploration","fund space exploration","space exploration mission","future of space exploration"}', '{"电磁辐射","辐射水平","辐射防护","核辐射"}', 'Private companies are now playing an increasingly important role in space exploration.', '长期暴露在高强度电磁辐射中可能对健康产生不利影响。', '{"cosmic exploration","interstellar exploration","space research","astronautics"}', '{"辐射","放射","射线","「astronautics」的中文释义"}', '{"exploration 不可数；explore 是动词，explorer 是探索者"}', 'Reading: science articles; Listening Section 4: astronomy lecture', '/ˈreɪ.di.eɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-045', 'technology addiction', '科技成瘾', 'noun phrase', '5.5', 71, '{"technology"}', '{"speaking","writing"}', '{"suffer from technology addiction","overcome technology addiction","technology addiction among youth","impact of technology addiction"}', '{"发电机","电力发电机","发电机运行","备用发电机"}', 'Technology addiction is increasingly recognized as a legitimate mental health concern requiring treatment.', '发电机在停电时为关键设施提供紧急电力供应。', '{"digital addiction","tech dependency","internet addiction","screen addiction"}', '{"发电设备","电力发生器","发电机组","「screen addiction」的中文释义"}', '{"addiction to technology，介词用 to 不是 of"}', 'Speaking Part 3: technology / health; Writing Task 2: technology / society', '/ˈdʒen.ə.reɪ.tər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-046', 'facial recognition', '面部识别', 'noun phrase', '6.5', 63, '{"technology"}', '{"reading","writing"}', '{"facial recognition technology","use facial recognition","facial recognition system","deploy facial recognition"}', '{"光纤通信","光纤网络","光纤电缆","光纤技术"}', 'The use of facial recognition technology in public spaces has sparked intense debate about privacy and civil liberties.', '光纤技术提供了远超传统铜线电缆的数据传输速度。', '{"face recognition","biometric identification","face detection technology"}', '{"光缆","光导纤维","光纤线缆"}', '{"facial 是 face 的形容词形式，不是 familiar 的缩写"}', 'Reading: technology / privacy; Writing Task 2: surveillance / privacy', '/ˈɒp.tɪ.kəl ˈfaɪ.bər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-047', 'open source software', '开源软件', 'noun phrase', '6.0', 57, '{"technology"}', '{"reading","listening"}', '{"develop open source software","open source software community","contribute to open source software","adopt open source software"}', '{"游戏机","控制台","操作台","中控台"}', 'Open source software has driven innovation by allowing developers worldwide to collaborate and build upon existing code.', '最新一代的游戏机提供了令人惊叹的图像处理能力。', '{"free software","community-developed software","public-source software","OSS"}', '{"游戏主机","控制面板","终端","「OSS」的中文释义"}', '{"open source 作为形容词有连字符 open-source；作名词无连字符"}', 'Reading: technology development; Listening Section 3: IT discussion', '/ˈkɒn.səʊl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-048', 'hybrid work model', '混合办公模式', 'noun phrase', '6.0', 61, '{"technology"}', '{"speaking","writing"}', '{"adopt a hybrid work model","hybrid work model benefits","implement a hybrid work model","shift to hybrid work models"}', '{"大型计算机","主机系统","大型机技术","主机架构"}', 'Many companies have adopted a hybrid work model that combines remote and in-office work.', '大型计算机仍然在金融和政府部门的关键任务系统中发挥着重要作用。', '{"flexible work arrangement","blended work model","mixed-mode working","hybrid workplace model"}', '{"大型主机","大型计算机","中央主机","「hybrid workplace model」的中文释义"}', '{"hybrid 发音 /ˈhaɪbrɪd/，不是 high-brid"}', 'Speaking Part 3: work trends; Writing Task 2: future of work', '/ˈmeɪn.freɪm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-049', '3D printing technology', '3D打印技术', 'noun phrase', '6.0', 55, '{"technology"}', '{"reading","listening"}', '{"advance 3D printing technology","3D printing technology enables","adopt 3D printing technology","applications of 3D printing technology"}', '{"电池寿命","锂离子电池","电池技术","更换电池"}', '3D printing technology is revolutionizing manufacturing by enabling rapid prototyping and customized production.', '电池技术的突破是推动电动汽车普及的关键因素。', '{"additive manufacturing","three-dimensional printing","rapid prototyping technology"}', '{"电池","蓄电池","电源"}', '{"3D 中的 D 大写；发音 three-dimensional"}', 'Reading: manufacturing technology; Listening Section 4: engineering lecture', '/ˈbæt.ər.i/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('tech-050', 'information overload', '信息过载', 'noun phrase', '6.0', 59, '{"technology"}', '{"writing","speaking"}', '{"suffer from information overload","cope with information overload","digital age information overload","impact of information overload"}', '{"开关","打开开关","电源开关","切换到"}', 'Information overload in the digital age can lead to reduced productivity and increased stress levels.', '这只是一个简单的开关，可以在手动和自动模式之间切换。', '{"data deluge","information glut","cognitive overload","content saturation"}', '{"切换","转换器","开关装置","「content saturation」的中文释义"}', '{"overload 不可数；是 over + load 复合词"}', 'Writing Task 2: technology / society; Speaking Part 3: modern life', '/swɪtʃ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-001', 'work-life balance', '工作生活平衡', 'noun phrase', '6.5', 85, '{"work"}', '{"writing","speaking"}', '{"maintain a healthy work-life balance","struggle with work-life balance","achieve better work-life balance"}', '{"保持工作与生活的平衡","改善工作与生活的平衡","缺乏工作与生活的平衡"}', 'Many employees today prioritize work-life balance over higher salaries.', '保持健康的工作与生活平衡对于长期职业发展和个人幸福至关重要。', '{"life-work balance","work-life equilibrium"}', '{"工作生活协调","职业与个人生活平衡"}', '{"不是 life-work balance，固定语序是 work-life balance"}', 'Speaking Part 3: work / lifestyle topics; Writing Task 2: employment', '/wɜːk laɪf ˈbæl.əns/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-001', 'mental well-being', '心理健康', 'noun phrase', '6.0', 90, '{"health"}', '{"writing","reading"}', '{"promote mental well-being","impact on mental well-being","prioritize mental well-being"}', '{"公共卫生","公共卫生系统","公共卫生政策"}', 'Regular exercise has a significant impact on both physical health and mental well-being.', '投资公共卫生是预防疾病和延长国民寿命最有效的方式。', '{"psychological well-being","mental health","emotional well-being"}', '{"公共健康","大众健康","国民健康"}', '{"mental health 更常用；well-being 注意连字符"}', 'Writing Task 2: health / lifestyle topics; Reading: health articles', '/ˈpʌb.lɪk helθ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-001', 'public transport', '公共交通', 'noun phrase', '5.5', 89, '{"city"}', '{"speaking","listening"}', '{"reliable public transport","invest in public transport","accessible public transport"}', '{"城市化进程","快速城市化","城市化率"}', 'Improving public transport is key to reducing traffic congestion in urban areas.', '快速城市化给住房、交通和环境带来了前所未有的压力。', '{"public transportation","mass transit","public transit"}', '{"都市化","城镇发展","城市化趋势"}', '{"可数/不可数均可：public transport (UK) = public transportation (US)"}', 'Speaking Part 1: hometown / transport; Listening Section 1: travel', '/ˌɜː.bən.aɪˈzeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-002', 'employment opportunities', '就业机会', 'noun phrase', '6.5', 98, '{"work"}', '{"writing","speaking"}', '{"create employment opportunities","limited employment opportunities","expand employment opportunities","access to employment opportunities"}', '{"提高工作满意度","工作满意度调查","员工工作满意度","高工作满意度"}', 'The government should invest in vocational training to expand employment opportunities for young people.', '工作满意度不仅取决于薪酬，还取决于工作环境和职业发展机会。', '{"job opportunities","job prospects","career opportunities"}', '{"职业满足感","工作满意度","职场满意度"}', '{"employment 不可数；说 job opportunities 更口语化"}', 'Writing Task 2: unemployment / government policy; Speaking Part 3: jobs', '/dʒɒb ˌsæt.ɪsˈfæk.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-003', 'job satisfaction', '工作满意度', 'noun phrase', '6.5', 97, '{"work"}', '{"writing","speaking"}', '{"high level of job satisfaction","improve job satisfaction","factors affecting job satisfaction","decline in job satisfaction"}', '{"职业发展","追求职业晋升","职业晋升机会","促进职业发展"}', 'A supportive work environment is one of the key factors affecting job satisfaction.', '持续学习和技能提升是职业发展的关键驱动力。', '{"work satisfaction","career satisfaction","occupational satisfaction"}', '{"职业晋升","职业发展","职位提升"}', '{"satisfaction 介词用 with：job satisfaction with salary"}', 'Writing Task 2: work motivation / company culture; Speaking Part 3: career', '/kəˈrɪər ədˈvɑːns.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-004', 'career advancement', '职业晋升', 'noun phrase', '6.5', 96, '{"work"}', '{"writing","speaking"}', '{"pursue career advancement","opportunities for career advancement","blocked career advancement","rapid career advancement"}', '{"职业发展","持续专业发展","专业发展计划","促进专业发展"}', 'Many employees change jobs frequently in search of better career advancement opportunities.', '许多公司为员工提供专业发展培训以保持竞争力。', '{"career progression","career growth","professional advancement"}', '{"职业培训","专业成长","职业技能提升"}', '{"advancement 不用于 physical movement，仅用于抽象晋升"}', 'Writing Task 2: career development; Speaking Part 3: ambitions', '/prəˈfeʃ.ən.əl dɪˈvel.əp.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-005', 'workplace environment', '工作环境', 'noun phrase', '6.0', 95, '{"work"}', '{"writing","speaking"}', '{"positive workplace environment","toxic workplace environment","create a safe workplace environment","competitive workplace environment"}', '{"团队合作","促进团队合作","有效的团队合作","团队合作技能"}', 'A positive workplace environment boosts employee morale and overall productivity.', '有效的团队合作是现代职场中最受重视的软技能之一。', '{"working environment","work atmosphere","office environment"}', '{"协作","团队协作","合作精神"}', '{"workplace 和 workspace 不同：workplace 泛指工作场所，workspace 指个人工位"}', 'Writing Task 2: company culture; Speaking Part 3: job preferences', '/ˈtiːm.wɜːk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-006', 'job security', '工作稳定性', 'noun phrase', '6.0', 94, '{"work"}', '{"writing","speaking"}', '{"guarantee job security","threaten job security","loss of job security","sense of job security"}', '{"领导力","培养领导力","领导技能","强大的领导力"}', 'In times of economic uncertainty, job security becomes a top priority for workers.', '优秀的领导力不仅关乎管理他人，更关乎激励和赋能团队成员。', '{"employment security","job stability","tenure security"}', '{"领导能力","领导才能","管理能力"}', '{"security 不可数，不说 a job security"}', 'Writing Task 2: employment trends / gig economy; Speaking Part 3: job market', '/ˈliː.də.ʃɪp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-007', 'professional development', '职业发展', 'noun phrase', '6.5', 93, '{"work"}', '{"writing","speaking"}', '{"invest in professional development","ongoing professional development","professional development opportunities","support professional development"}', '{"职场多元化","促进多元化","多元化和包容性","重视职场多元化"}', 'Companies that invest in employees'' professional development tend to have lower staff turnover rates.', '职场多元化能为企业带来更广泛的视角和更具创新性的解决方案。', '{"career development","vocational development","professional growth"}', '{"工作场所多样性","职场包容性","多元文化工作环境"}', '{"professional development 常见缩写 CPD (Continuing Professional Development)"}', 'Writing Task 2: education / training; Speaking Part 3: workplace learning', '/ˈwɜːk.pleɪs daɪˈvɜː.sə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-008', 'unemployment rate', '失业率', 'noun phrase', '5.5', 99, '{"work"}', '{"writing","speaking"}', '{"rising unemployment rate","reduce the unemployment rate","youth unemployment rate","official unemployment rate"}', '{"员工士气","提升员工士气","低迷的员工士气","维持员工士气"}', 'Despite technological advances, the unemployment rate in many countries remains stubbornly high.', '员工士气直接影响工作效率和公司的整体业绩。', '{"jobless rate","rate of unemployment","unemployment level"}', '{"员工积极性","团队士气","工作热情"}', '{"说 the unemployment rate 或 an unemployment rate of 5%"}', 'Writing Task 1: line graphs / bar charts; Writing Task 2: economy', '/ɪmˈplɔɪ.iː məˈrɑːl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-009', 'transferable skills', '可迁移技能', 'noun phrase', '6.5', 91, '{"work"}', '{"writing","speaking"}', '{"develop transferable skills","acquire transferable skills","demonstrate transferable skills","highly transferable skills"}', '{"提高生产力","劳动生产率","生产力增长","测量生产力"}', 'Volunteering helps young people develop transferable skills such as communication and teamwork.', '合理的工作环境和工具可以显著提高员工的生产力。', '{"portable skills","cross-functional skills","versatile skills"}', '{"生产效率","产出效率","工作效率"}', '{"transferable 两个 r：trans-fer-able"}', 'Writing Task 2: education / employment; Speaking Part 3: career preparation', '/ˌprɒd.ʌkˈtɪv.ə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-010', 'corporate culture', '企业文化', 'noun phrase', '6.5', 92, '{"work"}', '{"reading","writing"}', '{"strong corporate culture","shape corporate culture","toxic corporate culture","corporate culture transformation"}', '{"时间管理","良好的时间管理","时间管理技能","有效的时间管理"}', 'A healthy corporate culture encourages innovation and open communication among staff.', '良好的时间管理能力是高效完成工作的基础。', '{"organizational culture","company culture","business culture"}', '{"时间规划","时间统筹","时间分配"}', '{"corporate 的发音 /ˈkɔːpərət/，重音在第一音节"}', 'Reading: business articles; Writing Task 2: management', '/taɪm ˈmæn.ɪdʒ.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-011', 'salary negotiation', '薪资谈判', 'noun phrase', '6.0', 90, '{"work"}', '{"speaking","listening"}', '{"engage in salary negotiation","successful salary negotiation","salary negotiation skills","during salary negotiation"}', '{"截止日期","错过截止日期","赶上截止日期","设定截止日期"}', 'Many candidates feel uncomfortable with salary negotiation and accept the first offer they receive.', '在截止日期前交付高质量的工作是职场信誉的重要组成部分。', '{"pay negotiation","wage bargaining","compensation negotiation"}', '{"最后期限","交期","截止时间"}', '{"negotiation 拼写注意 ti 不是 ci"}', 'Speaking Part 3: workplace / career; Listening Section 3: job interview discussion', '/ˈded.laɪn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-012', 'performance evaluation', '绩效评估', 'noun phrase', '6.5', 90, '{"work"}', '{"reading","writing"}', '{"undergo performance evaluation","annual performance evaluation","conduct a performance evaluation","performance evaluation system"}', '{"工作量","沉重的工作量","管理工作量","减少工作量"}', 'Regular performance evaluations provide employees with valuable feedback for improvement.', '过重的工作量可能导致职业倦怠和健康问题。', '{"performance review","performance appraisal","performance assessment"}', '{"工作负荷","工作任务","劳动量"}', '{"evaluation 的动词是 evaluate，去 e 加 ion"}', 'Reading: HR management; Writing Task 2: workplace practices', '/ˈwɜːk.ləʊd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-013', 'job market', '就业市场', 'noun phrase', '6.0', 95, '{"work"}', '{"writing","speaking"}', '{"competitive job market","enter the job market","tight job market","global job market"}', '{"晋升","获得晋升","升职机会","晋升政策"}', 'Graduates face fierce competition when entering today''s highly competitive job market.', '出色完成项目目标通常意味着更好的晋升机会。', '{"labour market","employment market","work market"}', '{"升职","职位提升","晋级"}', '{"job market 前不总加 the：enter the job market 但 a tight job market"}', 'Writing Task 2: graduate employment; Speaking Part 3: career planning', '/prəˈməʊ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-014', 'flexible working hours', '弹性工作时间', 'noun phrase', '6.0', 93, '{"work"}', '{"writing","speaking"}', '{"offer flexible working hours","request flexible working hours","benefit from flexible working hours","introduce flexible working hours"}', '{"薪水","年薪","高薪水","薪水范围"}', 'Flexible working hours allow employees to better balance their professional and personal responsibilities.', '薪水仍然是大多数求职者选择职位时最重要的考量因素之一。', '{"flextime","flexible schedule","flexible work arrangements"}', '{"工资","薪酬","收入"}', '{"hours 必须用复数；flexible working hours 不是 flexible work hours"}', 'Writing Task 2: work-life balance; Speaking Part 3: ideal job', '/ˈsæl.ər.i/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-015', 'team collaboration', '团队协作', 'noun phrase', '5.5', 96, '{"work"}', '{"writing","speaking"}', '{"enhance team collaboration","effective team collaboration","promote team collaboration","cross-functional team collaboration"}', '{"最低工资","小时工资","工资水平","工资增长"}', 'Modern project management tools facilitate team collaboration across different time zones.', '政府定期调整最低工资标准以保障劳动者的基本生活。', '{"teamwork","group cooperation","collaborative work"}', '{"工资","薪酬","报酬"}', '{"collaboration 介词用 with：collaboration with colleagues"}', 'Writing Task 2: workplace efficiency; Speaking Part 3: teamwork', '/weɪdʒ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-016', 'staff turnover', '员工流动率', 'noun phrase', '6.5', 91, '{"work"}', '{"reading","writing"}', '{"high staff turnover","reduce staff turnover","staff turnover rate","excessive staff turnover"}', '{"加班","加班费","大量加班","强制加班"}', 'Industries with high staff turnover often struggle to maintain consistent service quality.', '长期加班不仅影响健康，还可能降低整体工作效率。', '{"employee turnover","personnel turnover","labour turnover"}', '{"超时工作","额外工时","加班工作"}', '{"turnover 在此义项下不可数；注意不是 overturn"}', 'Reading: business / HR management; Writing Task 2: employment', '/ˈəʊ.və.taɪm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-017', 'career path', '职业道路', 'noun phrase', '6.0', 90, '{"work"}', '{"writing","speaking"}', '{"choose a career path","follow a traditional career path","non-linear career path","change career path"}', '{"失业率","失业问题","青年失业","高失业率"}', 'Young people today are more likely to change their career path several times during their working life.', '青年失业是许多国家面临的重大社会经济问题。', '{"career trajectory","professional path","vocational path"}', '{"失业","待业","没有工作"}', '{"path 可搭配 different/alternative/non-traditional"}', 'Writing Task 2: career change; Speaking Part 3: ambitions', '/ˌʌn.ɪmˈplɔɪ.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-018', 'occupational health', '职业健康', 'noun phrase', '6.5', 90, '{"work"}', '{"reading","listening"}', '{"occupational health and safety","occupational health standards","occupational health risks","occupational health services"}', '{"就业市场","竞争激烈的就业市场","就业市场趋势","进入就业市场"}', 'Employers have a legal duty to protect their workers'' occupational health and safety.', '当前的就业市场对具有数字技能的专业人才需求旺盛。', '{"workplace health","industrial health","occupational wellness"}', '{"劳动力市场","就业领域","人才市场"}', '{"常缩写为 OHS (Occupational Health and Safety) 或 OSH"}', 'Reading: workplace regulations; Listening Section 4: health and safety lecture', '/dʒɒb ˈmɑːr.kɪt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-019', 'employee benefits', '员工福利', 'noun phrase', '6.0', 90, '{"work"}', '{"writing","speaking"}', '{"attractive employee benefits","comprehensive employee benefits package","provide employee benefits","cut employee benefits"}', '{"招聘过程","招聘机构","招聘策略","校园招聘"}', 'In addition to a competitive salary, the company offers a comprehensive range of employee benefits.', '有效的招聘流程是建立一支高素质团队的第一步。', '{"employee perks","staff benefits","workplace benefits"}', '{"招聘","征才","人才招募"}', '{"benefits 常用复数；perk 是更口语的说法"}', 'Writing Task 2: employment compensation; Speaking Part 3: ideal job', '/rɪˈkruːt.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-020', 'labour productivity', '劳动生产力', 'noun phrase', '6.0', 91, '{"work"}', '{"reading","writing"}', '{"boost labour productivity","measure labour productivity","decline in labour productivity","maintain high labour productivity"}', '{"实习","参加实习","实习项目","暑期实习"}', 'Studies show that regular breaks can significantly improve labour productivity and accuracy.', '实习为学生提供了将课堂知识应用于实际工作环境的机会。', '{"workforce productivity","employee output","workplace productivity"}', '{"实习","实习生项目","工作见习"}', '{"productivity 不可数；来自形容词 productive"}', 'Reading: business / economics; Writing Task 2: work efficiency', '/ˈɪn.tɜːn.ʃɪp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-021', 'labour force participation', '劳动力参与率', 'noun phrase', '6.5', 90, '{"work"}', '{"reading","writing"}', '{"labour force participation rate","increase labour force participation","declining labour force participation","female labour force participation"}', '{"学徒制","参加学徒培训","学徒计划","传统的学徒制度"}', 'The aging population has led to a gradual decline in labour force participation across developed nations.', '学徒制将实践培训和课堂教学相结合，培养技术熟练的工人。', '{"workforce participation","labour participation","economic participation"}', '{"学徒培训","职业见习","学徒工"}', '{"labour (UK) = labor (US)；两者都可用于 IELTS"}', 'Writing Task 1: demographic data; Reading: economic reports', '/əˈpren.tɪs.ʃɪp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-022', 'career prospects', '职业前景', 'noun phrase', '6.0', 85, '{"work"}', '{"writing","speaking"}', '{"bright career prospects","limited career prospects","future career prospects","improve career prospects"}', '{"同事","与同事合作","帮助同事","同事关系"}', 'Many students choose their degree based on future career prospects rather than personal interest.', '与同事建立良好的工作关系有助于营造积极的工作氛围。', '{"job prospects","career outlook","professional future"}', '{"同事","工作伙伴","同仁"}', '{"prospects 常用复数；不说 career prospect（虽然单数有时可接受）"}', 'Writing Task 2: education / employment; Speaking Part 3: university choice', '/ˈkɒl.iːɡ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-023', 'commuting time', '通勤时间', 'noun phrase', '5.5', 83, '{"work"}', '{"writing","speaking"}', '{"long commuting time","reduce commuting time","average commuting time","waste hours in commuting time"}', '{"雇主","潜在雇主","雇主品牌","雇主责任"}', 'Long commuting times have been linked to higher stress levels and reduced job satisfaction.', '一个好的雇主不仅要提供有竞争力的薪酬，还要关心员工的职业发展。', '{"travel time to work","journey time","commute duration"}', '{"用人单位","雇佣方","老板"}', '{"commuting 是 commute 的动名词；commute 既可作动词也可作名词"}', 'Speaking Part 1: daily routine; Writing Task 2: urban planning', '/ɪmˈplɔɪ.ər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-024', 'salary package', '薪资方案', 'noun phrase', '6.0', 80, '{"work"}', '{"speaking","listening"}', '{"competitive salary package","negotiate a better salary package","attractive salary package","overall salary package"}', '{"员工","雇员福利","员工培训","员工满意度"}', 'When evaluating a job offer, candidates should consider the entire salary package rather than just the base pay.', '员工是公司最宝贵的资产，他们的幸福直接影响企业的成功。', '{"compensation package","remuneration package","pay package"}', '{"雇员","职员","工作人员"}', '{"salary 和 wage 的区别：salary 通常是年薪（白领），wage 通常按小时/周计算（蓝领）"}', 'Speaking Part 3: job expectations; Listening Section 3: career advice', '/ɪmˈplɔɪ.iː/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-025', 'promotion opportunity', '晋升机会', 'noun phrase', '6.0', 82, '{"work"}', '{"writing","speaking"}', '{"limited promotion opportunities","seek promotion opportunities","equal promotion opportunities","lack of promotion opportunities"}', '{"职业倦怠","防止职业倦怠","经历职业倦怠","职业倦怠症状"}', 'A lack of promotion opportunities is often cited as the primary reason for leaving a job.', '职业倦怠已成为现代职场中越来越普遍的心理健康问题。', '{"career advancement opportunities","upward mobility","promotional prospects"}', '{"工作倦怠","职业疲劳","精力耗竭"}', '{"get a promotion（获得晋升），promotion 可数"}', 'Writing Task 2: gender equality; Speaking Part 3: career goals', '/ˈbɜːn.aʊt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-026', 'workplace diversity', '职场多元化', 'noun phrase', '6.5', 78, '{"work"}', '{"reading","writing"}', '{"promote workplace diversity","embrace workplace diversity","cultural workplace diversity","benefits of workplace diversity"}', '{"灵活工作制","推行灵活工作","灵活工作时间","灵活工作安排"}', 'Companies with strong workplace diversity tend to be more innovative and better at problem-solving.', '灵活工作安排有助于员工更好地平衡工作与家庭责任。', '{"workforce diversity","employment diversity","organizational diversity"}', '{"弹性工作","灵活工时","工作弹性"}', '{"diversity 不可数，不说 a diversity"}', 'Reading: business management; Writing Task 2: equality in workplace', '/ˈfleks.ɪ.bəl ˈwɜː.kɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-027', 'workforce shortage', '劳动力短缺', 'noun phrase', '6.5', 81, '{"work"}', '{"reading","writing"}', '{"address workforce shortage","severe workforce shortage","skilled workforce shortage","global workforce shortage"}', '{"薪资谈判","商业谈判","谈判技巧","和平谈判"}', 'The healthcare industry is facing a critical workforce shortage as demand for services continues to grow.', '出色的谈判技巧可以帮助你在求职过程中获得更好的薪酬待遇。', '{"labour shortage","staff shortage","manpower shortage"}', '{"协商","议价","商讨"}', '{"workforce 注意拼写：一个词，不是 work force"}', 'Reading: economic trends; Writing Task 2: immigration / employment policy', '/ˌneɡ.əʊ.ʃiˈeɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-028', 'vocational training', '职业培训', 'noun phrase', '6.0', 84, '{"work"}', '{"writing","speaking"}', '{"provide vocational training","undergo vocational training","vocational training programme","access to vocational training"}', '{"签署合同","劳动合同","合同条款","合同到期"}', 'Governments should invest more in vocational training to bridge the skills gap in the labour market.', '在签署劳动合同之前，务必仔细阅读所有条款和条件。', '{"technical training","job training","trade training"}', '{"协议","合约","契约"}', '{"vocational 来自 vocation（职业），不是 vacation（假期）"}', 'Writing Task 2: education policy / skills gap; Speaking Part 3: alternative to university', '/ˈkɒn.trækt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-029', 'employment contract', '劳动合同', 'noun phrase', '6.0', 76, '{"work"}', '{"reading","listening"}', '{"sign an employment contract","fixed-term employment contract","breach of employment contract","under the terms of the employment contract"}', '{"时间框架","工作框架","法律框架","参考框架"}', 'Before starting a new job, employees should carefully review their employment contract.', '我们必须在给定的时间和预算框架内完成项目。', '{"work contract","labour contract","contract of employment"}', '{"框架","结构","体系"}', '{"contract 作名词重音在前 /ˈkɒntrækt/，作动词重音在后 /kənˈtrækt/"}', 'Reading: employment law; Listening Section 3: HR discussion', '/freɪm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-030', 'working conditions', '工作条件', 'noun phrase', '6.0', 86, '{"work"}', '{"writing","speaking"}', '{"improve working conditions","poor working conditions","safe working conditions","harsh working conditions"}', '{"试用期","通过试用期","三个月的试用期","在试用期间"}', 'Improving working conditions in factories should be a priority for governments and multinational corporations.', '新员工通常需要经过三个月的试用期才能成为正式员工。', '{"work conditions","labour conditions","workplace conditions"}', '{"实习期","考察期","试工期间"}', '{"conditions 必用复数；working conditions 不是 work conditions"}', 'Writing Task 2: labour rights / globalization; Speaking Part 3: workplace', '/ˈtraɪ.əl ˈpiː.ri.əd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-031', 'job application', '求职申请', 'noun phrase', '5.5', 80, '{"work"}', '{"speaking","listening"}', '{"submit a job application","fill out a job application","successful job application","online job application"}', '{"辞职信","提交辞职","辞职通知","辞职决定"}', 'Crafting a tailored job application for each position increases the chances of securing an interview.', '他经过深思熟虑后向公司提交了辞职信，准备开启新的职业生涯。', '{"employment application","job submission","position application"}', '{"辞职","离职","请辞"}', '{"application 后介词用 for：job application for the position"}', 'Speaking Part 1: job hunting; Listening Section 2: job fair announcement', '/ˈrez.ɪɡˈneɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-032', 'trade union', '工会', 'noun phrase', '6.0', 77, '{"work"}', '{"reading","writing"}', '{"join a trade union","trade union membership","trade union representatives","powerful trade union"}', '{"裁员","被裁员","裁员补偿","被迫裁员"}', 'Trade unions play a vital role in protecting workers'' rights and negotiating fair wages.', '经济衰退导致许多公司不得不进行大规模裁员以削减成本。', '{"labour union","union","labour organization"}', '{"解雇","失业","人员精简"}', '{"trade union (UK) = labor union (US)"}', 'Reading: labour history; Writing Task 2: workers'' rights', '/rɪˈdʌn.dən.si/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-033', 'managerial position', '管理职位', 'noun phrase', '6.5', 75, '{"work"}', '{"reading","writing"}', '{"hold a managerial position","promoted to a managerial position","senior managerial position","aspire to a managerial position"}', '{"退休金","养老金计划","养老金基金","国家养老金"}', 'Women remain underrepresented in senior managerial positions across many industries.', '一个良好的养老金计划是吸引和留住优秀员工的重要因素。', '{"management position","executive role","leadership position"}', '{"退休金","养老储蓄","年金"}', '{"managerial 是 manager 的形容词形式；注意拼写：-erial 不是 -eriall"}', 'Reading: gender equality; Writing Task 2: workplace inequality', '/ˈpen.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-034', 'working remotely', '远程办公', 'noun phrase', '6.0', 88, '{"work"}', '{"writing","speaking"}', '{"prefer working remotely","adapt to working remotely","challenges of working remotely","advantages of working remotely"}', '{"事业","商业项目","重大的事业","慈善项目"}', 'Working remotely has become the new normal for millions of office workers since the pandemic.', '创业是一个充满挑战但也极其有回报的事业。', '{"telecommuting","remote work","working from home"}', '{"事业","项目","企业"}', '{"remotely 副词；remote 形容词。说 work remotely 不是 work remote"}', 'Writing Task 2: future of work; Speaking Part 3: lifestyle changes', '/ˌʌn.dəˈteɪ.kɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-035', 'freelance work', '自由职业', 'noun phrase', '6.0', 79, '{"work"}', '{"writing","speaking"}', '{"engage in freelance work","pursue freelance work","full-time freelance work","secure freelance work"}', '{"新员工","招聘","雇佣新员工","最近的招聘"}', 'The gig economy has made freelance work a viable career option for millions of professionals.', '公司计划今年招聘50名新员工以支持业务扩展。', '{"self-employment","independent contracting","freelancing"}', '{"新员工","聘用","招募"}', '{"freelance 可以作形容词、名词(freelancer)、动词(to freelance)"}', 'Writing Task 2: gig economy; Speaking Part 3: work trends', '/ˈhaɪ.ər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-036', 'career break', '职业中断', 'noun phrase', '6.0', 73, '{"work"}', '{"speaking","listening"}', '{"take a career break","extended career break","returning from a career break","voluntary career break"}', '{"队友","同事","室友","同学"}', 'Taking a career break to travel or raise children is becoming increasingly accepted by employers.', '一个好队友会在你需要帮助的时候伸出援手。', '{"career gap","employment gap","career hiatus"}', '{"同事","伙伴","搭档"}', '{"break 应与 gap 区分：career break 是主动选择，unemployment gap 是被动失业"}', 'Speaking Part 1: career history; Listening Section 3: career counseling', '/meɪt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-037', 'apprenticeship programme', '学徒项目', 'noun phrase', '6.0', 71, '{"work"}', '{"listening","reading"}', '{"enrol in an apprenticeship programme","apprenticeship programme provider","complete an apprenticeship programme","government-funded apprenticeship programme"}', '{"报价","引用一段话","股票报价","提供报价"}', 'Apprenticeship programmes offer a practical alternative to university education for many young people.', '在开始工作之前，请确保您已经从供应商那里获得了详细的报价。', '{"trainee programme","vocational apprenticeship","skills training programme"}', '{"报价","引述","摘录"}', '{"apprenticeship 双 p：apprentice + ship（状态）"}', 'Listening Section 2: course information; Reading: education alternatives', '/kwəʊt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-038', 'income inequality', '收入不平等', 'noun phrase', '6.5', 84, '{"work"}', '{"writing","speaking"}', '{"address income inequality","rising income inequality","reduce income inequality","growing income inequality"}', '{"筛选","仔细筛选","筛选简历","筛选申请"}', 'Rising income inequality has become one of the most pressing economic challenges of our time.', '人力资源部门需要仔细筛选数百份简历来找到合适的候选人。', '{"income disparity","wage inequality","earnings gap"}', '{"筛选","过滤","精选"}', '{"inequality 不可数；注意区别 wealth inequality（财富不平等）"}', 'Writing Task 2: economic policy / social justice; Speaking Part 3: society', '/sɪft/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-039', 'skills gap', '技能缺口', 'noun phrase', '6.5', 68, '{"work"}', '{"reading","writing"}', '{"bridge the skills gap","address the skills gap","widening skills gap","technical skills gap"}', '{"推动力","积极进取","开车","驱动器"}', 'Employers across the technology sector report a persistent skills gap between graduate capabilities and industry needs.', '内在的驱动力是持续学习和职业成长的关键。', '{"skill shortage","competency gap","qualifications gap"}', '{"动力","驱动力","动机"}', '{"gap 搭配 bridge/close/narrow/address；不说 solve the gap"}', 'Reading: education / employment; Writing Task 2: education reform', '/draɪv/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-040', 'sick leave', '病假', 'noun phrase', '5.5', 65, '{"work"}', '{"speaking","listening"}', '{"take sick leave","paid sick leave","entitled to sick leave","extended sick leave"}', '{"行业","贸易","技术行业","公平贸易"}', 'Employees should not feel pressured to work when they are ill, as sick leave exists to protect both workers and colleagues.', '学习一门技术行业可以为您的职业生涯提供稳定的基础。', '{"medical leave","sickness absence","health leave"}', '{"行业","职业","行当"}', '{"sick leave 是固定搭配；leave 此处不可数"}', 'Speaking Part 1: work; Listening Section 1: absence reporting', '/treɪd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-041', 'performance bonus', '绩效奖金', 'noun phrase', '6.0', 63, '{"work"}', '{"speaking","listening"}', '{"receive a performance bonus","annual performance bonus","eligible for a performance bonus","performance bonus scheme"}', '{"企业家","成功的企业家","企业家精神","青年企业家"}', 'The company offers a generous annual performance bonus to employees who exceed their targets.', '成功的企业家往往具备创新思维和承担风险的勇气。', '{"merit bonus","incentive pay","performance incentive"}', '{"创业者","企业家","创业家"}', '{"bonus 复数 bonuses（不是 boni）"}', 'Speaking Part 3: work motivation; Listening Section 3: HR presentation', '/ˈent.rə.prəˌnɜːr/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-042', 'labour rights', '劳工权益', 'noun phrase', '6.5', 61, '{"work"}', '{"reading","writing"}', '{"protect labour rights","violate labour rights","basic labour rights","labour rights violations"}', '{"加薪","提高","筹集资金","引起关注"}', 'International organizations have called for stricter enforcement of labour rights in global supply chains.', '她在年度评估后获得了不错的加薪。', '{"workers'' rights","employee rights","labour standards"}', '{"加薪","提升","增加"}', '{"labour rights 常用复数；表示多项权利的整体"}', 'Reading: globalization / ethics; Writing Task 2: corporate social responsibility', '/ˈreɪz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-043', 'job burnout', '职业倦怠', 'noun phrase', '6.5', 66, '{"work"}', '{"reading","writing"}', '{"experience job burnout","prevent job burnout","symptoms of job burnout","severe job burnout"}', '{"员工福利","福利待遇","健康福利","享受福利"}', 'Chronic overwork and high pressure can lead to job burnout, affecting both personal well-being and professional performance.', '有竞争力的员工福利计划包括医疗保险、带薪休假和退休储蓄。', '{"occupational burnout","work exhaustion","career burnout"}', '{"福利","好处","利益"}', '{"burnout 一个词（名词）；burn out 两个词（短语动词）"}', 'Reading: workplace psychology; Writing Task 2: work culture', '/ˈben.ɪ.fɪt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-044', 'career ladder', '职业阶梯', 'noun phrase', '6.0', 62, '{"work"}', '{"writing","speaking"}', '{"climb the career ladder","move up the career ladder","bottom rung of the career ladder","corporate career ladder"}', '{"轮班工作","夜班","倒班","值班"}', 'Mentoring programmes can help junior staff climb the career ladder more quickly.', '轮班工作在医疗、制造和客户服务行业中非常普遍。', '{"corporate ladder","promotion ladder","professional hierarchy"}', '{"轮班","排班","换班"}', '{"climb the career ladder 是隐喻，ladder 在此不指实物"}', 'Writing Task 2: career development; Speaking Part 3: ambition', '/ʃɪft/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-045', 'shift work', '轮班工作', 'noun phrase', '5.5', 67, '{"work"}', '{"listening","reading"}', '{"do shift work","night shift work","rotating shift work","shift work schedule"}', '{"绩效奖金","年终奖金","奖金计划","发放奖金"}', 'Long-term shift work can disrupt the body''s natural circadian rhythms and lead to chronic health issues.', '绩效奖金是激励员工超额完成工作目标的有效手段。', '{"rotating work","shift-based employment","alternating shifts"}', '{"奖金","红利","额外报酬"}', '{"shift 的常见搭配：day/night/evening/graveyard shift"}', 'Listening Section 1: job interview; Reading: occupational health', '/bəʊ.nəs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-046', 'minimum wage', '最低工资', 'noun phrase', '6.0', 69, '{"work"}', '{"writing","speaking"}', '{"raise the minimum wage","above minimum wage","statutory minimum wage","living wage vs minimum wage"}', '{"优势","有利地位","独特优势","竞争优势"}', 'Proponents argue that raising the minimum wage helps lift low-income families out of poverty.', '掌握多门外语在就业市场中具有明显的竞争优势。', '{"base pay","statutory minimum","wage floor"}', '{"优势","有利条件","好处"}', '{"minimum wage 前用 the：the minimum wage（政策层面）"}', 'Writing Task 2: economic policy / poverty; Speaking Part 3: inequality', '/ˈvæn.tɪdʒ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-047', 'desk job', '文职工作', 'noun phrase', '5.5', 64, '{"work"}', '{"speaking","writing"}', '{"sedentary desk job","typical desk job","stuck in a desk job","leave a desk job"}', '{"新人","大一新生","新入职者","新来的"}', 'Having a desk job often means sitting for eight or more hours a day, which poses serious health risks.', '作为职场新人，虚心学习和积极融入团队非常重要。', '{"office job","white-collar job","administrative job"}', '{"新人","初学者","新员工"}', '{"desk job 不是 desk work（后者指在办公桌上做的事）"}', 'Speaking Part 1: daily routine; Writing Task 2: health and lifestyle', '/ˈfreʃ.mən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-048', 'exit interview', '离职面谈', 'noun phrase', '6.0', 55, '{"work"}', '{"listening","speaking"}', '{"conduct an exit interview","attend an exit interview","exit interview feedback","exit interview process"}', '{"框架","工作框架","理论框架","管理框架"}', 'Exit interviews provide valuable insight into why employees leave and how the organization can improve.', '一个清晰的框架有助于组织思路并确保项目的系统推进。', '{"departure interview","leaving interview","separation interview"}', '{"框架","结构体系","纲要"}', '{"exit interview 是离职面谈；exit exam 是毕业考试 — 不同概念"}', 'Listening Section 3: HR discussion; Speaking Part 3: job change', '/ˈfreɪm.wɜːk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-049', 'economic inactivity', '经济不活跃', 'noun phrase', '6.5', 58, '{"work"}', '{"reading","listening"}', '{"rising economic inactivity","economic inactivity rate","long-term economic inactivity","reasons for economic inactivity"}', '{"居民区","住宅","住宅建筑","住宅项目"}', 'Economic inactivity among working-age adults has risen sharply in regions affected by industrial decline.', '许多远程工作者选择搬到生活成本更低的住宅区域。', '{"non-participation","labour market inactivity","economic non-engagement"}', '{"住宅的","居住的","家居的"}', '{"economic inactivity 不等于 unemployment：失业的人在 actively seeking work"}', 'Reading: economic analysis; Listening Section 4: economics lecture', '/ˌrez.ɪˈden.ʃəl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('work-050', 'manual labour', '体力劳动', 'noun phrase', '5.5', 52, '{"work"}', '{"reading","writing"}', '{"perform manual labour","heavy manual labour","decline in manual labour","skilled manual labour"}', '{"在在于","位于","在于","躺下"}', 'Automation has significantly reduced the demand for manual labour in manufacturing industries.', '这个问题的核心在于缺乏有效的沟通渠道。', '{"physical labour","blue-collar work","manual work"}', '{"在于","位于","存在"}', '{"labour 此处不可数；作 ''劳工'' 义项时集合名词（不可数）"}', 'Writing Task 2: automation / employment; Reading: industrial history', '/laɪ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-002', 'physical health', '身体健康', 'noun phrase', '6.0', 99, '{"health"}', '{"writing","speaking"}', '{"maintain physical health","benefit physical health","impact on physical health","neglect physical health"}', '{"心理健康","提高心理健康意识","心理健康问题","心理健康服务"}', 'Regular exercise is essential for maintaining both physical health and mental well-being.', '心理健康与身体健康同等重要，需要得到同等重视。', '{"bodily health","physical well-being","physical fitness"}', '{"心理卫生","精神健康","心理福祉"}', '{"physical health 是相对 mental health 的概念；不加 s"}', 'Writing Task 2: health / lifestyle; Speaking Part 3: healthy habits', '/ˈmen.təl helθ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-003', 'healthy lifestyle', '健康生活方式', 'noun phrase', '6.0', 98, '{"health"}', '{"writing","speaking"}', '{"adopt a healthy lifestyle","promote a healthy lifestyle","lead a healthy lifestyle","maintain a healthy lifestyle"}', '{"体能","保持身体健康","体能测试","体能水平"}', 'Schools should educate children about the importance of maintaining a healthy lifestyle from an early age.', '定期锻炼是维持良好体能的必要条件。', '{"health-conscious lifestyle","wholesome lifestyle","health-promoting lifestyle"}', '{"身体健康","身体素质","体格"}', '{"lifestyle 可数，说 a healthy lifestyle"}', 'Writing Task 2: public health / education; Speaking Part 3: daily habits', '/ˈfɪz.ɪ.kəl ˈfɪt.nəs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-004', 'sedentary lifestyle', '久坐生活方式', 'noun phrase', '6.5', 96, '{"health"}', '{"writing","speaking"}', '{"lead a sedentary lifestyle","associated with a sedentary lifestyle","risks of a sedentary lifestyle","increasingly sedentary lifestyle"}', '{"营养","良好的营养","营养不足","营养学"}', 'A sedentary lifestyle has been linked to an increased risk of obesity, diabetes, and cardiovascular disease.', '均衡的营养对所有年龄段的人的健康都至关重要。', '{"inactive lifestyle","sitting-based lifestyle","physically inactive lifestyle"}', '{"营养学","饮食营养","营养素"}', '{"sedentary 发音 /ˈsednteri/，来自拉丁语 sedere（坐）"}', 'Writing Task 2: modern lifestyle / health risks; Speaking Part 3: workplace health', '/njuːˈtrɪʃ.ən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-005', 'balanced diet', '均衡饮食', 'noun phrase', '5.5', 97, '{"health"}', '{"writing","speaking"}', '{"maintain a balanced diet","eat a balanced diet","follow a balanced diet","lack of a balanced diet"}', '{"肥胖症","儿童肥胖","肥胖率","预防肥胖"}', 'A balanced diet rich in fruits, vegetables, and whole grains is the foundation of good health.', '儿童肥胖率上升已成为全球公共卫生的重大挑战。', '{"healthy diet","nutritious diet","well-rounded diet"}', '{"过度肥胖","超重","肥胖问题"}', '{"balanced diet 前用 a；区别于 dietary balance（更学术）"}', 'Writing Task 2: nutrition / health education; Speaking Part 1: food / diet', '/əʊˈbiː.sə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-006', 'mental disorder', '精神障碍', 'noun phrase', '6.5', 92, '{"health"}', '{"reading","writing"}', '{"suffer from a mental disorder","diagnose a mental disorder","common mental disorder","treat mental disorders"}', '{"久坐的生活方式","避免久坐生活","改变久坐的生活方式","久坐生活方式导致的疾病"}', 'Depression is one of the most common mental disorders, affecting millions of people worldwide.', '久坐的生活方式与多种慢性疾病的风险增加有关。', '{"psychiatric disorder","mental illness","psychological disorder"}', '{"缺乏运动的生活","静态生活方式","不活跃生活"}', '{"mental disorder 比 mental illness 更临床、更正式"}', 'Reading: health / psychology articles; Writing Task 2: mental health', '/ˈsed.ən.tər.i ˈlaɪf.staɪl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-007', 'public health', '公共卫生', 'noun phrase', '6.5', 98, '{"health"}', '{"reading","writing"}', '{"protect public health","threaten public health","public health crisis","public health policy"}', '{"医疗保健系统","完善医疗系统","医疗改革","公共医疗系统"}', 'Vaccination programmes are one of the most effective public health interventions in history.', '一个高效的医疗保健系统应该在成本和质量之间取得平衡。', '{"community health","population health","public healthcare"}', '{"卫生系统","医疗体系","健康服务体系"}', '{"public health 不加 the；泛指概念时零冠词"}', 'Reading: public health reports; Writing Task 2: government health policy', '/ˈhelθ.keər ˈsɪs.təm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-008', 'healthcare system', '医疗保健体系', 'noun phrase', '6.5', 95, '{"health"}', '{"writing","speaking"}', '{"universal healthcare system","overburdened healthcare system","reform the healthcare system","access to the healthcare system"}', '{"疫苗接种","疫苗接种计划","疫苗接种率","接种疫苗"}', 'An efficient healthcare system is essential for ensuring that all citizens receive timely medical treatment.', '广泛的疫苗接种是控制传染性疾病传播最有效的公共卫生措施之一。', '{"medical system","health system","health service"}', '{"预防接种","免疫接种","打疫苗"}', '{"healthcare 一个词（英式）或 health care 两个词（美式）；IELTS 两种均接受"}', 'Writing Task 2: government spending / health policy; Speaking Part 3: public services', '/ˌvæk.sɪˈneɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-009', 'chronic disease', '慢性疾病', 'noun phrase', '6.5', 93, '{"health"}', '{"reading","writing"}', '{"suffer from a chronic disease","manage chronic disease","prevent chronic disease","chronic disease burden"}', '{"预期寿命","提高预期寿命","平均预期寿命","预期寿命增长"}', 'The rising prevalence of chronic diseases such as diabetes places an enormous strain on healthcare budgets.', '医疗进步和卫生条件改善显著提高了全球人口的预期寿命。', '{"long-term illness","chronic illness","non-communicable disease"}', '{"平均寿命","寿命预期","人均寿命"}', '{"chronic /ˈkrɒnɪk/ 不是 acute（急性）；chronic 强调长期性"}', 'Reading: medical reports; Writing Task 2: aging population / health costs', '/laɪf ɪkˈspek.tən.si/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-010', 'life expectancy', '预期寿命', 'noun phrase', '6.5', 96, '{"health"}', '{"reading","writing"}', '{"increase life expectancy","average life expectancy","life expectancy has risen","longer life expectancy"}', '{"慢性疾病","管理慢性疾病","慢性疾病预防","患有慢性疾病"}', 'Improved sanitation and medical advances have dramatically increased life expectancy over the past century.', '生活方式干预对预防和管理慢性疾病至关重要。', '{"longevity","expected lifespan","average lifespan"}', '{"慢性病","长期疾病","持续性病症"}', '{"life expectancy 不可数/可数均可；常用单数"}', 'Writing Task 1: demographic data; Writing Task 2: aging society', '/ˈkrɒn.ɪk dɪˈziːz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-011', 'physical activity', '身体活动', 'noun phrase', '5.5', 94, '{"health"}', '{"writing","speaking"}', '{"engage in physical activity","lack of physical activity","regular physical activity","benefits of physical activity"}', '{"传染病","控制传染病","传染病爆发","传染病预防"}', 'Children should engage in at least one hour of moderate physical activity every day.', '全球化为传染病的快速传播创造了前所未有的条件。', '{"exercise","bodily activity","physical exercise"}', '{"传染病","感染性疾病","传播性疾病"}', '{"physical activity 比 exercise 涵盖更广（包括日常活动如走路、爬楼梯）"}', 'Writing Task 2: children''s health / lifestyle; Speaking Part 3: fitness', '/ɪnˈfek.ʃəs dɪˈziːz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-012', 'health insurance', '健康保险', 'noun phrase', '6.0', 91, '{"health"}', '{"writing","speaking"}', '{"purchase health insurance","comprehensive health insurance","lack health insurance","private health insurance"}', '{"预防医学","预防医疗","定期预防体检","预防医疗保健"}', 'In countries without universal healthcare, health insurance is essential for accessing affordable medical care.', '预防医学专注于在疾病发生之前识别并消除风险因素。', '{"medical insurance","health coverage","medical coverage"}', '{"预防性医疗","疾病预防","保健医学"}', '{"insurance 不可数；说 buy/provide/have health insurance（不加 s）"}', 'Writing Task 2: healthcare funding; Speaking Part 3: medical costs', '/prɪˈven.tɪv ˈmed.ɪ.sɪn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-013', 'obesity epidemic', '肥胖流行病', 'noun phrase', '6.5', 94, '{"health"}', '{"reading","writing"}', '{"tackle the obesity epidemic","combat the obesity epidemic","rising obesity epidemic","obesity epidemic among children"}', '{"健康意识","提高健康意识","健康意识活动","公众健康意识"}', 'The obesity epidemic is driven by a combination of poor diet, sedentary lifestyles, and aggressive food marketing.', '提高公众健康意识是减少可预防疾病的关键策略。', '{"obesity crisis","overweight epidemic","weight problem epidemic"}', '{"健康认知","卫生意识","保健意识"}', '{"epidemic 本义是传染病流行；比喻义为问题蔓延；obesity 发音 /əʊˈbiːsəti/"}', 'Reading: health / nutrition articles; Writing Task 2: junk food / public health', '/helθ əˈweə.nəs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-014', 'stress management', '压力管理', 'noun phrase', '6.0', 91, '{"health"}', '{"writing","speaking"}', '{"effective stress management","stress management techniques","practice stress management","poor stress management"}', '{"压力管理","学习压力管理","压力管理技巧","有效的压力管理"}', 'Employers should offer stress management workshops to help employees cope with workplace pressure.', '学习压力管理技巧有助于预防职业倦怠和维护心理健康。', '{"stress relief","coping strategies","stress reduction"}', '{"减压管理","压力缓解","压力应对"}', '{"stress management 不是 pressure management；stress 是长期压力，pressure 是短期压力"}', 'Writing Task 2: workplace wellness; Speaking Part 3: modern life pressures', '/stres ˈmæn.ɪdʒ.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-015', 'medical treatment', '医疗治疗', 'noun phrase', '6.0', 92, '{"health"}', '{"reading","listening"}', '{"receive medical treatment","seek medical treatment","access to medical treatment","delay medical treatment"}', '{"幸福感","心理福祉","员工福祉","促进福祉"}', 'Early diagnosis and prompt medical treatment significantly improve recovery outcomes for most conditions.', '身心健康是衡量生活质量和幸福感的综合指标。', '{"healthcare treatment","therapeutic treatment","clinical treatment"}', '{"幸福","安康","身心健康"}', '{"treatment 可数/不可数：medical treatment（整体）/ a new treatment（具体疗法）"}', 'Reading: health articles; Listening Section 3: health center consultation', '/ˌwel ˈbiː.ɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-016', 'nutritional intake', '营养摄入', 'noun phrase', '6.5', 90, '{"health"}', '{"reading","writing"}', '{"adequate nutritional intake","daily nutritional intake","monitor nutritional intake","insufficient nutritional intake"}', '{"饮食习惯","改变饮食习惯","不健康的饮食习惯","良好的饮食习惯"}', 'Poor nutritional intake in early childhood can have lasting effects on cognitive development.', '从小养成健康的饮食习惯对预防慢性疾病非常重要。', '{"dietary intake","nutrient consumption","nutritional consumption"}', '{"进食习惯","饮食模式","饮食行为"}', '{"nutritional 和 nutritious 不同：nutritional = 关于营养的，nutritious = 有营养的"}', 'Reading: nutrition science; Writing Task 2: children''s health', '/ˈdaɪ.ə.tər.i ˈhæb.ɪts/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-017', 'cardiovascular disease', '心血管疾病', 'noun phrase', '6.5', 91, '{"health"}', '{"reading","listening"}', '{"risk of cardiovascular disease","prevent cardiovascular disease","develop cardiovascular disease","cardiovascular disease prevention"}', '{"垃圾食品","减少垃圾食品消费","垃圾食品广告","垃圾食品的危害"}', 'Smoking, poor diet, and physical inactivity are the leading causes of cardiovascular disease worldwide.', '经常食用垃圾食品与肥胖和心血管疾病的风险增加有关。', '{"heart disease","CVD","coronary artery disease"}', '{"不健康食品","快餐食品","高热量零食"}', '{"cardiovascular 来自 cardio（心脏）+ vascular（血管）"}', 'Reading: medical / health articles; Listening Section 4: health lecture', '/dʒʌŋk fuːd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-018', 'immune system', '免疫系统', 'noun phrase', '6.0', 93, '{"health"}', '{"reading","listening"}', '{"weakened immune system","strengthen the immune system","compromised immune system","boost your immune system"}', '{"均衡饮食","保持均衡饮食","均衡饮食的重要性","饮食均衡"}', 'Adequate sleep and proper nutrition are critical for maintaining a strong immune system.', '均衡饮食应包含足够的蛋白质、碳水化合物、脂肪、维生素和矿物质。', '{"body''s defences","immunological system","disease defence system"}', '{"平衡膳食","营养均衡饮食","健康饮食"}', '{"immune 发音 /ɪˈmjuːn/；注意区别于 immune to（对...免疫）"}', 'Reading: health / biology; Listening Section 4: science lecture', '/ˈbæl.ənst ˈdaɪ.ət/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-019', 'sleep deprivation', '睡眠不足', 'noun phrase', '6.5', 93, '{"health"}', '{"reading","writing"}', '{"chronic sleep deprivation","suffer from sleep deprivation","effects of sleep deprivation","severe sleep deprivation"}', '{"锻炼习惯","定期锻炼计划","养成锻炼习惯","每日锻炼"}', 'Chronic sleep deprivation impairs cognitive function and increases the risk of accidents and chronic diseases.', '建立规律的锻炼习惯是维持长期健康的关键。', '{"sleep deficiency","insufficient sleep","sleep shortage"}', '{"运动计划","锻炼方案","健身常规"}', '{"deprivation 不可数；动词 deprive someone of sleep"}', 'Reading: health studies; Writing Task 2: modern lifestyle / student stress', '/ˈek.sə.saɪz ruːˈtiːn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-020', 'substance abuse', '药物滥用', 'noun phrase', '6.5', 94, '{"health"}', '{"reading","writing"}', '{"struggle with substance abuse","treat substance abuse","substance abuse problem","substance abuse among teenagers"}', '{"心血管健康","心血管疾病","心血管系统","心血管锻炼"}', 'Substance abuse among young people is a growing public health crisis that requires early intervention.', '经常进行有氧运动有助于改善心血管健康状况。', '{"drug abuse","substance misuse","chemical dependency"}', '{"心脏血管","心血管的","循环系统"}', '{"substance 在此义项下指药物、酒精等成瘾物质"}', 'Reading: social issues / health; Writing Task 2: youth problems', '/ˌkɑːr.di.əʊˈvæs.kjʊ.lər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-021', 'health awareness', '健康意识', 'noun phrase', '6.0', 84, '{"health"}', '{"writing","speaking"}', '{"raise health awareness","increase health awareness","public health awareness","lack of health awareness"}', '{"免疫系统","增强免疫系统","免疫系统功能","弱化免疫系统"}', 'Health awareness campaigns have played a crucial role in reducing smoking rates across many countries.', '充足的睡眠和均衡的饮食对维持健康的免疫系统至关重要。', '{"health consciousness","wellness awareness","health literacy"}', '{"免疫力","免疫机制","防御系统"}', '{"awareness 不可数；搭配 raise/increase/promote"}', 'Writing Task 2: public health campaigns; Speaking Part 3: health education', '/ɪˈmjuːn ˈsɪs.təm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-022', 'dietary habits', '饮食习惯', 'noun phrase', '6.0', 86, '{"health"}', '{"writing","speaking"}', '{"unhealthy dietary habits","improve dietary habits","poor dietary habits","develop dietary habits"}', '{"诊断","早期诊断","做出诊断","诊断结果"}', 'Children''s dietary habits formed in early years tend to persist into adulthood.', '早期诊断和治疗显著提高了许多癌症患者的生存率。', '{"eating habits","nutritional habits","food habits"}', '{"诊断","确诊","判断"}', '{"dietary 是 diet 的形容词；发音 /ˈdaɪətəri/"}', 'Writing Task 2: nutrition / children''s health; Speaking Part 1: food', '/ˌdaɪ.əɡˈnəʊ.sɪs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-023', 'preventive care', '预防性护理', 'noun phrase', '6.5', 79, '{"health"}', '{"reading","writing"}', '{"invest in preventive care","emphasize preventive care","access to preventive care","preventive care services"}', '{"治疗方案","接受治疗","治疗方法","药物治疗"}', 'Investing in preventive care is far more cost-effective than treating advanced diseases.', '个性化的治疗方案能够更有效地应对每个患者的具体情况。', '{"preventive medicine","preventative care","proactive healthcare"}', '{"疗法","诊治","医治"}', '{"preventive 和 preventative 均可，preventive 更常用于学术语境"}', 'Reading: healthcare policy; Writing Task 2: government health spending', '/ˈtriːt.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-024', 'health screening', '健康筛查', 'noun phrase', '6.0', 75, '{"health"}', '{"reading","listening"}', '{"routine health screening","undergo health screening","regular health screening","national health screening programme"}', '{"症状","出现症状","早期症状","流感症状"}', 'Regular health screening can detect diseases at an early stage when they are more treatable.', '如果你出现任何新冠肺炎症状，应该立即进行检测并自我隔离。', '{"medical screening","health check-up","diagnostic screening"}', '{"症状","征兆","临床表现"}', '{"screening 不可数（作过程）；screen 是可数名词/动词"}', 'Reading: medical procedures; Listening Section 3: health centre information', '/ˈsɪmp.təm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-025', 'fast food consumption', '快餐消费', 'noun phrase', '6.0', 82, '{"health"}', '{"writing","speaking"}', '{"excessive fast food consumption","reduce fast food consumption","rise in fast food consumption","cut down on fast food consumption"}', '{"治疗方案","物理治疗","心理治疗","基因疗法"}', 'The dramatic rise in fast food consumption has been linked to increasing rates of obesity and related diseases.', '认知行为疗法是治疗焦虑和抑郁最有效的心理疗法之一。', '{"junk food intake","convenience food consumption","fast-food eating"}', '{"治疗","疗法","康复治疗"}', '{"fast food 中 fast 是形容词（快的），不是动词"}', 'Writing Task 2: diet / public health; Speaking Part 1: eating habits', '/ˈθer.ə.pi/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-026', 'psychological counselling', '心理咨询', 'noun phrase', '6.5', 74, '{"health"}', '{"reading","listening"}', '{"seek psychological counselling","provide psychological counselling","access psychological counselling","benefit from psychological counselling"}', '{"流行病","疫情爆发","控制流行病","流行病学"}', 'Universities should offer free psychological counselling services to support students'' mental well-being.', '肥胖已成为一种全球性流行病，影响着发达国家和发展中国家。', '{"mental health counselling","therapy","psychological therapy"}', '{"传染病流行","瘟疫","疾病蔓延"}', '{"counselling (UK) = counseling (US)；双 l 是英式拼写"}', 'Reading: mental health services; Listening Section 3: student services', '/ˈep.ɪ.dem.ɪk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-027', 'medical breakthrough', '医学突破', 'noun phrase', '6.0', 78, '{"health"}', '{"reading","listening"}', '{"major medical breakthrough","achieve a medical breakthrough","recent medical breakthrough","scientific medical breakthrough"}', '{"大流行病","全球大流行","大流行应对","宣布大流行"}', 'The development of mRNA vaccines represents one of the most significant medical breakthroughs of the 21st century.', '新冠疫情提醒世界，全球大流行病的威胁始终存在。', '{"medical advance","scientific breakthrough","healthcare breakthrough"}', '{"全球流行病","大规模疫情","全球性传染病"}', '{"breakthrough 可数，一个重大突破 a breakthrough"}', 'Reading: medical / science articles; Listening Section 4: scientific lecture', '/pænˈdem.ɪk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-028', 'eating disorder', '进食障碍', 'noun phrase', '6.5', 76, '{"health"}', '{"reading","writing"}', '{"suffer from an eating disorder","develop an eating disorder","treat eating disorders","eating disorder among adolescents"}', '{"卫生的","卫生条件","卫生标准","清洁卫生"}', 'Social media has been implicated in the rising prevalence of eating disorders among teenagers.', '保持良好的个人卫生习惯对于预防疾病传播至关重要。', '{"disordered eating","eating disturbance","food-related disorder"}', '{"卫生的","清洁的","保健的"}', '{"常见 eating disorders：anorexia (厌食症), bulimia (贪食症), binge eating (暴食)"}', 'Reading: psychology / health; Writing Task 2: media influence / body image', '/hɪˈdʒiː.nɪk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-029', 'health expenditure', '医疗支出', 'noun phrase', '6.5', 80, '{"health"}', '{"reading","writing"}', '{"rising health expenditure","government health expenditure","control health expenditure","health expenditure per capita"}', '{"和谐","社会和谐","与自然和谐相处","和谐关系"}', 'Rising health expenditure is a major concern for governments facing aging populations.', '身心健康有助于实现工作与生活的和谐。', '{"healthcare spending","medical expenditure","health spending"}', '{"和谐","协调","平衡"}', '{"expenditure 不可数；介词搭配 expenditure on health/education"}', 'Writing Task 1: economic data; Reading: government reports', '/ˈhɑːr.mə.ni/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-030', 'fitness regimen', '健身计划', 'noun phrase', '6.0', 71, '{"health"}', '{"speaking","listening"}', '{"follow a fitness regimen","strict fitness regimen","maintain a fitness regimen","start a fitness regimen"}', '{"药剂师","咨询药剂师","社区药剂师","注册药剂师"}', 'Adopting a regular fitness regimen can improve both physical health and mental clarity.', '药剂师可以提供关于处方药和非处方药的用药指导。', '{"exercise routine","workout plan","training regimen"}', '{"药师","调剂师","药剂专家"}', '{"regimen /ˈredʒɪmən/ 不是 regime /reɪˈʒiːm/（政权）"}', 'Speaking Part 1: hobbies / exercise; Listening Section 1: gym membership', '/ˈfɑː.mə.sɪst/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-031', 'vaccination programme', '疫苗接种计划', 'noun phrase', '6.0', 85, '{"health"}', '{"reading","writing"}', '{"implement a vaccination programme","national vaccination programme","childhood vaccination programme","successful vaccination programme"}', '{"血清素","血清素水平","提高血清素","血清素缺乏"}', 'Mass vaccination programmes have eradicated or dramatically reduced many life-threatening infectious diseases.', '运动和阳光照射可以自然提高体内的血清素水平，改善情绪。', '{"immunization programme","vaccination campaign","inoculation programme"}', '{"5-羟色胺","血清张力素","快乐激素"}', '{"vaccination 和 immunization 常互换；vaccination 强调接种行为本身"}', 'Writing Task 2: public health policy; Reading: health reports', '/ˈser.ə.təʊ.nɪn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-032', 'health education', '健康教育', 'noun phrase', '6.0', 83, '{"health"}', '{"writing","speaking"}', '{"promote health education","school-based health education","provide health education","comprehensive health education"}', '{"按摩","按摩疗法","颈部和肩部按摩","放松按摩"}', 'Comprehensive health education in schools can equip children with the knowledge to make informed lifestyle choices.', '定期按摩有助于缓解肌肉紧张和改善血液循环。', '{"public health education","wellness education","health literacy education"}', '{"推拿","按摩疗法","舒压按摩"}', '{"health education 不可数；泛指概念前不加冠词"}', 'Writing Task 2: school curriculum / public health; Speaking Part 3: education', '/ˈmæs.ɑːʒ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-033', 'patient care', '患者护理', 'noun phrase', '6.0', 81, '{"health"}', '{"reading","listening"}', '{"improve patient care","quality of patient care","patient-centred care","provide patient care"}', '{"检测","早期检测","癌症检测","检测方法"}', 'Improving the quality of patient care requires adequate staffing levels and ongoing professional training.', '早期检测是提高许多疾病治愈率的关键因素。', '{"medical care","healthcare delivery","clinical care"}', '{"发现","查出","诊断"}', '{"patient 发音 /ˈpeɪʃnt/，不是 patience /ˈpeɪʃəns/（耐心）"}', 'Reading: healthcare management; Listening Section 4: nursing lecture', '/dɪˈtek.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-034', 'junk food advertising', '垃圾食品广告', 'noun phrase', '6.0', 82, '{"health"}', '{"writing","speaking"}', '{"ban junk food advertising","restrict junk food advertising","targeted junk food advertising","exposure to junk food advertising"}', '{"炎症","通货膨胀","慢性炎症","抗炎"}', 'Many health experts argue that junk food advertising aimed at children should be strictly regulated.', '慢性炎症与许多现代疾病包括心脏病和糖尿病有关。', '{"fast food advertising","unhealthy food advertising","food marketing to children"}', '{"发炎","红肿","炎症反应"}', '{"junk food 不可数；泛指垃圾食品时不加 s"}', 'Writing Task 2: advertising / children''s health; Speaking Part 3: consumer culture', '/ɪnˈfleɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-035', 'calorie intake', '卡路里摄入', 'noun phrase', '6.0', 75, '{"health"}', '{"reading","writing"}', '{"reduce calorie intake","excessive calorie intake","daily calorie intake","monitor calorie intake"}', '{"屈肌","髋屈肌","屈肌伸展","腕屈肌"}', 'Reducing daily calorie intake combined with regular exercise is the most effective weight loss strategy.', '长时间坐着会导致髋屈肌变得紧张和缩短。', '{"caloric intake","energy intake","dietary energy consumption"}', '{"屈曲肌肉","收缩肌","弯曲肌"}', '{"calorie 可数；常用复数 calories"}', 'Reading: nutrition / health studies; Writing Task 1: dietary data', '/ˈflɛk.sər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-036', 'mental resilience', '心理韧性', 'noun phrase', '6.5', 73, '{"health"}', '{"writing","speaking"}', '{"build mental resilience","develop mental resilience","lack of mental resilience","enhance mental resilience"}', '{"卫生","个人卫生","口腔卫生","卫生习惯"}', 'Building mental resilience helps individuals cope effectively with stress, adversity, and life challenges.', '良好的个人卫生是预防感染性疾病的第一道防线。', '{"psychological resilience","emotional resilience","mental toughness"}', '{"卫生","清洁","保健"}', '{"resilience 来自动词 resile（回弹）；发音 /rɪˈzɪliəns/"}', 'Writing Task 2: education / mental health; Speaking Part 3: coping with challenges', '/haɪˈdʒiːn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-037', 'disease prevention', '疾病预防', 'noun phrase', '6.5', 87, '{"health"}', '{"reading","writing"}', '{"focus on disease prevention","effective disease prevention","disease prevention strategy","prioritize disease prevention"}', '{"癫痫","癫痫发作","癫痫治疗","癫痫患者"}', 'Governments should shift their healthcare focus from treatment to disease prevention through public health campaigns.', '癫痫是一种神经系统疾病，需要持续的医疗管理和治疗。', '{"illness prevention","prevention of disease","prophylactic care"}', '{"羊痫风","抽搐症","羊角风"}', '{"prevention 不可数；prevention of + 名词 或 disease prevention"}', 'Writing Task 2: healthcare priorities; Reading: public health policy', '/ˈep.aɪˌlɛp.si/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-038', 'health inequality', '健康不平等', 'noun phrase', '6.5', 77, '{"health"}', '{"reading","writing"}', '{"address health inequality","social health inequality","reduce health inequality","persistent health inequality"}', '{"排泄","排泄系统","废物排泄","排泄功能"}', 'Health inequality persists between rich and poor communities even within the same city.', '肾脏在人体的废物排泄和体液平衡中起着关键作用。', '{"health disparity","health gap","health inequity"}', '{"排泄","排出","分泌排出"}', '{"inequality 和 inequity 的区别：inequality = 客观不平等，inequity = 不公平（有道德判断）"}', 'Reading: social medicine / public health; Writing Task 2: social justice', '/ɪkˈskriː.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-039', 'contagious disease', '传染病', 'noun phrase', '6.0', 67, '{"health"}', '{"reading","listening"}', '{"spread of contagious disease","highly contagious disease","outbreak of a contagious disease","control contagious disease"}', '{"视觉的","光学的","光学仪器","视神经"}', 'Good hygiene practices are essential for preventing the spread of contagious diseases in schools and workplaces.', '定期进行视力检查可以及早发现视力健康问题。', '{"infectious disease","communicable disease","transmissible disease"}', '{"视力的","光学的","视觉器官的"}', '{"contagious 指接触传播；infectious 范围更广（包括空气/水传播）"}', 'Reading: public health; Listening Section 4: epidemiology lecture', '/ˈɒp.tɪ.kəl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-040', 'prescription drug', '处方药', 'noun phrase', '6.0', 62, '{"health"}', '{"reading","listening"}', '{"take prescription drugs","over-the-counter vs prescription drugs","cost of prescription drugs","prescription drug abuse"}', '{"排泄","分泌出","排出","排泄废物"}', 'The rising cost of prescription drugs has made essential medications unaffordable for many patients.', '运动后身体通过汗液排出一部分盐分和水分。', '{"prescription medication","prescribed medicine","Rx drug"}', '{"排出","分泌","排泄出"}', '{"prescription 拼写注意 scrip；区别于 subscription（订阅）"}', 'Reading: health economics; Listening Section 3: pharmacy consultation', '/ekˈskriːt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-041', 'genetic disorder', '遗传疾病', 'noun phrase', '6.5', 59, '{"health"}', '{"reading","listening"}', '{"inherited genetic disorder","diagnose a genetic disorder","rare genetic disorder","carrier of a genetic disorder"}', '{"肿胀","关节肿胀","减轻肿胀","肿胀部位"}', 'Advances in gene therapy offer new hope for treating previously incurable genetic disorders.', '脚踝肿胀可能是由于长时间站立或潜在的健康问题引起的。', '{"hereditary disease","congenital disorder","inherited condition"}', '{"浮肿","水肿","肿起"}', '{"genetic (遗传的) 和 hereditary (家族遗传) 有细微区别"}', 'Reading: medical / science articles; Listening Section 4: biology lecture', '/ˈswel.ɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-042', 'first aid', '急救', 'noun phrase', '5.5', 63, '{"health"}', '{"speaking","listening"}', '{"administer first aid","basic first aid","first aid training","first aid kit"}', '{"时髦的","流行趋势","时尚饮食","最新潮流"}', 'Learning basic first aid should be a mandatory part of the school curriculum.', '不要盲目追求时髦的饮食方式，科学的均衡营养才是关键。', '{"emergency care","immediate assistance","emergency treatment"}', '{"时尚的","流行的","前卫的"}', '{"first aid 不加 the；不可数概念"}', 'Speaking Part 2: describe a useful skill; Listening Section 2: first aid course', '/ˈtren.di/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-043', 'premature death', '过早死亡', 'noun phrase', '6.5', 61, '{"health"}', '{"reading","writing"}', '{"prevent premature death","risk of premature death","cause premature death","reduce premature death rates"}', '{"甜味剂","人造甜味剂","天然甜味剂","低热量甜味剂"}', 'Smoking is the leading cause of preventable premature death worldwide.', '人造甜味剂虽然不含热量，但长期使用可能对肠道菌群有影响。', '{"early mortality","untimely death","premature mortality"}', '{"代糖","甜味料","甘味剂"}', '{"premature 发音 /ˈpremətʃə(r)/；来自 pre（前）+ mature（成熟）"}', 'Writing Task 2: smoking / public health; Reading: health statistics', '/ˈswiː.tən.ər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-044', 'rehabilitation centre', '康复中心', 'noun phrase', '6.0', 55, '{"health"}', '{"listening","reading"}', '{"attend a rehabilitation centre","drug rehabilitation centre","inpatient rehabilitation centre","referral to a rehabilitation centre"}', '{"甜的","甜食","糖果","甜饮料"}', 'The rehabilitation centre offers comprehensive programmes for patients recovering from serious injuries or addiction.', '减少甜食和含糖饮料的摄入是维持健康体重的重要步骤。', '{"rehab facility","recovery centre","treatment centre"}', '{"含糖的","甘甜的","高糖的"}', '{"rehabilitation 常缩略为 rehab（口语）；正式写作中用全称"}', 'Listening Section 2: facility tour; Reading: health services', '/swiːt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-045', 'dietary supplement', '膳食补充剂', 'noun phrase', '6.0', 57, '{"health"}', '{"reading","listening"}', '{"take dietary supplements","natural dietary supplement","vitamin dietary supplement","use of dietary supplements"}', '{"脂肪","饱和脂肪","不健康脂肪","身体脂肪"}', 'While dietary supplements can fill nutritional gaps, they are no substitute for a healthy balanced diet.', '并非所有脂肪都是坏的，不饱和脂肪对心脏健康有益。', '{"food supplement","nutritional supplement","health supplement"}', '{"脂类","油脂","脂肪组织"}', '{"supplement 不是 replacement（替代品）；supplement 是补充"}', 'Reading: nutrition / health; Listening Section 3: health advice', '/fæt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-046', 'holistic approach', '整体方法', 'noun phrase', '6.5', 58, '{"health"}', '{"writing","speaking"}', '{"take a holistic approach","holistic approach to health","adopt a holistic approach","holistic treatment approach"}', '{"钠","钠摄入量","低钠饮食","钠含量"}', 'A holistic approach to healthcare addresses not only physical symptoms but also mental and social factors.', '摄入过多的钠是导致高血压的主要饮食因素之一。', '{"comprehensive approach","integrated approach","whole-person approach"}', '{"钠元素","盐分","食盐成分"}', '{"holistic 来自 whole；发音 /həʊˈlɪstɪk/，h不发音的现象已过时"}', 'Writing Task 2: healthcare reform; Speaking Part 3: alternative medicine', '/ˈsəʊ.di.əm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-047', 'hygiene practice', '卫生习惯', 'noun phrase', '5.5', 66, '{"health"}', '{"writing","speaking"}', '{"good hygiene practice","personal hygiene practice","poor hygiene practice","promote hygiene practice"}', '{"钙","钙摄入","钙补充剂","钙质"}', 'Teaching children good hygiene practices from an early age helps prevent the spread of infectious diseases.', '钙质对骨骼健康和预防骨质疏松至关重要。', '{"sanitary practice","cleanliness habit","hygienic behaviour"}', '{"钙元素","钙质","骨矿物质"}', '{"hygiene 不可数；发音 /ˈhaɪdʒiːn/"}', 'Writing Task 2: public health / education; Speaking Part 3: health in schools', '/ˈkæl.si.əm/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-048', 'health indicator', '健康指标', 'noun phrase', '6.0', 53, '{"health"}', '{"reading","listening"}', '{"key health indicator","measure health indicators","health indicator data","vital health indicators"}', '{"露营","训练营","夏令营","营地"}', 'Life expectancy and infant mortality are two of the most commonly used health indicators.', '参加健身训练营是快速启动健康生活方式的好方法。', '{"health metric","health measure","wellness indicator"}', '{"营地","野外营地","集训营"}', '{"indicator 可数；key/important indicator of + 名词"}', 'Writing Task 1: health data; Listening Section 4: public health lecture', '/kæmp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-049', 'quality of life', '生活质量', 'noun phrase', '6.5', 69, '{"health"}', '{"writing","speaking"}', '{"improve quality of life","overall quality of life","diminished quality of life","enhance quality of life"}', '{"微生物","肠道微生物","微生物群落","有益微生物"}', 'Access to green spaces and recreational facilities significantly improves residents'' quality of life.', '肠道微生物对人体消化和免疫系统功能有着深远的影响。', '{"standard of living","life quality","well-being"}', '{"细菌","微生物","微菌"}', '{"quality of life 缩写 QoL；注意区别于 standard of living（偏经济指标）"}', 'Writing Task 2: urban planning / healthcare; Speaking Part 3: happiness / well-being', '/ˈmaɪ.krəʊb/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('health-050', 'addictive behaviour', '成瘾行为', 'noun phrase', '6.5', 56, '{"health"}', '{"reading","writing"}', '{"exhibit addictive behaviour","treat addictive behaviour","signs of addictive behaviour","compulsive addictive behaviour"}', '{"显微镜","电子显微镜","在显微镜下观察","显微镜检查"}', 'Social media platforms are designed to encourage addictive behaviour and maximize user engagement.', '在显微镜下，我们可以看到肉眼无法察觉的微生物世界。', '{"dependency behaviour","compulsive behaviour","habit-forming behaviour"}', '{"显微镜","显微仪器","放大镜"}', '{"addictive 是形容词（令人上瘾的）；addicted 是过去分词形容词（已上瘾的）"}', 'Reading: psychology / technology; Writing Task 2: social media impact', '/ˈmɑɪ.krə.skəʊp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-002', 'urban development', '城市发展', 'noun phrase', '6.5', 98, '{"city"}', '{"writing","speaking"}', '{"rapid urban development","unsustainable urban development","plan urban development","urban development project"}', '{"基础设施建设","改善基础设施","城市基础设施","基础设施投资"}', 'Rapid urban development has placed enormous pressure on existing infrastructure and public services.', '完善的基础设施是城市经济繁荣和居民生活质量的基础。', '{"city development","urban growth","metropolitan development"}', '{"城市设施","基础建设","公共设施"}', '{"urban 是形容词；泛指城市相关的。比较 city（名词）"}', 'Writing Task 2: urbanization / city planning; Speaking Part 3: hometown changes', '/ˈɪn.frəˌstrʌk.tʃər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-003', 'traffic congestion', '交通拥堵', 'noun phrase', '6.0', 99, '{"city"}', '{"writing","speaking"}', '{"ease traffic congestion","severe traffic congestion","reduce traffic congestion","stuck in traffic congestion"}', '{"公共交通","使用公共交通","公共交通系统","公共交通改善"}', 'Traffic congestion in major cities costs billions in lost productivity and contributes to air pollution.', '高效便捷的公共交通是减少城市交通拥堵的关键。', '{"traffic jams","gridlock","heavy traffic"}', '{"大众运输","公交系统","公共交通网"}', '{"congestion 不可数；heavy/severe traffic congestion 是固定搭配"}', 'Writing Task 2: transport / urban problems; Speaking Part 1: hometown', '/ˈpʌb.lɪk ˈtræn.spɔːrt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-004', 'public transportation system', '公共交通系统', 'noun phrase', '6.0', 96, '{"city"}', '{"writing","speaking"}', '{"reliable public transportation system","invest in the public transportation system","efficient public transportation system","expand the public transportation system"}', '{"交通拥堵","缓解交通拥堵","严重的交通拥堵","交通拥堵收费"}', 'An efficient public transportation system is the backbone of any sustainable city.', '交通拥堵不仅浪费时间，还加剧了空气污染和能源消耗。', '{"mass transit system","public transport network","transit system"}', '{"交通堵塞","塞车","道路拥堵"}', '{"transportation (US) = transport (UK)；IELTS 两种用法均接受"}', 'Writing Task 2: urban infrastructure; Speaking Part 3: city improvements', '/ˈtræf.ɪk kənˈdʒes.tʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-005', 'infrastructure investment', '基础设施投资', 'noun phrase', '6.5', 95, '{"city"}', '{"reading","writing"}', '{"increase infrastructure investment","public infrastructure investment","massive infrastructure investment","infrastructure investment project"}', '{"住房可负担性","住房可负担性问题","改善住房可负担性","住房可负担性危机"}', 'Sustained infrastructure investment is critical for supporting economic growth and improving living standards.', '住房可负担性已成为许多大城市年轻一代面临的最大挑战。', '{"capital investment","infrastructure spending","public works investment"}', '{"住房负担能力","购房压力","房价可承受"}', '{"infrastructure 不可数；注意拼写 infra + structure"}', 'Writing Task 2: government spending; Reading: economic development', '/ˈhaʊ.zɪŋ əˌfɔːr.dəˈbɪl.ə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-006', 'housing market', '住房市场', 'noun phrase', '6.0', 94, '{"city"}', '{"writing","speaking"}', '{"overheated housing market","affordable housing market","housing market crash","regulate the housing market"}', '{"高层建筑","建造高层建筑","高层住宅楼","高层商业楼"}', 'The housing market in many major cities has become increasingly unaffordable for young first-time buyers.', '高层建筑是在有限土地上容纳更多人口的有效方式。', '{"property market","real estate market","residential market"}', '{"摩天楼","大厦","超高层建筑"}', '{"housing 不可数；泛指住房；house 是可数名词"}', 'Writing Task 2: housing affordability; Speaking Part 3: cost of living', '/haɪ raɪz ˈbɪl.dɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-007', 'sustainable city', '可持续城市', 'noun phrase', '6.5', 91, '{"city"}', '{"writing","speaking"}', '{"build a sustainable city","design sustainable cities","sustainable city initiative","vision of a sustainable city"}', '{"郊区","住在郊区","郊区发展","城市郊区"}', 'A sustainable city balances economic growth with environmental protection and social equity.', '许多家庭选择搬到郊区以寻求更大的居住空间和更好的环境。', '{"eco-city","green city","livable city"}', '{"城郊","近郊","市郊"}', '{"sustainable 来自动词 sustain；注意 -able 后缀表示 ''能够...的''"}', 'Writing Task 2: urban planning / environment; Speaking Part 3: future cities', '/ˈsʌb.ɜːb/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-008', 'city dweller', '城市居民', 'noun phrase', '6.0', 95, '{"city"}', '{"writing","speaking"}', '{"modern city dweller","city dwellers face challenges","majority of city dwellers","urban city dweller"}', '{"大都市","大都市区","大都市生活","大都市发展"}', 'City dwellers often face higher living costs but also enjoy greater access to cultural and entertainment facilities.', '大都市通常提供更多的工作机会和文化娱乐选择。', '{"urban resident","city inhabitant","townspeople"}', '{"大城市的","都会的","都市的"}', '{"dweller 来自 dwell（居住）；city dweller 是固定搭配，不说 city liver"}', 'Writing Task 2: urban life; Speaking Part 1: hometown', '/ˌmet.rəˈpɒl.ɪ.tən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-009', 'residential area', '住宅区', 'noun phrase', '5.5', 93, '{"city"}', '{"speaking","listening"}', '{"quiet residential area","suburban residential area","high-density residential area","live in a residential area"}', '{"人口密度","高人口密度","人口密度增加","降低人口密度"}', 'The new residential area on the outskirts of the city offers more space but limited public transport links.', '高人口密度城市在公共卫生危机期间面临独特的挑战。', '{"housing estate","neighbourhood","residential district"}', '{"人口集中度","居住密度","人口稠密"}', '{"residential 是 reside 的形容词形式；发音重音在 den"}', 'Speaking Part 1: accommodation; Listening Section 1: accommodation inquiry', '/ˌpɒp.jʊˈleɪ.ʃən ˈden.sɪ.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-010', 'urban planning', '城市规划', 'noun phrase', '6.5', 94, '{"city"}', '{"reading","writing"}', '{"poor urban planning","effective urban planning","urban planning policy","modern urban planning"}', '{"交通高峰时段","避开高峰时段","早高峰时段","高峰时段交通"}', 'Effective urban planning can alleviate many of the problems associated with rapid urbanization.', '在高峰时段通勤往往需要花费正常时间的两倍以上。', '{"city planning","town planning","municipal planning"}', '{"交通高峰期","繁忙时段","人流高峰"}', '{"urban planning 不加 the；泛指学科/活动"}', 'Reading: urban studies; Writing Task 2: city development', '/rʌʃ aʊər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-011', 'public facilities', '公共设施', 'noun phrase', '6.0', 92, '{"city"}', '{"writing","speaking"}', '{"access to public facilities","improve public facilities","lack of public facilities","invest in public facilities"}', '{"绿地","增加绿地","城市绿地","公共绿地"}', 'Investment in public facilities such as libraries, parks, and sports centres greatly enhances community well-being.', '城市绿地不仅美化环境，还为居民提供了休闲和社交的场所。', '{"public amenities","community facilities","civic facilities"}', '{"绿化地带","公园绿地","开放空间"}', '{"facilities 常用复数；指设备、设施的整体"}', 'Writing Task 2: public spending / quality of life; Speaking Part 3: community', '/ɡriːn speɪs/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-012', 'commercial district', '商业区', 'noun phrase', '6.0', 90, '{"city"}', '{"speaking","listening"}', '{"bustling commercial district","central commercial district","modern commercial district","located in the commercial district"}', '{"城市规划","可持续的城市规划","城市规划政策","城市规划和设计"}', 'The commercial district has undergone significant redevelopment, attracting new businesses and shoppers.', '良好的城市规划应平衡经济发展与环境保护和社会公平。', '{"business district","shopping district","downtown area"}', '{"城市规划","城市设计","城镇布局"}', '{"commercial 发音 /kəˈmɜːʃl/；来自 commerce（商业）"}', 'Speaking Part 1: hometown; Listening Section 1: city tour information', '/ˈɜː.bən ˈplæn.ɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-013', 'green space', '绿地', 'noun phrase', '5.5', 96, '{"city"}', '{"writing","speaking"}', '{"preserve green space","lack of green space","create more green spaces","urban green space"}', '{"智慧城市","智慧城市建设","智慧城市技术","未来的智慧城市"}', 'Preserving urban green spaces is essential for residents'' physical and mental well-being.', '智慧城市利用数字技术提高城市服务的效率和居民的生活质量。', '{"parkland","open space","green area"}', '{"智能城市","智慧都市","科技城市"}', '{"green space 可数（a green space）也可集合名词；urban green spaces 更常用"}', 'Writing Task 2: urban environment / quality of life; Speaking Part 3: city vs countryside', '/smɑːrt ˈsɪt.i/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-014', 'smart city', '智慧城市', 'noun phrase', '6.5', 92, '{"city"}', '{"reading","writing"}', '{"develop a smart city","smart city technology","smart city initiative","build smart cities"}', '{"文化多样性","促进文化多样性","丰富的文化多样性","尊重文化多样性"}', 'Smart city technologies use data and sensors to improve traffic flow, energy efficiency, and public safety.', '文化多样性使城市成为充满活力和创造力的中心。', '{"intelligent city","digital city","connected city"}', '{"文化多元性","文化丰富性","多样文化"}', '{"smart city 新兴概念，2010年代后广泛使用"}', 'Reading: technology / urban studies; Writing Task 2: future cities', '/ˈkʌl.tʃər.əl daɪˈvɜː.sə.ti/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-015', 'public amenity', '公共便利设施', 'noun phrase', '6.5', 90, '{"city"}', '{"reading","writing"}', '{"provide public amenities","essential public amenities","access to public amenities","investment in public amenities"}', '{"生活成本","高昂的生活成本","生活成本上升","降低生活成本"}', 'Adequate public amenities such as clean water supply and sanitation are fundamental to a healthy urban environment.', '大城市的高生活成本是许多年轻人外出谋生的主要障碍。', '{"public service","civic amenity","community facility"}', '{"生活费","居住成本","生活开支"}', '{"amenity 发音 /əˈmiːnəti/；可数名词，复数 amenities 更常用"}', 'Reading: urban development reports; Writing Task 2: living standards', '/kɒst əv ˈlɪv.ɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-016', 'population density', '人口密度', 'noun phrase', '6.5', 97, '{"city"}', '{"reading","writing"}', '{"high population density","low population density","increase population density","reduce population density"}', '{"市政","市政府","市政服务","市政选举"}', 'High population density in city centres creates challenges for housing, transport, and public health.', '市政府负责提供垃圾收集、道路维护等基本公共服务。', '{"population concentration","density of population","crowding level"}', '{"城市的","市政府的","市立的"}', '{"density 形容词形式 dense（密集的）；不说 dense population density（重复）"}', 'Writing Task 1: demographic data; Writing Task 2: urban planning', '/mjuːˈnɪs.ɪ.pəl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-017', 'road network', '道路网络', 'noun phrase', '6.0', 91, '{"city"}', '{"reading","listening"}', '{"extensive road network","well-developed road network","expand the road network","congested road network"}', '{"住宅区","安静的住宅区","位于住宅区","规划住宅区"}', 'An efficient road network is vital for the smooth flow of goods and people within a city.', '这个安静的住宅区距离市中心只有20分钟的地铁路程。', '{"street network","highway system","transport network"}', '{"居住区","住宅区域","居民区"}', '{"road network 中 network 可数；a road network / road networks"}', 'Reading: infrastructure; Listening Section 2: traffic report', '/ˌrez.ɪˈden.ʃəl ˈeə.ri.ə/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-018', 'city council', '市议会', 'noun phrase', '5.5', 90, '{"city"}', '{"speaking","listening"}', '{"local city council","city council election","city council member","run for city council"}', '{"商业区","繁华的商业区","主要商业区","市中心商业区"}', 'The city council has approved a new five-year plan to expand cycling lanes and pedestrian zones.', '商业区聚集了大量的办公楼、商店和餐馆。', '{"municipal council","town council","local council"}', '{"商业中心","商贸区","商务区"}', '{"council 和 counsel 区分：council = 议会/委员会，counsel = 忠告/律师"}', 'Speaking Part 3: local government; Listening Section 2: community announcement', '/kəˈmɜː.ʃəl ˈdɪs.trɪkt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-019', 'urban sprawl', '城市蔓延（无序扩张）', 'noun phrase', '6.5', 93, '{"city"}', '{"reading","writing"}', '{"uncontrolled urban sprawl","limit urban sprawl","consequences of urban sprawl","suburban sprawl"}', '{"便利设施","公共设施","现代化设施","生活设施"}', 'Urban sprawl leads to the loss of farmland, increased car dependency, and higher infrastructure costs.', '良好的社区便利设施包括超市、学校、医院和休闲场所。', '{"suburban sprawl","urban expansion","metropolitan sprawl"}', '{"公共设施","基础设施","便民设施"}', '{"sprawl 通常带负面含义（无序扩张）；与 planned expansion（有序扩张）对比"}', 'Reading: environmental / urban studies; Writing Task 2: city development', '/əˈmiː.nə.tiz/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-020', 'downtown area', '市中心区域', 'noun phrase', '5.5', 92, '{"city"}', '{"speaking","listening"}', '{"bustling downtown area","downtown area attractions","shopping in the downtown area","revitalized downtown area"}', '{"过度拥挤","监狱过度拥挤","过度拥挤的城市","缓解过度拥挤"}', 'The downtown area has been revitalized with new shops, restaurants, and cultural venues.', '过度拥挤是许多大城市面临的社会和健康问题之一。', '{"city centre","town centre","central business district"}', '{"拥挤不堪","人口过剩","过于拥挤"}', '{"downtown 主要北美用法；city/town centre 英国用法；两者 IELTS 均可"}', 'Speaking Part 1: hometown; Listening Section 1: tourist information', '/ˌəʊ.vəˈkraʊ.dɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-021', 'municipal services', '市政服务', 'noun phrase', '6.5', 90, '{"city"}', '{"reading","writing"}', '{"provide municipal services","essential municipal services","improve municipal services","access to municipal services"}', '{"夜生活","丰富的夜生活","夜生活场所","夜生活区"}', 'Efficient municipal services such as waste collection and water supply are taken for granted in most developed cities.', '这个城市以丰富多彩的夜生活和娱乐场所而闻名。', '{"council services","city services","local government services"}', '{"夜生活","夜间娱乐","夜市生活"}', '{"municipal 发音 /mjuːˈnɪsɪpl/；来自拉丁语 municipium（自治市）"}', 'Writing Task 2: local government responsibility; Reading: public administration', '/ˈnaɪt.laɪf/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-022', 'pedestrian zone', '步行区', 'noun phrase', '6.0', 83, '{"city"}', '{"writing","speaking"}', '{"create pedestrian zones","car-free pedestrian zone","expand pedestrian zones","shopping pedestrian zone"}', '{"停车","停车场","停车位","停车费"}', 'Creating more pedestrian zones in city centres encourages walking, reduces pollution, and boosts local businesses.', '在市中心找停车位是许多驾车通勤者每天的烦恼。', '{"pedestrian area","walking zone","car-free area"}', '{"泊车","停放车辆","汽车停放"}', '{"pedestrian 拼写注意 pedes-，来自拉丁语 pes（脚）"}', 'Writing Task 2: urban design / environment; Speaking Part 3: city improvements', '/ˈpɑːr.kɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-023', 'rush hour', '高峰时段', 'noun phrase', '5.5', 88, '{"city"}', '{"speaking","listening"}', '{"during rush hour","morning rush hour","avoid the rush hour","rush hour traffic"}', '{"农村地区","农村发展","农村生活","农村社区"}', 'The city''s metro system carries over a million commuters during the morning rush hour alone.', '政府正在采取措施缩小城乡之间在医疗和教育上的差距。', '{"peak hour","peak time","busy hour"}', '{"乡村地区","农村地带","乡间"}', '{"rush hour 可数；during the rush hour 或 during rush hour 均可"}', 'Speaking Part 1: daily routine; Listening Section 1: travel schedule', '/ˈruːr.əl ˈeə.ri.ə/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-024', 'housing shortage', '住房短缺', 'noun phrase', '6.0', 84, '{"city"}', '{"writing","speaking"}', '{"severe housing shortage","acute housing shortage","address the housing shortage","chronic housing shortage"}', '{"地铁","坐地铁","地铁站","地铁线路"}', 'A severe housing shortage in major cities has pushed property prices and rents to record levels.', '地铁是大城市中最快速、最可靠的公共交通方式之一。', '{"housing crisis","housing deficit","lack of housing"}', '{"地下铁","地铁系统","轨道交通"}', '{"shortage 可数；a shortage of + 名词 / housing shortage"}', 'Writing Task 2: housing policy / urbanization; Speaking Part 3: cost of living', '/ˈsʌb.wɛr/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-025', 'metropolitan area', '大都市区域', 'noun phrase', '6.0', 82, '{"city"}', '{"reading","listening"}', '{"greater metropolitan area","in the metropolitan area","wider metropolitan area","metropolitan area population"}', '{"摩天大楼","建造摩天大楼","摩天大楼群","标志性摩天大楼"}', 'The greater metropolitan area now extends over 100 kilometres from the original city centre.', '城市天际线上那些令人印象深刻的摩天大楼象征着经济繁荣。', '{"conurbation","metro area","urban agglomeration"}', '{"摩天大厦","高层地标","巨厦"}', '{"metropolitan 发音 /ˌmetrəˈpɒlɪtən/；metropolis = 大都市"}', 'Reading: urban geography; Listening Section 2: regional news', '/skai.skreɪ.pər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-026', 'traffic regulation', '交通管制', 'noun phrase', '6.0', 76, '{"city"}', '{"reading","listening"}', '{"enforce traffic regulations","strict traffic regulation","violate traffic regulations","obey traffic regulations"}', '{"光污染","减少光污染","城市光污染","光污染问题"}', 'Strict traffic regulations combined with heavy fines have significantly reduced road accidents in the city.', '城市光污染不仅浪费能源，还影响野生动物的自然周期。', '{"traffic law","traffic rule","road regulation"}', '{"光污染","人工照明污染","夜间光害"}', '{"regulation 常用复数 regulations；traffic regulation 作为系统概念时可用单数"}', 'Reading: urban management; Listening Section 2: traffic announcement', '/ˈlaɪt ˌpɒlˈuː.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-027', 'street vendor', '街头小贩', 'noun phrase', '5.5', 78, '{"city"}', '{"speaking","listening"}', '{"licensed street vendor","illegal street vendor","street vendor selling food","ban street vendors"}', '{"人行道","在街上","走人行道","人行道咖啡座"}', 'Street vendors add vibrancy to city life but also pose challenges for sanitation and traffic management.', '宽敞整洁的人行道鼓励更多的人选择步行而非驾车出行。', '{"hawker","street seller","market stall trader"}', '{"人行便道","步道","走道"}', '{"vendor 发音 /ˈvendə(r)/；来自拉丁语 vendere（卖）"}', 'Speaking Part 3: city life / informal economy; Listening Section 1: city walk', '/ˈsaɪd.wɔːk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-028', 'urban infrastructure', '城市基础设施', 'noun phrase', '6.5', 86, '{"city"}', '{"reading","writing"}', '{"aging urban infrastructure","invest in urban infrastructure","improve urban infrastructure","urban infrastructure project"}', '{"景观","城市景观","景观设计","自然景观"}', 'Aging urban infrastructure in many older cities requires massive investment to meet modern standards.', '精心设计的城市景观可以提升居民的生活质量和幸福感。', '{"city infrastructure","municipal infrastructure","metropolitan infrastructure"}', '{"风景","景色","地貌"}', '{"infrastructure 不可数；常用搭配：critical / essential infrastructure"}', 'Reading: urban development; Writing Task 2: government investment', '/ˈlænd.skeɪp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-029', 'urban regeneration', '城市更新', 'noun phrase', '6.5', 79, '{"city"}', '{"reading","writing"}', '{"undergo urban regeneration","urban regeneration project","urban regeneration scheme","fund urban regeneration"}', '{"凉亭","展览馆","运动场看台","园区亭阁"}', 'Urban regeneration projects have transformed derelict industrial areas into vibrant residential and cultural quarters.', '公园内新建的凉亭成为居民休息和社交的热门场所。', '{"urban renewal","city revitalization","urban redevelopment"}', '{"亭子","展馆","阁楼"}', '{"regeneration 来自 re（重新）+ generate（生成）；不可数"}', 'Reading: urban studies; Writing Task 2: city development', '/ˈpæv.ɪlj.ən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-030', 'shopping mall', '购物中心', 'noun phrase', '5.5', 81, '{"city"}', '{"speaking","listening"}', '{"huge shopping mall","visit the shopping mall","shopping mall complex","out-of-town shopping mall"}', '{"飞行员","航空先驱","飞行爱好者","试飞员"}', 'The rise of online shopping has threatened the traditional business model of large shopping malls.', '飞行员需要经过多年严格的训练才能驾驶商业航班。', '{"shopping centre","retail centre","mall"}', '{"飞行驾驶员","飞机师","航空员"}', '{"mall 发音 /mɔːl/ 或 /mæl/（美式）"}', 'Speaking Part 1: leisure / shopping; Listening Section 1: directions', '/ˈeɪ.vi.eɪ.tər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-031', 'bicycle lane', '自行车道', 'noun phrase', '5.5', 80, '{"city"}', '{"writing","speaking"}', '{"dedicated bicycle lane","build more bicycle lanes","separated bicycle lane","network of bicycle lanes"}', '{"阁楼","在阁楼上","阁楼空间","改建阁楼"}', 'Investing in safe bicycle lanes encourages more people to cycle, reducing both congestion and pollution.', '他们将阁楼改造成了一间温馨的客卧。', '{"cycle lane","bike lane","cycling path"}', '{"顶楼空间","屋顶空间","阁楼层"}', '{"bicycle 可缩写为 bike；lane 强调道路上的划线车道"}', 'Writing Task 2: green transport; Speaking Part 3: city transport', '/ˈæt.ɪk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-032', 'living standard', '生活水平', 'noun phrase', '6.0', 87, '{"city"}', '{"writing","speaking"}', '{"improve living standards","high living standard","declining living standard","raise living standards"}', '{"地下室","地下室公寓","地下停车场","在地下室"}', 'Good urban planning can significantly improve living standards for all city residents.', '许多老建筑的地下室被改造成时尚的酒吧和咖啡厅。', '{"standard of living","quality of life","living condition"}', '{"地库","地下层","地窖"}', '{"living standards（复数）比 living standard（单数）更常用"}', 'Writing Task 2: urban quality of life; Speaking Part 3: city vs countryside', '/beɪs.mənt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-033', 'commuting distance', '通勤距离', 'noun phrase', '5.5', 74, '{"city"}', '{"speaking","writing"}', '{"long commuting distance","average commuting distance","reduce commuting distance","acceptable commuting distance"}', '{"跑步者","马拉松跑步者","晨跑的人","跑道"}', 'Long commuting distances are a major source of stress and reduced leisure time for city workers.', '清晨的公园里总是有很多跑步者在锻炼。', '{"travel distance to work","journey distance","commute length"}', '{"跑者","慢跑者","赛跑者"}', '{"commute 作名词可数；a long commute / my daily commute"}', 'Speaking Part 1: daily routine; Writing Task 2: work-life balance', '/ˈrʌn.ər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-034', 'public security', '公共安全', 'noun phrase', '6.0', 79, '{"city"}', '{"reading","listening"}', '{"ensure public security","threaten public security","maintain public security","public security concern"}', '{"淡水","淡水资源","淡水湖","淡水供应"}', 'The installation of CCTV cameras has been justified on the grounds of improving public security.', '城市淡水资源的可持续管理对居民生活和经济发展至关重要。', '{"public safety","public order","civic security"}', '{"干净水","清水","淡水资源"}', '{"security 和 safety 区别：security 强调免受故意伤害，safety 强调免受意外伤害"}', 'Reading: urban crime; Listening Section 3: city council debate', '/ˈfreʃ.wɔː.tər/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-035', 'street lighting', '街道照明', 'noun phrase', '5.5', 72, '{"city"}', '{"speaking","listening"}', '{"adequate street lighting","poor street lighting","improve street lighting","energy-efficient street lighting"}', '{"行政区","商业区","学区","选区"}', 'Better street lighting has been demonstrated to reduce crime rates and improve pedestrian safety at night.', '每个行政区都有自己的特色和文化底蕴。', '{"road lighting","public lighting","street illumination"}', '{"地区","区域","行政区划"}', '{"lighting 不可数；street lights 指具体的灯（可数）"}', 'Speaking Part 3: neighbourhood safety; Listening Section 1: complaint', '/ˈdɪs.trɪkt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-036', 'rental market', '租赁市场', 'noun phrase', '6.0', 83, '{"city"}', '{"writing","speaking"}', '{"competitive rental market","tight rental market","regulation of the rental market","booming rental market"}', '{"社区","邻里关系","友好社区","社区服务"}', 'The rental market in the city has become so competitive that prospective tenants routinely offer above the asking price.', '一个和谐友好的社区让居民感到安全和归属感。', '{"lettings market","tenancy market","housing rental market"}', '{"邻里","街坊","住宅社区"}', '{"rental 可作形容词（租赁的）或名词（租金）"}', 'Writing Task 2: housing policy; Speaking Part 3: housing challenges', '/ˈneɪ.bər.hʊd/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-037', 'urban migration', '城市迁移（人口向城市流动）', 'noun phrase', '6.5', 80, '{"city"}', '{"reading","writing"}', '{"rural-to-urban migration","mass urban migration","drive urban migration","rapid urban migration"}', '{"促进","方便","帮助实现","推动"}', 'Rural-to-urban migration has accelerated in developing countries as people seek better employment opportunities.', '新开通的地铁线路将大大方便市民的日常通勤。', '{"urbanization","rural-urban drift","internal migration to cities"}', '{"促进","帮助","推动"}', '{"migration 是不可数名词（作为过程）或集合名词"}', 'Reading: demographic studies; Writing Task 2: urbanization causes / effects', '/ˈfæs.ɪ.leɪt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-038', 'civic engagement', '公民参与', 'noun phrase', '6.5', 71, '{"city"}', '{"reading","writing"}', '{"promote civic engagement","increase civic engagement","lack of civic engagement","community civic engagement"}', '{"自行车","骑自行车","自行车道","共享单车"}', 'Higher levels of civic engagement are associated with stronger communities and more responsive local government.', '骑自行车不仅是环保的交通方式，还是很好的运动。', '{"citizen participation","community involvement","public participation"}', '{"单车","脚踏车","自行车"}', '{"civic 是 civil 的同源词；civic 强调城市/公民事务，civil 更广泛"}', 'Reading: social studies / urban sociology; Writing Task 2: community / democracy', '/baɪˈsɪk.əl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-039', 'parking space', '停车位', 'noun phrase', '5.5', 68, '{"city"}', '{"speaking","listening"}', '{"limited parking space","shortage of parking spaces","find a parking space","designated parking space"}', '{"行人","行人安全","行人专用区","步行者"}', 'The shortage of parking spaces in the city centre has led to higher charges and increased use of public transport.', '城市应该为行人提供更多安全的步行空间和过街设施。', '{"parking spot","parking bay","car park space"}', '{"步行者","路人","行人"}', '{"parking space 可数；注意不要与 parking lot（停车场整体）混淆"}', 'Speaking Part 1: driving / transport; Listening Section 1: directions', '/ˈpiː.dɪs.tri.ən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-040', 'residential building', '住宅楼', 'noun phrase', '5.5', 67, '{"city"}', '{"speaking","listening"}', '{"high-rise residential building","modern residential building","residential building complex","new residential building"}', '{"通风","通风系统","良好通风","自然通风"}', 'The city has approved the construction of several new high-rise residential buildings to address the housing shortage.', '良好的通风对于保持室内空气质量和预防霉菌至关重要。', '{"apartment building","housing block","dwelling"}', '{"空气流通","换气","排风"}', '{"residential 和 residence 区分：residence 是名词（住所），residential 是形容词"}', 'Speaking Part 1: accommodation; Listening Section 1: property viewing', '/ˈven.tɪ.leɪ.ʃən/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-041', 'landfill site', '垃圾填埋场', 'noun phrase', '6.0', 58, '{"city"}', '{"reading","listening"}', '{"designate a landfill site","overflowing landfill site","close a landfill site","waste to landfill site"}', '{"化粪池","受感染的","腐败性","有细菌的"}', 'As landfill sites reach capacity, cities must invest in recycling and waste-to-energy technologies.', '郊区的许多房屋使用化粪池系统来处理生活废水。', '{"rubbish dump","waste disposal site","garbage dump"}', '{"腐败的","感染的","排污的"}', '{"landfill 一个词；可数（指场地）或不可数（指处理方式）"}', 'Reading: waste management; Listening Section 4: environmental lecture', '/ˈsept.ɪk/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-042', 'traffic violation', '交通违规', 'noun phrase', '5.5', 64, '{"city"}', '{"speaking","listening"}', '{"commit a traffic violation","minor traffic violation","traffic violation fine","repeat traffic violation"}', '{"饮用水","适合饮用的","饮水","饮用"}', 'Installing more traffic cameras has led to a significant decrease in traffic violations at major intersections.', '确保所有居民都能获得干净的饮用水是城市的基本责任。', '{"traffic offence","traffic infraction","driving violation"}', '{"可饮用的","饮用","饮用的"}', '{"violation 来自动词 violate；可数名词"}', 'Speaking Part 3: road safety; Listening Section 2: police announcement', '/ˈdrɪŋ.kɪŋ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-043', 'urban landscape', '城市景观', 'noun phrase', '6.0', 62, '{"city"}', '{"writing","speaking"}', '{"transforming urban landscape","modern urban landscape","dominate the urban landscape","changing urban landscape"}', '{"摊位","市场摊位","小吃摊","货摊"}', 'The proliferation of high-rise buildings has fundamentally altered the urban landscape of many Asian cities.', '这个夜市摊位卖着这座城市最好吃的街头小吃。', '{"cityscape","townscape","urban scenery"}', '{"摊位","摊贩","档口"}', '{"landscape 可数；the urban landscape 指城市总体面貌"}', 'Writing Task 1: describing places; Speaking Part 3: hometown changes', '/stɔːl/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-044', 'heritage site', '遗产地', 'noun phrase', '6.0', 60, '{"city"}', '{"reading","listening"}', '{"protect a heritage site","UNESCO World Heritage site","cultural heritage site","preserve heritage sites"}', '{"背景","城市背景","历史背景","山景背景"}', 'The city''s historic district has been designated a UNESCO World Heritage site, attracting millions of tourists annually.', '这座山为整个城市提供了壮丽的背景。', '{"historic site","cultural site","listed site"}', '{"背景","环境","布景"}', '{"heritage 不可数；a World Heritage site（可数，指具体地点）"}', 'Reading: tourism / culture; Listening Section 2: guided tour information', '/ˈbæk.drɒp/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-045', 'drainage system', '排水系统', 'noun phrase', '6.0', 56, '{"city"}', '{"reading","listening"}', '{"inadequate drainage system","improve the drainage system","urban drainage system","blocked drainage system"}', '{"衰败","城市衰败","牙齿腐烂","衰败过程"}', 'Flash flooding in the city is largely due to an outdated drainage system unable to cope with heavy rainfall.', '一些老工业区经历了衰败，但正在通过城市更新项目重获新生。', '{"sewer system","stormwater system","wastewater system"}', '{"衰退","腐蚀","老损"}', '{"drainage 来自 drain（排水）；发音 /ˈdreɪnɪdʒ/"}', 'Reading: urban infrastructure; Listening Section 4: civil engineering lecture', '/dɪˈkeɪ/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-046', 'garbage disposal', '垃圾处理', 'noun phrase', '5.5', 65, '{"city"}', '{"writing","speaking"}', '{"proper garbage disposal","illegal garbage disposal","municipal garbage disposal","garbage disposal problem"}', '{"起源","来源","原始","起点"}', 'Improper garbage disposal in rapidly growing cities poses serious health and environmental risks.', '了解一个城市的历史起源有助于理解其文化和建筑风格。', '{"waste disposal","rubbish disposal","trash disposal"}', '{"来源","起点","发祥地"}', '{"garbage (US) / rubbish (UK) / waste（正式）；IELTS 三种均可"}', 'Writing Task 2: waste management; Speaking Part 3: environmental problems', '/ˈɒr.ɪ.dʒɪn/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-047', 'noise complaint', '噪音投诉', 'noun phrase', '5.5', 52, '{"city"}', '{"speaking","listening"}', '{"file a noise complaint","noise complaint from residents","deal with noise complaints","repeated noise complaint"}', '{"大道","林荫大道","主要大道","商业大道"}', 'The council receives hundreds of noise complaints each year, mostly relating to late-night bars and construction work.', '这条宽阔的大道两旁种满了梧桐树，是城市最具标志性的街道之一。', '{"noise grievance","sound complaint","noise nuisance report"}', '{"大街","大道","林荫道"}', '{"complaint 是名词（投诉），complain 是动词；complaint about + 噪音来源"}', 'Speaking Part 3: neighbourhood problems; Listening Section 1: complaint form', '/ˈæv.ən.juː/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-048', 'pedestrian crossing', '人行横道', 'noun phrase', '5.5', 54, '{"city"}', '{"speaking","listening"}', '{"designated pedestrian crossing","use the pedestrian crossing","safe pedestrian crossing","zebra pedestrian crossing"}', '{"郊区","在城郊","城市边缘","郊区地带"}', 'Installing more signal-controlled pedestrian crossings near schools has improved safety for children.', '许多工厂和物流中心都设在城市郊区，那里地价更便宜。', '{"crosswalk","zebra crossing","foot crossing"}', '{"市郊","近郊","城边"}', '{"crossing (UK) 和 crosswalk (US)；IELTS 均可使用"}', 'Speaking Part 1: neighbourhood; Listening Section 1: giving directions', '/ˈaʊt.kɜːts/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-049', 'public art installation', '公共艺术装置', 'noun phrase', '6.0', 51, '{"city"}', '{"speaking","listening"}', '{"commission a public art installation","temporary public art installation","controversial public art installation","outdoor public art installation"}', '{"重建","重新创造","再现","复原"}', 'Public art installations can transform neglected urban spaces and foster a sense of community identity.', '城市规划者正在努力重建这个历史街区昔日的辉煌。', '{"street art","civic art","urban sculpture"}', '{"重建","复制","再现"}', '{"installation 可数；指具体艺术作品时 a public art installation"}', 'Speaking Part 3: culture / public spaces; Listening Section 2: city festival', '/ˈrek.ri.eɪt/');
INSERT INTO public.chunks (id, word, translation, part_of_speech, band_level, frequency_score, topics, modules, collocations, collocations_cn, example_sentence, example_sentence_cn, synonyms, synonyms_cn, common_mistakes, ielts_context, pronunciation) VALUES ('city-050', 'real estate developer', '房地产开发商', 'noun phrase', '6.0', 57, '{"city"}', '{"reading","writing"}', '{"commercial real estate developer","property developer","private real estate developer","real estate developer profits"}', '{"海港","港口城市","天然海港","渔港"}', 'Real estate developers have been accused of prioritizing profits over community needs and environmental considerations.', '这座海港城市因其便利的海上贸易条件而繁荣发展。', '{"property developer","land developer","housing developer"}', '{"港口","港湾","码头"}', '{"real estate 为美式英语；英式用 property；IELTS 均可"}', 'Reading: business / urban development; Writing Task 2: housing / economy', '/ˈhɑːr.bər/');
